function isDrawTool(t) { return BUILTIN_BRUSHES.some(b => b.id === t); }
// rail family for a brush id: pen-family ids map to the Pen button, pencil-family to Pencil
const BRUSH_FAMILIES = {
  pen: ['pen', 'technicalpen', 'fountainpen', 'ballpoint'],
  pencil: ['pencil', 'mechanicalpencil'],
};
function brushFamilyOf(id) {
  for (const fam in BRUSH_FAMILIES) if (BRUSH_FAMILIES[fam].includes(id)) return fam;
  return id;
}
// procedural grain tip (paper tooth) → dataURL, stamped + tinted by the brush engine
function makeGrainTip(kind) {
  const S = 64, c = document.createElement('canvas'); c.width = c.height = S;
  const x = c.getContext('2d');
  // soft radial base so stamps blend at the edges
  const g = x.createRadialGradient(S/2, S/2, 0, S/2, S/2, S/2);
  g.addColorStop(0, 'rgba(0,0,0,1)'); g.addColorStop(0.6, 'rgba(0,0,0,0.85)'); g.addColorStop(1, 'rgba(0,0,0,0)');
  x.fillStyle = g; x.beginPath(); x.arc(S/2, S/2, S/2, 0, Math.PI*2); x.fill();
  // knock out speckles to create tooth (coarse = bigger, sparser holes)
  const img = x.getImageData(0, 0, S, S), d = img.data;
  const density = kind === 'coarse' ? 0.5 : 0.32, cut = kind === 'coarse' ? 0.75 : 0.55;
  for (let i = 0; i < d.length; i += 4) {
    if (Math.random() < density) { const k = Math.random() * cut; d[i+3] = Math.round(d[i+3] * (1 - k)); }
  }
  x.putImageData(img, 0, 0);
  return c;
}
function initGrainTips() {
  BUILTIN_BRUSHES.forEach(b => {
    if (b.tipType === 'texture' && b.tipImage == null && b.grain) {
      const c = makeGrainTip(b.grain);
      const url = c.toDataURL();
      b.tipImage = url;
      state.tipImageCache[url] = c;   // store the ready canvas — no async decode gap
    }
  });
}
try { initGrainTips(); } catch (e) { /* canvas not ready yet; exitMassing/boot will retry */ }

