/* =================== TRANSFORMS =================== */
function applyStageTransform() {
  stage.style.transform = `translate(${state.panX}px, ${state.panY}px)`;
  paper.style.transform = `translate(-50%, -50%) scale(${state.zoom * state.baseZoom})`;
  document.getElementById('zoom-level').textContent = Math.round(state.zoom * 100) + '%';
  refreshMeasurements();
}

function fitToScreen() {
  const areaRect = area.getBoundingClientRect();
  const padding = 60;
  const aw = areaRect.width - padding * 2;
  const ah = areaRect.height - padding * 2;
  const aspect = DOC_W_PX / DOC_H_PX;
  let w, h;
  if (aw / ah > aspect) {
    h = ah; w = h * aspect;
  } else {
    w = aw; h = w / aspect;
  }
  paper.style.width = DOC_W_PX + 'px';
  paper.style.height = DOC_H_PX + 'px';
  state.baseZoom = w / DOC_W_PX;
  state.zoom = 1;
  state.panX = 0; state.panY = 0;
  applyStageTransform();
}

/* =================================================================
   CANVAS SIZE — resize the document, preserving artwork
   ================================================================= */
function resizeDocument(newWmm, newHmm, newDpi) {
  const oldW = DOC_W_PX, oldH = DOC_H_PX;
  DOC_W_MM = newWmm; DOC_H_MM = newHmm; DOC_DPI = newDpi;
  DOC_W_PX = Math.round(DOC_W_MM / 25.4 * DOC_DPI);
  DOC_H_PX = Math.round(DOC_H_MM / 25.4 * DOC_DPI);

  // Resize every layer's canvases, scaling existing content to the new size.
  state.layers.forEach(layer => {
    ['canvas', 'imageCanvas'].forEach(key => {
      const src = layer[key];
      if (!src) return;
      const tmp = document.createElement('canvas');
      tmp.width = oldW; tmp.height = oldH;
      tmp.getContext('2d').drawImage(src, 0, 0);
      src.width = DOC_W_PX; src.height = DOC_H_PX;
      const ctx = (key === 'canvas') ? layer.ctx : layer.imageCtx;
      ctx.clearRect(0, 0, DOC_W_PX, DOC_H_PX);
      ctx.drawImage(tmp, 0, 0, oldW, oldH, 0, 0, DOC_W_PX, DOC_H_PX);
    });
    // Reset history (snapshots are old-size ImageData)
    layer.history = [];
    layer.redo = [];
  });

  // Resize helper canvases
  strokeCanvas.width = DOC_W_PX; strokeCanvas.height = DOC_H_PX;
  const gc = document.getElementById('guide-canvas');
  gc.width = DOC_W_PX; gc.height = DOC_H_PX;

  // Update document info panel
  const fmt = paperFormatName(newWmm, newHmm);
  document.querySelectorAll('.layer-props-title').forEach(()=>{});
  const infoRows = document.querySelectorAll('#layers-panel [style*="justify-content:space-between"]');
  // Update the Document section values directly
  updateDocInfo(fmt);

  fitToScreen();
  drawDocGrid();
  if (typeof drawGuides === 'function') drawGuides();
  state.layers.forEach(l => saveSnapshot(l));
  renderLayers();
}

/* Expand canvas for infinite-scroll drawing (Morpholio Trace style). */
function expandDocumentPixels(addLeft, addTop, addRight, addBottom) {
  if (!addLeft && !addTop && !addRight && !addBottom) return;
  const oldW = DOC_W_PX, oldH = DOC_H_PX;
  const newW = oldW + addLeft + addRight;
  const newH = oldH + addTop + addBottom;
  if (newW > 24000 || newH > 24000) return;

  const shiftLayerCanvases = (layer) => {
    ['canvas', 'imageCanvas'].forEach(key => {
      const src = layer[key];
      if (!src) return;
      const tmp = document.createElement('canvas');
      tmp.width = oldW; tmp.height = oldH;
      tmp.getContext('2d').drawImage(src, 0, 0);
      src.width = newW; src.height = newH;
      const ctx = (key === 'canvas') ? layer.ctx : layer.imageCtx;
      ctx.clearRect(0, 0, newW, newH);
      ctx.drawImage(tmp, addLeft, addTop);
    });
    layer.history = [];
    layer.redo = [];
    saveSnapshot(layer);
  };

  state.layers.forEach(shiftLayerCanvases);
  strokeCanvas.width = newW; strokeCanvas.height = newH;
  const gc = document.getElementById('guide-canvas');
  if (gc) { gc.width = newW; gc.height = newH; }
  if (gridCanvas) { gridCanvas.width = newW; gridCanvas.height = newH; }

  DOC_W_PX = newW;
  DOC_H_PX = newH;
  // Keep mm-per-pixel constant so scale/measurements stay accurate after expansion
  if ((state.infiniteCanvas || state.autoExpandCanvas) && oldW > 0 && oldH > 0) {
    const mmPerPxW = DOC_W_MM / oldW;
    const mmPerPxH = DOC_H_MM / oldH;
    DOC_W_MM = newW * mmPerPxW;
    DOC_H_MM = newH * mmPerPxH;
    updateDocInfo(paperFormatName(DOC_W_MM, DOC_H_MM));
  }
  paper.style.width = DOC_W_PX + 'px';
  paper.style.height = DOC_H_PX + 'px';

  state.vanishingPoints.forEach(vp => { vp.x += addLeft; vp.y += addTop; });
  state.measurements.forEach(m => {
    if (m.x1 != null) { m.x1 += addLeft; m.y1 += addTop; }
    if (m.x2 != null) { m.x2 += addLeft; m.y2 += addTop; }
    if (m.points) m.points.forEach(p => { p.x += addLeft; p.y += addTop; });
  });
  state.walls.forEach(w => { if (w.pts) w.pts.forEach(p => { p.x += addLeft; p.y += addTop; }); });
  state.shapes.forEach(s => {
    if (s.pts) s.pts.forEach(p => { p.x += addLeft; p.y += addTop; });
    if (s.x != null) s.x += addLeft;
    if (s.y != null) s.y += addTop;
    if (s.cx != null) { s.cx += addLeft; s.cy += addTop; }
  });
  if (massing.baseAnchor) { massing.baseAnchor.px += addLeft; massing.baseAnchor.py += addTop; }

  drawDocGrid();
  if (typeof drawGuides === 'function') drawGuides();
  refreshMeasurements();
  renderLayers();
}

const CANVAS_EXPAND_PX = 900;
const CANVAS_EXPAND_THRESHOLD = 140;

function maybeExpandCanvas(x, y) {
  if (!state.infiniteCanvas && !state.autoExpandCanvas) return;
  let addL = 0, addT = 0, addR = 0, addB = 0;
  if (x < CANVAS_EXPAND_THRESHOLD) addL = CANVAS_EXPAND_PX;
  if (x > DOC_W_PX - CANVAS_EXPAND_THRESHOLD) addR = CANVAS_EXPAND_PX;
  if (y < CANVAS_EXPAND_THRESHOLD) addT = CANVAS_EXPAND_PX;
  if (y > DOC_H_PX - CANVAS_EXPAND_THRESHOLD) addB = CANVAS_EXPAND_PX;
  if (addL || addT || addR || addB) expandDocumentPixels(addL, addT, addR, addB);
}

function releaseTransientInput() {
  state.drawing = false;
  state.isPanning = false;
  state.lineDrag = null;
  if (typeof massing !== 'undefined') massing.dragging = null;
  document.body.classList.remove('nm-drawing');
  activePointers.forEach((_, id) => {
    try { if (paper.hasPointerCapture(id)) paper.releasePointerCapture(id); } catch (_) {}
    try { if (area.hasPointerCapture(id)) area.releasePointerCapture(id); } catch (_) {}
    try { if (massingCanvas && massingCanvas.hasPointerCapture(id)) massingCanvas.releasePointerCapture(id); } catch (_) {}
  });
  activePointers.clear();
  state.pinchStart = null;
}

function dismissSketchOverlays() {
  showWall2dPalette(false);
  showOpeningPalette(false);
  if (state.polyActive) {
    state.polyPoints = [];
    state.polyActive = false;
    const ph = document.getElementById('poly-hint');
    if (ph) ph.style.display = 'none';
  }
  closeGroupFlyout();
  if (_brushFlyout) _brushFlyout.style.display = 'none';
  const selBar = document.getElementById('sel-bar');
  if (selBar) selBar.classList.remove('show');
}

function paperFormatName(w, h) {
  const sizes = { '420x297':'A3', '297x210':'A4', '594x420':'A2', '841x594':'A1',
                  '279x216':'Letter', '432x279':'Tabloid' };
  const key = `${Math.round(w)}x${Math.round(h)}`;
  const rev = `${Math.round(h)}x${Math.round(w)}`;
  const name = sizes[key] || sizes[rev];
  const orient = w >= h ? 'Landscape' : 'Portrait';
  return name ? `${name} ${orient}` : `Custom`;
}

function updateDocInfo(fmt) {
  const panel = document.getElementById('layers-panel');
  const rows = panel.querySelectorAll('div[style*="space-between"]');
  rows.forEach(row => {
    const label = row.firstElementChild ? row.firstElementChild.textContent.trim() : '';
    const val = row.lastElementChild;
    if (!val) return;
    if (label === 'Format') val.textContent = fmt;
    else if (label === 'Size') val.textContent = `${DOC_W_MM} × ${DOC_H_MM} mm`;
    else if (label === 'DPI') val.textContent = String(DOC_DPI);
  });
}

// Canvas size dialog
const canvasSizeDialog = document.getElementById('canvas-size-dialog');
let _modalScrim = null;
function ensureModalScrim() {
  if (_modalScrim) return _modalScrim;
  _modalScrim = document.createElement('div');
  _modalScrim.id = 'modal-scrim';
  _modalScrim.addEventListener('click', () => closeCanvasSizeDialog());
  document.body.appendChild(_modalScrim);
  return _modalScrim;
}
function closeCanvasSizeDialog() {
  canvasSizeDialog.classList.remove('show');
  canvasSizeDialog.style.display = 'none';
  if (_modalScrim) _modalScrim.style.display = 'none';
}
function openCanvasSize() {
  releaseTransientInput();
  dismissSketchOverlays();
  if (typeof window._closeMassMenus === 'function') window._closeMassMenus();
  document.getElementById('cs-w').value = DOC_W_MM;
  document.getElementById('cs-h').value = DOC_H_MM;
  document.getElementById('cs-dpi').value = DOC_DPI;
  ensureModalScrim().style.display = 'block';
  canvasSizeDialog.style.display = 'block';
  canvasSizeDialog.classList.add('show');
  const vw = window.innerWidth, vh = window.innerHeight;
  const w = canvasSizeDialog.offsetWidth || 280;
  canvasSizeDialog.style.left = Math.max(12, (vw - w) / 2) + 'px';
  canvasSizeDialog.style.top = Math.max(72, Math.min(vh * 0.12, 120)) + 'px';
  syncCsPresets();
}
if (canvasSizeDialog) {
  canvasSizeDialog.addEventListener('pointerdown', e => e.stopPropagation());
  canvasSizeDialog.addEventListener('click', e => e.stopPropagation());
}
document.querySelectorAll('#canvas-size-dialog .cs-preset').forEach(btn => {
  btn.addEventListener('click', () => {
    document.getElementById('cs-w').value = btn.dataset.w;
    document.getElementById('cs-h').value = btn.dataset.h;
    syncCsPresets();
  });
});
function syncCsPresets() {
  const w = document.getElementById('cs-w').value, h = document.getElementById('cs-h').value;
  document.querySelectorAll('#canvas-size-dialog .cs-preset').forEach(b =>
    b.classList.toggle('active', b.dataset.w === w && b.dataset.h === h));
}
document.getElementById('cs-w').addEventListener('input', syncCsPresets);
document.getElementById('cs-h').addEventListener('input', syncCsPresets);
document.getElementById('cs-orient').addEventListener('click', () => {
  const w = document.getElementById('cs-w'), h = document.getElementById('cs-h');
  const tmp = w.value; w.value = h.value; h.value = tmp;
  syncCsPresets();
});
document.getElementById('cs-cancel').addEventListener('click', () => {
  closeCanvasSizeDialog();
});
document.getElementById('cs-apply').addEventListener('click', () => {
  const w = Math.max(50, Math.min(2000, parseInt(document.getElementById('cs-w').value) || 420));
  const h = Math.max(50, Math.min(2000, parseInt(document.getElementById('cs-h').value) || 297));
  const dpi = parseInt(document.getElementById('cs-dpi').value) || 150;
  closeCanvasSizeDialog();
  resizeDocument(w, h, dpi);
  showHint(`Canvas resized to ${w} × ${h} mm @ ${dpi} DPI`);
});

/* =================== LAYERS =================== */
let layerIdCounter = 1;
function createLayer(name) {
  // Image canvas (beneath drawing canvas)
  const imageCanvas = document.createElement('canvas');
  imageCanvas.width = DOC_W_PX;
  imageCanvas.height = DOC_H_PX;
  imageCanvas.style.position = 'absolute';
  imageCanvas.style.inset = '0';
  imageCanvas.style.width = '100%';
  imageCanvas.style.height = '100%';
  imageCanvas.style.pointerEvents = 'none';
  paper.insertBefore(imageCanvas, rulerOverlay);

  // Drawing canvas
  const canvas = document.createElement('canvas');
  canvas.width = DOC_W_PX;
  canvas.height = DOC_H_PX;
  paper.insertBefore(canvas, rulerOverlay);

  const layer = {
    id: layerIdCounter++,
    name: name || `Layer ${String(state.layers.length + 1).padStart(2, '0')}`,
    canvas,
    ctx: canvas.getContext('2d'),
    imageCanvas,
    imageCtx: imageCanvas.getContext('2d'),
    visible: true,
    opacity: 1.0,
    trace: 0,
    blendMode: 'source-over',   // CSS mix-blend-mode for the layer
    history: [],
    redo: [],
    _cur: null,   // cached full pixels for region-diff undo
    image: null,
    imageSource: null,
    imageTransform: null,
    imageOpacity: 1.0,
    imageCrop: null,
    imageBaked: false,
  };
  layer.ctx.lineCap = 'round';
  layer.ctx.lineJoin = 'round';
  state.layers.push(layer);
  state.activeLayer = state.layers.length - 1;
  updateLayerOrder();
  layer._cur = layer.ctx.getImageData(0, 0, DOC_W_PX, DOC_H_PX);  // empty baseline
  renderLayers();
  return layer;
}

// Import an image as a new layer.
function importImageAsLayer(file, replaceLayer) {
  // If we're replacing an existing image in a layer, pick that target
  if (!replaceLayer && state.replaceImageInLayer) {
    replaceLayer = state.replaceImageInLayer;
    state.replaceImageInLayer = null;
  }
  const reader = new FileReader();
  reader.onload = (ev) => {
    const dataUrl = ev.target.result;
    const img = new Image();
    img.onload = () => {
      const targetLayer = replaceLayer || createLayer(file.name.replace(/\.[^.]+$/, '').slice(0, 32) || 'Image');
      // Fit image inside the document while preserving aspect.
      const aspect = img.naturalWidth / img.naturalHeight;
      let w, h;
      if (DOC_W_PX / DOC_H_PX > aspect) {
        h = DOC_H_PX * 0.9;
        w = h * aspect;
      } else {
        w = DOC_W_PX * 0.9;
        h = w / aspect;
      }
      targetLayer.image = img;
      targetLayer.imageSource = dataUrl;
      targetLayer.imageTransform = {
        x: DOC_W_PX / 2,
        y: DOC_H_PX / 2,
        w, h,
        rotation: 0,
      };
      targetLayer.imageOpacity = 1.0;
      targetLayer.imageCrop = null;
      targetLayer.imageBaked = false;
      renderImageCanvas(targetLayer);
      state.activeLayer = state.layers.indexOf(targetLayer);
      updateLayerOrder();
      renderLayers();
      updateUI();
      showHint('Image imported as layer · drag to move, corners to scale, top handle to rotate');
    };
    img.src = dataUrl;
  };
  reader.readAsDataURL(file);
}

// Redraw a layer's image canvas with its current transform + crop.
// A downscaled copy of the source used for fast live preview while moving/
// scaling (resampling the full-res original every frame is what made it lag).
// Full-res original is still used when baking for final quality.
function workingImage(layer) {
  if (layer.imageCrop) return layer.image;   // crop path needs original coords
  const src = layer.image;
  const long = Math.max(src.naturalWidth, src.naturalHeight);
  const cap = 2200;
  if (long <= cap) return src;
  if (layer._imgWork && layer._imgWorkFor === src) return layer._imgWork;
  const s = cap / long;
  const wc = document.createElement('canvas');
  wc.width = Math.max(1, Math.round(src.naturalWidth * s));
  wc.height = Math.max(1, Math.round(src.naturalHeight * s));
  wc.getContext('2d').drawImage(src, 0, 0, wc.width, wc.height);
  layer._imgWork = wc; layer._imgWorkFor = src;
  return wc;
}

function renderImageCanvas(layer) {
  const ctx = layer.imageCtx;
  ctx.clearRect(0, 0, DOC_W_PX, DOC_H_PX);
  if (!layer.image || layer.imageBaked) return;
  const t = layer.imageTransform;
  ctx.save();
  ctx.globalAlpha = layer.imageOpacity;
  ctx.translate(t.x, t.y);
  ctx.rotate(t.rotation * Math.PI / 180);
  const useImg = layer.imageManipulating ? workingImage(layer) : layer.image;
  let sx = 0, sy = 0, sw = useImg.naturalWidth || useImg.width, sh = useImg.naturalHeight || useImg.height;
  if (layer.imageCrop) {
    sx = layer.imageCrop.x; sy = layer.imageCrop.y;
    sw = layer.imageCrop.w; sh = layer.imageCrop.h;
  }
  ctx.drawImage(useImg, sx, sy, sw, sh, -t.w/2, -t.h/2, t.w, t.h);
  ctx.restore();
}

// Bake the image into the drawing canvas, freeing the image for normal draw/erase.
function bakeImageLayer(layer) {
  if (!layer.image || layer.imageBaked) return;
  layer.ctx.save();
  layer.ctx.globalAlpha = layer.imageOpacity;
  layer.ctx.drawImage(layer.imageCanvas, 0, 0);
  layer.ctx.restore();
  layer.imageCanvas.getContext('2d').clearRect(0, 0, DOC_W_PX, DOC_H_PX);
  layer.imageBaked = true;
  layer.image = null; // free reference; source kept in case we want re-import
  saveSnapshot(layer);
  hideImageOverlay();
  renderLayers();
  updateUI();
}

function updateLayerOrder() {
  state.layers.forEach((l, i) => {
    // image canvas sits just below the drawing canvas for the same layer
    if (l.imageCanvas) {
      l.imageCanvas.style.zIndex = (i * 2 + 2).toString();
      l.imageCanvas.style.opacity = l.visible ? 1 : 0;
      l.imageCanvas.style.pointerEvents = 'none';
    }
    l.canvas.style.zIndex = (i * 2 + 3).toString();
    l.canvas.style.opacity = l.visible ? l.opacity : 0;
    // Mix-blend-mode on the draw canvas implements layer blend modes
    l.canvas.style.mixBlendMode = (l.blendMode && l.blendMode !== 'source-over') ? l.blendMode : '';
    if (l.trace > 0) {
      l.canvas.style.filter = `sepia(${l.trace * 0.4}) saturate(${1 + l.trace * 0.5}) hue-rotate(-10deg)`;
    } else {
      l.canvas.style.filter = '';
    }
    // pointer events on active drawing canvas only when in draw mode and the layer has no unbaked image
    const hasUnbakedImage = l.image && !l.imageBaked;
    l.canvas.style.pointerEvents = (i === state.activeLayer && state.mode === 'draw' && !hasUnbakedImage) ? 'auto' : 'none';
  });
  rulerOverlay.style.zIndex = '999';
  // pointer-events: all set in CSS; individual non-interactive elements get pointer-events:none explicitly
  // Refresh image overlay visibility for active layer
  refreshImageOverlay();
}

function activeLayer() { return state.layers[state.activeLayer]; }

// Undo model: each history entry is a region diff { x, y, before, after }.
// Strokes capture only their bounding box (cheap). Rare ops (fill, layer ops,
// resize, image bake) capture the full canvas. layer._cur caches the current
// full pixels so full-canvas ops can record their "before" without a second read.
function _capHistory(layer) {
  const minSteps = 40;
  let budget = 220 * 1024 * 1024;  // ~220MB of undo per layer
  let total = 0;
  for (let i = layer.history.length - 1; i >= 0; i--) {
    const e = layer.history[i];
    total += (e.before ? e.before.data.length : 0) + (e.after ? e.after.data.length : 0);
    if (total > budget && layer.history.length > minSteps) { layer.history.splice(0, i + 1); break; }
  }
}
function _blitRegion(full, region, x, y) {
  if (!full || !region) return;
  const fw = full.width, rw = region.width, rh = region.height;
  for (let row = 0; row < rh; row++) {
    const dst = ((y + row) * fw + x) * 4;
    const src = row * rw * 4;
    full.data.set(region.data.subarray(src, src + rw * 4), dst);
  }
}
// Slice a w×h region out of a full ImageData into a new ImageData.
function _extractRegion(full, x, y, w, h) {
  const out = new ImageData(w, h);
  const fw = full.width;
  for (let row = 0; row < h; row++) {
    const src = ((y + row) * fw + x) * 4;
    out.data.set(full.data.subarray(src, src + w * 4), row * w * 4);
  }
  return out;
}
// Clamp a stroke's bounding box to canvas bounds, padded by the brush width.
function _bboxRect(bb) {
  if (!bb) return null;
  const pad = Math.ceil(bb.maxW) + 4;
  const x = Math.max(0, Math.floor(bb.minX - pad));
  const y = Math.max(0, Math.floor(bb.minY - pad));
  const w = Math.min(DOC_W_PX - x, Math.ceil(bb.maxX + pad) - x);
  const h = Math.min(DOC_H_PX - y, Math.ceil(bb.maxY + pad) - y);
  if (w <= 0 || h <= 0) return null;
  return { x, y, w, h };
}

// Full-canvas snapshot — used by rare, large operations.
function saveSnapshot(layer) {
  try {
    const after = layer.ctx.getImageData(0, 0, DOC_W_PX, DOC_H_PX);
    const before = layer._cur || after;
    layer.history.push({ x: 0, y: 0, before, after });
    layer.redo = [];
    layer._cur = after;
    _capHistory(layer);
    layer._dirty = true;
    scheduleAutosave();
  } catch (e) { console.warn(e); }
}

// Region snapshot — used by strokes. before/after are already-captured regions.
function pushRegionSnapshot(layer, x, y, before, after) {
  try {
    layer.history.push({ x, y, before, after });
    layer.redo = [];
    if (!layer._cur) layer._cur = layer.ctx.getImageData(0, 0, DOC_W_PX, DOC_H_PX);
    else _blitRegion(layer._cur, after, x, y);
    _capHistory(layer);
    layer._dirty = true;
    scheduleAutosave();
  } catch (e) { console.warn(e); }
}

// ---- vector-entity undo (walls, openings, rooms, dimensions) ----
// Rides the active layer's history so it interleaves correctly with raster strokes.
function vectorSnapshot() {
  return {
    walls: JSON.parse(JSON.stringify(state.walls || [])),
    shapes: JSON.parse(JSON.stringify(state.shapes || [])),
    measurements: JSON.parse(JSON.stringify(state.measurements || [])),
  };
}
function applyVectorSnapshot(s) {
  state.walls = JSON.parse(JSON.stringify(s.walls || []));
  state.shapes = JSON.parse(JSON.stringify(s.shapes || []));
  state.measurements = JSON.parse(JSON.stringify(s.measurements || []));
  state.sel = null; state.selOpening2D = null;
  if (typeof showSelectBar === 'function') showSelectBar(null);
  if (typeof showOpeningPalette === 'function') showOpeningPalette(state.tool === 'opening');
  if (typeof refreshMeasurements === 'function') refreshMeasurements();
  if (typeof syncWallsToMasses === 'function') syncWallsToMasses();
  if (typeof renderSchedule === 'function') renderSchedule();
}
let _lastVecPush = 0;
function recordVec(before, coalesce) {
  const l = activeLayer(); if (!l) return;
  const after = vectorSnapshot();
  const now = Date.now();
  const top = l.history[l.history.length - 1];
  // coalesce only a burst of property edits (e.g. typing a thickness) into one undo step
  if (coalesce && top && top.vector && (now - _lastVecPush) < 800) {
    top.vector.after = after;
  } else {
    l.history.push({ vector: { before, after } });
    l.redo = [];
    _capHistory(l);
  }
  _lastVecPush = now;
  l._dirty = true; scheduleAutosave();
}

function undo() {
  if (massing.active) { massUndo(); return; }
  const l = activeLayer();
  if (!l.history.length) return;
  const e = l.history.pop();
  if (e.vector) { applyVectorSnapshot(e.vector.before); l.redo.push(e); l._dirty = true; scheduleAutosave(); return; }
  l.ctx.putImageData(e.before, e.x, e.y);
  l.redo.push(e);
  if (l._cur) _blitRegion(l._cur, e.before, e.x, e.y);
  l._dirty = true; scheduleAutosave();
  renderLayers();
}

function redo() {
  if (massing.active) { massRedo(); return; }
  const l = activeLayer();
  if (!l.redo.length) return;
  const e = l.redo.pop();
  if (e.vector) { applyVectorSnapshot(e.vector.after); l.history.push(e); l._dirty = true; scheduleAutosave(); return; }
  l.ctx.putImageData(e.after, e.x, e.y);
  l.history.push(e);
  if (l._cur) _blitRegion(l._cur, e.after, e.x, e.y);
  l._dirty = true; scheduleAutosave();
  renderLayers();
}

function clearActive() {
  const l = activeLayer();
  l.ctx.clearRect(0, 0, DOC_W_PX, DOC_H_PX);
  saveSnapshot(l);
  renderLayers();
}

function setWallsVisible(visible) {
  state.wallsVisible = !!visible;
  if (!state.wallsVisible) {
    if (state.sel && (state.sel.type === 'wall' || state.sel.type === 'opening')) {
      state.sel = null;
      if (typeof showSelectBar === 'function') showSelectBar(null);
    }
    state.selOpening2D = null;
    if (typeof showOpeningPalette === 'function') showOpeningPalette(false);
  }
  refreshMeasurements();
  renderLayers();
  scheduleAutosave();
}

function renderLayers() {
  layersList.innerHTML = '';
  // Update layer count — element may not exist in new UI
  const lcEl = document.getElementById('layer-count');
  if (lcEl) lcEl.textContent = state.layers.length;
  // v96 — pinned Walls vector row (not a raster layer; lives in state.walls)
  {
    const wCount = (state.walls || []).length;
    const wVis = state.wallsVisible !== false;
    const wRow = document.createElement('div');
    wRow.className = 'layer-card layer-card-vector' + (wVis ? '' : ' layer-hidden');
    wRow.innerHTML = `
      <div class="layer-thumb layer-thumb-vector" aria-hidden="true">
        <svg viewBox="0 0 42 30" width="42" height="30"><rect width="42" height="30" fill="#f4f2ef"/><line x1="6" y1="10" x2="36" y2="10" stroke="#1c1a18" stroke-width="2"/><line x1="6" y1="20" x2="36" y2="20" stroke="#1c1a18" stroke-width="2"/><rect x="6" y="10" width="30" height="10" fill="rgba(28,26,24,0.12)"/></svg>
      </div>
      <div class="layer-info">
        <div class="layer-name">Walls<span class="vec-badge">VEC</span></div>
        <div class="layer-meta">${wCount} wall${wCount === 1 ? '' : 's'} · ${wVis ? 'VISIBLE' : 'HIDDEN'} · 2D only</div>
      </div>
      <div class="layer-actions">
        <button class="layer-act ${wVis ? 'on' : 'off'}" data-action="walls-vis" title="Show/hide wall linework">
          ${wVis
            ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>'
            : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>'}
        </button>
      </div>`;
    wRow.querySelector('[data-action="walls-vis"]').addEventListener('click', (e) => {
      e.stopPropagation();
      setWallsVisible(!wVis);
    });
    layersList.appendChild(wRow);
  }
  for (let i = state.layers.length - 1; i >= 0; i--) {
    const l = state.layers[i];
    const div = document.createElement('div');
    div.className = 'layer-card' + (i === state.activeLayer ? ' active-layer' : '');
    const hasUnbakedImage = l.image && !l.imageBaked;
    const isImageLayer = hasUnbakedImage || l.imageBaked;
    div.innerHTML = `
      <div class="layer-thumb"><canvas width="42" height="30"></canvas></div>
      <div class="layer-info">
        <div class="layer-name" data-idx="${i}">${l.name}${hasUnbakedImage ? '<span class="img-badge">IMG</span>' : (l.imageBaked ? '<span class="img-badge" style="background:var(--muted)">FLAT</span>' : '')}</div>
        <div class="layer-meta">${Math.round(l.opacity*100)}% · ${l.visible ? 'VISIBLE' : 'HIDDEN'}${l.trace > 0 ? ' · TRACE' : ''}</div>
      </div>
      <div class="layer-actions">
        <button class="layer-act ${l.visible ? 'on' : 'off'}" data-action="vis" data-idx="${i}">
          ${l.visible
            ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>'
            : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>'}
        </button>
        <button class="layer-act" data-action="menu" data-idx="${i}" title="Layer options">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/></svg>
        </button>
        <button class="layer-act" data-action="del" data-idx="${i}" ${state.layers.length === 1 ? 'style="opacity:.2;pointer-events:none"' : ''}>
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L5 6"/></svg>
        </button>
      </div>
    `;
    const thumb = div.querySelector('canvas');
    const tctx = thumb.getContext('2d');
    if (l.imageCanvas) tctx.drawImage(l.imageCanvas, 0, 0, 42, 30);
    tctx.drawImage(l.canvas, 0, 0, 42, 30);

    div.addEventListener('click', (e) => {
      if (e.target.closest('.layer-act') || e.target.classList.contains('layer-name')) return;
      state.activeLayer = i;
      updateLayerOrder(); renderLayers(); updateUI();
    });

    const nameEl = div.querySelector('.layer-name');
    nameEl.addEventListener('dblclick', () => {
      nameEl.contentEditable = 'true';
      nameEl.focus();
      const range = document.createRange();
      range.selectNodeContents(nameEl);
      const sel = window.getSelection();
      sel.removeAllRanges();
      sel.addRange(range);
    });
    nameEl.addEventListener('blur', () => {
      l.name = nameEl.textContent.trim() || 'Layer';
      nameEl.contentEditable = 'false';
      renderLayers();
    });
    nameEl.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') { e.preventDefault(); nameEl.blur(); }
    });

    div.querySelectorAll('.layer-act').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const action = btn.dataset.action;
        const idx = parseInt(btn.dataset.idx);
        if (action === 'vis') {
          state.layers[idx].visible = !state.layers[idx].visible;
        } else if (action === 'menu') {
          openLayerMenu(idx, btn);
          return;
        } else if (action === 'del' && state.layers.length > 1) {
          const name = state.layers[idx].name || 'Layer';
          if (!confirm('Delete layer "' + name + '"? This cannot be undone.')) return;
          state.layers[idx].canvas.remove();
          if (state.layers[idx].imageCanvas) state.layers[idx].imageCanvas.remove();
          state.layers.splice(idx, 1);
          state.activeLayer = Math.min(state.activeLayer, state.layers.length - 1);
        }
        updateLayerOrder(); renderLayers(); updateUI();
      });
    });

    layersList.appendChild(div);
  }
}

/* =================================================================
   LAYER OPERATIONS — duplicate, flip (mirror), merge, clear,
   and free transform (move/scale/rotate) via the image overlay.
   ================================================================= */
function layerCompositeToCtx(src, ctx) {
  if (src.imageCanvas && !src.imageBaked) ctx.drawImage(src.imageCanvas, 0, 0);
  ctx.drawImage(src.canvas, 0, 0);
}

function moveLayer(idx, dir) {
  // dir +1 = up the stack (toward top of panel / higher z), -1 = down.
  const j = idx + dir;
  if (j < 0 || j >= state.layers.length) return;
  const [l] = state.layers.splice(idx, 1);
  state.layers.splice(j, 0, l);
  state.activeLayer = j;
  updateLayerOrder();
  renderLayers();
}

function duplicateLayer(idx) {
  const src = state.layers[idx];
  const nl = createLayer((src.name || 'Layer') + ' copy');  // appended at end, active
  layerCompositeToCtx(src, nl.ctx);
  nl.opacity = src.opacity; nl.trace = src.trace;
  nl.blendMode = src.blendMode; nl.visible = src.visible;
  // place the copy directly above the source
  state.layers.pop();
  state.layers.splice(idx + 1, 0, nl);
  state.activeLayer = idx + 1;
  saveSnapshot(nl);
  updateLayerOrder(); renderLayers(); updateUI();
  showHint('Layer duplicated');
}

function flipLayer(idx, horizontal) {
  const l = state.layers[idx];
  if (l.image && !l.imageBaked) bakeImageLayer(l);
  const tmp = document.createElement('canvas');
  tmp.width = DOC_W_PX; tmp.height = DOC_H_PX;
  tmp.getContext('2d').drawImage(l.canvas, 0, 0);
  l.ctx.clearRect(0, 0, DOC_W_PX, DOC_H_PX);
  l.ctx.save();
  if (horizontal) { l.ctx.translate(DOC_W_PX, 0); l.ctx.scale(-1, 1); }
  else { l.ctx.translate(0, DOC_H_PX); l.ctx.scale(1, -1); }
  l.ctx.drawImage(tmp, 0, 0);
  l.ctx.restore();
  saveSnapshot(l);
  renderLayers();
  showHint(horizontal ? 'Layer mirrored horizontally' : 'Layer mirrored vertically');
}

function mergeDownLayer(idx) {
  if (idx === 0) { showHint('Nothing below to merge into'); return; }
  const top = state.layers[idx], below = state.layers[idx - 1];
  if (top.image && !top.imageBaked) bakeImageLayer(top);
  if (below.image && !below.imageBaked) bakeImageLayer(below);
  below.ctx.save();
  below.ctx.globalAlpha = top.visible ? top.opacity : 0;
  below.ctx.drawImage(top.canvas, 0, 0);
  below.ctx.restore();
  top.canvas.remove();
  if (top.imageCanvas) top.imageCanvas.remove();
  state.layers.splice(idx, 1);
  state.activeLayer = idx - 1;
  saveSnapshot(below);
  updateLayerOrder(); renderLayers(); updateUI();
  showHint('Merged down');
}

function clearLayer(idx) {
  const l = state.layers[idx];
  l.ctx.clearRect(0, 0, DOC_W_PX, DOC_H_PX);
  if (l.imageCanvas) l.imageCtx.clearRect(0, 0, DOC_W_PX, DOC_H_PX);
  l.image = null; l.imageBaked = false; l.imageTransform = null;
  hideImageOverlay();
  saveSnapshot(l);
  renderLayers(); updateUI();
  showHint('Layer cleared');
}

// Free transform: turn the layer's pixels into a transformable image and
// reuse the existing move/scale/rotate overlay. "Apply" bakes it back.
function transformLayer(idx) {
  const l = state.layers[idx];
  state.activeLayer = idx;
  if (l.image && !l.imageBaked) bakeImageLayer(l);
  const dataUrl = l.canvas.toDataURL('image/png');
  const img = new Image();
  img.onload = () => {
    l.ctx.clearRect(0, 0, DOC_W_PX, DOC_H_PX);
    l.image = img;
    l.imageSource = dataUrl;
    l.imageTransform = { x: DOC_W_PX / 2, y: DOC_H_PX / 2, w: DOC_W_PX, h: DOC_H_PX, rotation: 0 };
    l.imageOpacity = 1; l.imageCrop = null; l.imageBaked = false;
    renderImageCanvas(l);
    updateLayerOrder(); renderLayers(); updateUI();
    refreshImageOverlay();
    showHint('Transform · drag to move · corners to scale · top handle to rotate · Apply to commit');
  };
  img.src = dataUrl;
}

/* ---- Layer options menu ---- */
let layerMenuEl = null;
function openLayerMenu(idx, anchor) {
  closeLayerMenu();
  const items = [
    { label: 'Move up', fn: () => moveLayer(idx, +1), disabled: idx === state.layers.length - 1 },
    { label: 'Move down', fn: () => moveLayer(idx, -1), disabled: idx === 0 },
    { label: 'Duplicate', fn: () => duplicateLayer(idx) },
    { label: 'Transform (move / scale / rotate)', fn: () => transformLayer(idx) },
    { label: 'Mirror horizontal', fn: () => flipLayer(idx, true) },
    { label: 'Mirror vertical', fn: () => flipLayer(idx, false) },
    { label: 'Merge down', fn: () => mergeDownLayer(idx), disabled: idx === 0 },
    { label: 'Clear', fn: () => clearLayer(idx) },
  ];
  const menu = document.createElement('div');
  menu.className = 'layer-menu';
  items.forEach(it => {
    const b = document.createElement('button');
    b.className = 'layer-menu-item' + (it.disabled ? ' disabled' : '');
    b.textContent = it.label;
    if (!it.disabled) b.addEventListener('click', (e) => { e.stopPropagation(); closeLayerMenu(); it.fn(); });
    menu.appendChild(b);
  });
  document.body.appendChild(menu);
  layerMenuEl = menu;
  const r = anchor.getBoundingClientRect();
  const mw = 210;
  let left = r.right - mw;
  if (left < 8) left = 8;
  let top = r.bottom + 4;
  // flip up if it would go off the bottom
  if (top + menu.offsetHeight > window.innerHeight - 8) top = r.top - menu.offsetHeight - 4;
  menu.style.left = left + 'px';
  menu.style.top = top + 'px';
  setTimeout(() => document.addEventListener('pointerdown', closeLayerMenuOnOutside, true), 0);
}
function closeLayerMenu() {
  if (layerMenuEl) { layerMenuEl.remove(); layerMenuEl = null; }
  document.removeEventListener('pointerdown', closeLayerMenuOnOutside, true);
}
function closeLayerMenuOnOutside(e) {
  if (layerMenuEl && !layerMenuEl.contains(e.target)) closeLayerMenu();
}
function clientToCanvas(clientX, clientY) {
  const rect = paper.getBoundingClientRect();
  const x = ((clientX - rect.left) / rect.width) * DOC_W_PX;
  const y = ((clientY - rect.top) / rect.height) * DOC_H_PX;
  return { x, y };
}

// ─── STROKE BUFFER ───────────────────────────────────────────────
// Freehand strokes render here at FULL opacity, so overlapping segments
// (especially the clustered points at stroke start) never accumulate
// alpha into a dark blob. On lift, the whole buffer is composited onto
// the active layer once, at the target opacity + blend mode.
const strokeCanvas = document.createElement('canvas');
strokeCanvas.width = DOC_W_PX;
strokeCanvas.height = DOC_H_PX;
strokeCanvas.id = 'stroke-buffer';
strokeCanvas.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;display:block;pointer-events:none;opacity:0;will-change:opacity;';
const strokeCtx = strokeCanvas.getContext('2d');
paper.appendChild(strokeCanvas);
// Persistent full-resolution canvas for replaying the committed stroke — reused
// each lift instead of allocating a large canvas per stroke (less GC, smoother).
const replayCanvas = document.createElement('canvas');
const replayCtx = replayCanvas.getContext('2d');

function strokeTarget() {
  return state.usingBuffer ? strokeCtx : activeLayer().ctx;
}


function pressureFor(e) {
  if (e.pointerType === 'pen' && e.pressure > 0) return e.pressure;
  if (e.pointerType === 'touch') return 0.55;
  return 0.5;
}

let activePointers = new Map(); // for pinch detection

paper.addEventListener('pointerdown', (e) => {
  // Dismiss the Fill·Extrude chip on any fresh interaction (a polygon-closing
  // tap re-shows it later in this same handler, so order is safe).
  if (typeof hideShapeChip === 'function') hideShapeChip();
  // track for pinch
  activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });

  // ─── Touch gesture tracking (2-finger undo, 3-finger redo) ──────
  if (e.pointerType === 'touch') {
    gestureState.touchTimes.set(e.pointerId, Date.now());
    gestureState.peakCount = Math.max(gestureState.peakCount, gestureState.touchTimes.size);
  }

  // ─── Auto-hide UI when stylus or finger starts drawing ──────────
  if ((e.pointerType === 'pen' || e.pointerType === 'mouse') &&
      state.mode === 'draw' &&
      !['hand','ruler','area','wall','opening','select','offset','fill','stencil','brushes','wand','lasso'].includes(state.tool)) {
    uiHide();
  }

  // Navigate mode or hand tool, or pinch zoom (always allow 2-finger zoom in draw mode)
  if (state.mode === 'navigate' || state.tool === 'hand' || activePointers.size > 1) {
    // A second finger arrived mid-stroke → abort the nascent stroke so a 2-/3-finger
    // gesture doesn't commit a stray (often empty) stroke that swallows the undo.
    if (activePointers.size > 1 && state.drawing) {
      state.drawing = false;
      if (typeof strokeCanvas !== 'undefined' && strokeCanvas) {
        strokeCtx.setTransform(1, 0, 0, 1, 0, 0);
        strokeCtx.clearRect(0, 0, strokeCanvas.width, strokeCanvas.height);
        strokeCanvas.style.opacity = '0';
      }
      state.strokeSegs = [];
    }
    paper.setPointerCapture(e.pointerId);
    if (activePointers.size === 2) {
      const pts = Array.from(activePointers.values());
      state.pinchStart = {
        dist: Math.hypot(pts[1].x - pts[0].x, pts[1].y - pts[0].y),
        zoom: state.zoom,
        midX: (pts[0].x + pts[1].x) / 2,
        midY: (pts[0].y + pts[1].y) / 2,
        panX: state.panX, panY: state.panY,
      };
    } else {
      state.isPanning = true;
      state.panStartX = e.clientX - state.panX;
      state.panStartY = e.clientY - state.panY;
    }
    return;
  }

  if (state.tool === 'stencil') {
    placeStencil(clientToCanvas(e.clientX, e.clientY));
    return;
  }

  // Area polygon tool
  if (state.tool === 'area' || state.tool === 'line' || state.tool === 'wall') {
    e.preventDefault();
    const p = clientToCanvas(e.clientX, e.clientY);
    // Line tool: click-drag for a single straight segment (PC, tablet, iPad, stylus)
    if (state.tool === 'line') {
      state.lineDrag = { x1: p.x, y1: p.y, x2: p.x, y2: p.y, pointerId: e.pointerId };
      paper.setPointerCapture && paper.setPointerCapture(e.pointerId);
      return;
    }
    state._lastPolyClient = { x: e.clientX, y: e.clientY };
    state.smoothedX = p.x;
    state.smoothedY = p.y;
    // Manual double-tap detection (dblclick is unreliable on touch/Pencil)
    const now = Date.now();
    if (state._lastAreaTap &&
        now - state._lastAreaTap.time < 350 &&
        Math.hypot(e.clientX - state._lastAreaTap.x, e.clientY - state._lastAreaTap.y) < 24) {
      // Double-tap → finish (area needs 3+, line/wall accept a 2-point run)
      const enough = (state.tool === 'line' || state.tool === 'wall') ? state.polyPoints.length >= 2 : state.polyPoints.length >= 3;
      if (state.polyActive && enough) {
        state._lastAreaTap = null;
        finishPoly();
        return;
      }
    }
    state._lastAreaTap = { time: now, x: e.clientX, y: e.clientY };
    addPolyVertex(p);
    return;
  }

  // Offset tool — tap a room to offset its boundary
  if (state.tool === 'offset') {
    e.preventDefault();
    const p = clientToCanvas(e.clientX, e.clientY);
    const t = offsetTargetAt(p);
    if (t) {
      state.offset = { type: t.type, idx: t.idx, mm: (state.offset && state.offset.mm) || 100, dir: (state.offset && state.offset.dir) || -1 };
      showOffsetBar(true); refreshMeasurements();
      showHint('Selected — set distance, In/Out, then Apply');
    } else {
      state.offset = null; showOffsetBar(false); refreshMeasurements();
      showHint('Tap a room or a shape to offset its boundary');
    }
    return;
  }

  // Select / edit entities (walls, doors, windows, rooms, dimensions)
  if (state.tool === 'select') {
    e.preventDefault();
    const p = clientToCanvas(e.clientX, e.clientY);
    selectEntityAt(p);
    return;
  }

  // Door / Window tool
  if (state.tool === 'opening') {
    e.preventDefault();
    const p = clientToCanvas(e.clientX, e.clientY);
    const hit = openingHitTest2D(p);
    if (hit) {
      state.selOpening2D = hit;
      state._draggingOpening = true;
      state._slideBefore = vectorSnapshot(); state._slideMoved = false;
      updateOpeningPalette();
      refreshMeasurements();
    } else {
      placeOpening2D(p);
    }
    return;
  }

  // Magic wand selection
  if (state.tool === 'wand') {
    e.preventDefault();
    const p = clientToCanvas(e.clientX, e.clientY);
    if (state.floating && insideFloating(p)) { startFloatDrag(e, p); return; }
    if (state.selection && maskAt(p)) { floatSelection(); startFloatDrag(e, p); return; }
    if (state.floating) { commitFloating(); }   // tapped outside floating → place it
    const tol = parseInt(document.getElementById('fill-tolerance').value) * 3;
    magicWandSelect(p, tol);
    return;
  }

  // Lasso selection (freehand) + area
  if (state.tool === 'lasso') {
    e.preventDefault();
    commitFloating(); clearSelection();
    const p = clientToCanvas(e.clientX, e.clientY);
    state.lassoPoints = [p];
    paper.setPointerCapture && paper.setPointerCapture(e.pointerId);
    let raf = false;
    const mv = (ev) => {
      const q = clientToCanvas(ev.clientX, ev.clientY);
      state.lassoPoints.push(q);
      if (raf) return; raf = true;
      requestAnimationFrame(() => { raf = false; drawLassoPath(); });
    };
    const up = () => {
      document.removeEventListener('pointermove', mv);
      document.removeEventListener('pointerup', up);
      document.removeEventListener('pointercancel', up);
      finishLasso();
    };
    document.addEventListener('pointermove', mv);
    document.addEventListener('pointerup', up);
    document.addEventListener('pointercancel', up);
    return;
  }

  // Eyedropper — pick colour from the canvas composite
  if (state.eyedropperActive) {
    e.preventDefault();
    const p = clientToCanvas(e.clientX, e.clientY);
    const x = Math.round(p.x), y = Math.round(p.y);
    // Composite all visible layers to sample
    const tmp = document.createElement('canvas');
    tmp.width = DOC_W_PX; tmp.height = DOC_H_PX;
    const tctx = tmp.getContext('2d');
    tctx.fillStyle = '#ffffff'; tctx.fillRect(0, 0, DOC_W_PX, DOC_H_PX);
    state.layers.forEach(l => {
      if (!l.visible) return;
      if (l.imageCanvas && !l.imageBaked) tctx.drawImage(l.imageCanvas, 0, 0);
      tctx.globalAlpha = l.opacity;
      tctx.drawImage(l.canvas, 0, 0);
    });
    tctx.globalAlpha = 1;
    const [r, g, b] = tctx.getImageData(x, y, 1, 1).data;
    const hex = '#' + [r,g,b].map(v => v.toString(16).padStart(2,'0')).join('');
    setColor(hex);
    state.eyedropperActive = false;
    document.body.style.cursor = '';
    showHint(`Picked: ${hex.toUpperCase()}`);
    return;
  }

  // Flood fill
  if (state.tool === 'fill') {
    e.preventDefault();
    const p = clientToCanvas(e.clientX, e.clientY);
    const l = activeLayer();
    const tolerance = parseInt(document.getElementById('fill-tolerance').value) * 3;
    const expand = parseInt(document.getElementById('fill-expand').value) || 0;
    const sampleAll = document.getElementById('fill-sample-all').checked;
    showHint('Filling…');
    setTimeout(() => {
      const sample = sampleData(sampleAll);
      let mask = computeFillMask(sample, p.x, p.y, tolerance);
      const shrinkEl = document.getElementById('fill-shrink');
      const shrink = shrinkEl ? parseInt(shrinkEl.value, 10) : 2;
      if (shrink > 0) mask = shrinkMask(mask, shrink);
      else if (expand) mask = expandMask(mask, expand);
      applyFill(l, mask);
      saveSnapshot(l);
      renderLayers();
      showHint('Fill complete');
    }, 10);
    return;
  }
  paper.setPointerCapture(e.pointerId);
  const p = clientToCanvas(e.clientX, e.clientY);

  if (measureDeleteAt(e.clientX, e.clientY)) return;

  state.drawing = true;
  state.lastX = p.x; state.lastY = p.y;
  state.startX = p.x; state.startY = p.y;
  state.lastStampX = p.x; state.lastStampY = p.y;
  state.stampAccum = 0;
  state.snapActive = false;
  state.snapAnchor = { x: p.x, y: p.y };
  // Seed stabilizer at touch point so first stroke segment isn't pulled from origin
  state.smoothedX = p.x;
  state.smoothedY = p.y;
  state.velocity = 0;
  state.strokeAge = 0;
  const l = activeLayer();

  if (state.tool === 'ruler') {
    // In chain mode, snap start to previous measurement endpoint
    const startX = (state.dimChainMode && state.dimChainEnd) ? state.dimChainEnd.x : p.x;
    const startY = (state.dimChainMode && state.dimChainEnd) ? state.dimChainEnd.y : p.y;
    state.measurePreview = { x1: startX, y1: startY, x2: p.x, y2: p.y };
    return;
  }

  if (['rect', 'circle'].includes(state.tool)) {
    state._shapeEnd = null;
    state.snapshot = l.ctx.getImageData(0, 0, DOC_W_PX, DOC_H_PX);
    return;
  }

  // Set up stroke path — NO initial dot drawn here.
  // The first pointermove event draws the actual opening segment with real pressure,
  // so the stroke start matches the brush opacity exactly.
  const brush = activeBrush();

  // Decide whether to use the full-opacity stroke buffer.
  // Texture brushes and the eraser draw directly to the layer.
  state.usingBuffer = (brush.kind !== 'erase' && !(brush.tipType === 'texture' && brush.tipImage));
  if (state.usingBuffer) {
    // Render the LIVE stroke to a display-resolution buffer (cheap to fill and
    // composite each frame), then replay at full resolution once on lift. This
    // keeps drawing smooth on large/high-DPI canvases while staying crisp.
    const dpr = window.devicePixelRatio || 1;
    // Live preview renders at display resolution; the committed stroke is always
    // replayed at full resolution, so we can cap the live buffer to bound per-frame
    // cost. Cap the longest side to ~1600px — biggest win on large/high-DPI canvases.
    const longSide = Math.max(DOC_W_PX, DOC_H_PX);
    const sizeCap = Math.min(1, 1600 / longSide);
    const previewScale = Math.max(0.2, Math.min(state.baseZoom * state.zoom * dpr, sizeCap));
    state.bufScale = previewScale;
    const bw = Math.max(1, Math.round(DOC_W_PX * previewScale));
    const bh = Math.max(1, Math.round(DOC_H_PX * previewScale));
    if (strokeCanvas.width !== bw || strokeCanvas.height !== bh) {
      strokeCanvas.width = bw; strokeCanvas.height = bh;
    } else {
      strokeCtx.setTransform(1, 0, 0, 1, 0, 0);
      strokeCtx.clearRect(0, 0, bw, bh);
    }
    // Draw in document coordinates; the transform scales into the small buffer.
    strokeCtx.setTransform(previewScale, 0, 0, previewScale, 0, 0);
    // Capture geometry for the full-res replay on commit.
    state.strokeSegs = [];
    state.strokeStart = { x: p.x, y: p.y };
    state.strokeColor = state.color;
    const activeZ = state.activeLayer * 2 + 3;
    strokeCanvas.style.zIndex = (activeZ + 1).toString();
    strokeCanvas.style.opacity = state.alpha;
    strokeCanvas.style.mixBlendMode = (brush.blend && brush.blend !== 'source-over') ? brush.blend : 'normal';
  }

  const tgt = strokeTarget();
  state.strokeBBox = { minX: p.x, minY: p.y, maxX: p.x, maxY: p.y, maxW: state.size };
  if (brush.tipType === 'texture' && brush.tipImage) {
    stampTexture(l.ctx, brush, p.x, p.y, pressureFor(e));
  } else {
    configurePen(tgt, pressureFor(e), brush, state.usingBuffer);
    tgt.beginPath();
    tgt.moveTo(p.x, p.y);
    // Do NOT stroke here — avoids dark round-cap dot at touch-down pressure.
  }
});

paper.addEventListener('pointermove', (e) => {
  if (state._draggingOpening && state.selOpening2D) {
    slideOpening2D(state.selOpening2D, clientToCanvas(e.clientX, e.clientY));
    state._slideMoved = true;
    return;
  }
  if (activePointers.has(e.pointerId)) {
    activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
  }

  // Pinch zoom — always immediate, no coalescing needed
  if (state.pinchStart && activePointers.size === 2) {
    const pts = Array.from(activePointers.values());
    const dist = Math.hypot(pts[1].x - pts[0].x, pts[1].y - pts[0].y);
    state.zoom = Math.max(0.2, Math.min(8, state.pinchStart.zoom * (dist / state.pinchStart.dist)));
    const midX = (pts[0].x + pts[1].x) / 2;
    const midY = (pts[0].y + pts[1].y) / 2;
    state.panX = state.pinchStart.panX + (midX - state.pinchStart.midX);
    state.panY = state.pinchStart.panY + (midY - state.pinchStart.midY);
    applyStageTransform();
    return;
  }

  if (state.isPanning) {
    state.panX = e.clientX - state.panStartX;
    state.panY = e.clientY - state.panStartY;
    applyStageTransform();
    return;
  }

  if (state.lineDrag && state.lineDrag.pointerId === e.pointerId) {
    const p = clientToCanvas(e.clientX, e.clientY);
    let x2 = p.x, y2 = p.y;
    if (e.shiftKey) {
      const sn = snapToOrtho(x2, y2, state.lineDrag.x1, state.lineDrag.y1);
      x2 = sn.x; y2 = sn.y;
      document.getElementById('snap-badge').classList.add('show');
    } else {
      document.getElementById('snap-badge').classList.remove('show');
    }
    state.lineDrag.x2 = x2;
    state.lineDrag.y2 = y2;
    state.measurePreview = { x1: state.lineDrag.x1, y1: state.lineDrag.y1, x2, y2 };
    refreshMeasurements();
    return;
  }

  if (e.pointerType === 'pen') {
    document.getElementById('pressure-val').textContent = (e.pressure * 100).toFixed(0) + '%';
  }

  if (!state.drawing) return;
  const l = activeLayer();

  // Ruler and shape tools — process main event only (need immediacy for live preview)
  const mainP = clientToCanvas(e.clientX, e.clientY);

  if (state.tool === 'ruler') {
    state.measurePreview.x2 = mainP.x;
    state.measurePreview.y2 = mainP.y;
    refreshMeasurements();
    return;
  }

  if (['rect', 'circle'].includes(state.tool)) {
    let tp = { ...mainP };
    if (e.shiftKey) {
      if (state.tool === 'line') {
        const sn = snapToOrtho(tp.x, tp.y, state.startX, state.startY);
        tp.x = sn.x; tp.y = sn.y;
      } else if (state.tool === 'rect') {
        const dx = tp.x - state.startX, dy = tp.y - state.startY;
        const s = Math.sign(dx) * Math.max(Math.abs(dx), Math.abs(dy));
        tp.x = state.startX + s; tp.y = state.startY + Math.sign(dy) * Math.abs(s);
      }
      document.getElementById('snap-badge').classList.add('show');
    } else {
      document.getElementById('snap-badge').classList.remove('show');
    }
    state._shapeEnd = { x: tp.x, y: tp.y };
    l.ctx.putImageData(state.snapshot, 0, 0);
    // Shapes always draw a clean ink stroke — never inherit the eraser or a
    // previous brush's blend mode (which would erase or composite oddly).
    l.ctx.globalCompositeOperation = 'source-over';
    l.ctx.globalAlpha = state.alpha;
    l.ctx.strokeStyle = state.color;
    l.ctx.lineWidth = Math.max(0.5, state.size);
    l.ctx.lineCap = 'round';
    l.ctx.lineJoin = 'round';
    l.ctx.beginPath();
    if (state.tool === 'line') {
      l.ctx.moveTo(state.startX, state.startY);
      l.ctx.lineTo(tp.x, tp.y);
      l.ctx.stroke();
    } else if (state.tool === 'rect') {
      l.ctx.strokeRect(state.startX, state.startY, tp.x - state.startX, tp.y - state.startY);
    } else if (state.tool === 'circle') {
      const dx = tp.x - state.startX, dy = tp.y - state.startY;
      const r = Math.sqrt(dx * dx + dy * dy);
      l.ctx.arc(state.startX, state.startY, r, 0, Math.PI * 2);
      l.ctx.stroke();
    }
    return;
  }

  // ─────────────────────────────────────────────────────────────────
  // FREEHAND DRAWING — process ALL coalesced events (240Hz on Pencil)
  // Then add predicted events at reduced opacity for zero-lag feel
  // ─────────────────────────────────────────────────────────────────
  const coalescedEvents = (e.getCoalescedEvents)
    ? e.getCoalescedEvents()
    : [e];

  const brush = activeBrush();
  // l is already declared above for ruler/shapes — no need to redeclare

  function drawFreehandPoint(ce, isPredicted) {
    let p = clientToCanvas(ce.clientX, ce.clientY);
    const pr = isPredicted ? (pressureFor(ce) * 0.85) : pressureFor(ce);

    // Ortho snap
    if (e.shiftKey && isDrawTool(state.tool)) {
      p = applyOrthoSnap(p, e);
    } else if (state.snapActive && !e.shiftKey) {
      state.snapActive = false;
      state.snapAnchor = null;
      document.getElementById('snap-badge').classList.remove('show');
    }

    // Stabilizer EMA — at 0 use raw coords (no offset drift)
    if (state.stabilizer > 0) {
      const s = state.stabilizer;
      state.smoothedX = p.x + s * (state.smoothedX - p.x);
      state.smoothedY = p.y + s * (state.smoothedY - p.y);
      p = { x: state.smoothedX, y: state.smoothedY };
    } else {
      state.smoothedX = p.x;
      state.smoothedY = p.y;
    }

    maybeExpandCanvas(p.x, p.y);

    // Velocity-based width — fast strokes are thinner (like real media)
    const dx = p.x - state.lastX, dy = p.y - state.lastY;
    const segDist = Math.sqrt(dx*dx + dy*dy);
    // EMA of velocity for smooth transition (in doc px per event — rough proxy)
    state.velocity = state.velocity * 0.72 + segDist * 0.28;
    // velocity multiplier: fast (>8px) = 0.7× width, slow (≤1px) = 1.0× width
    const velMul = Math.max(0.65, Math.min(1.0, 1.0 - (state.velocity - 1) * 0.04));

    // Apple Pencil tilt — altitude close to 0 = flat/broad, close to π/2 = upright/fine
    // altitudeAngle: 0 = flat, π/2 = upright. More tilt → larger effective size
    let tiltMul = 1.0;
    if (ce.altitudeAngle !== undefined && ce.altitudeAngle < Math.PI / 2) {
      const flatness = 1 - ce.altitudeAngle / (Math.PI / 2); // 0 upright, 1 flat
      tiltMul = 1 + flatness * 0.6; // flat pencil = up to 1.6× wider
    }

    // Taper factor — stroke naturally thins at its ends
    // This is a simple time-based taper using stroke progress
    state.strokeAge = (state.strokeAge || 0) + 1;
    const taperIn  = Math.min(1, state.strokeAge / 8);   // ramp up over 8 samples
    const taperPr  = pr * taperIn;

    if (brush.tipType === 'texture' && brush.tipImage) {
      const effSize = Math.max(1, brush.size * (1 - brush.pressureSize + brush.pressureSize * taperPr) * velMul * tiltMul);
      const step = Math.max(0.5, brush.spacing * effSize);
      state.stampAccum += segDist;
      let placed = 0;
      while (state.stampAccum >= step && placed < 500) {
        const overshoot = state.stampAccum - step;
        const t = (segDist - overshoot) / Math.max(segDist, 0.001);
        const sx = state.lastStampX + dx * t;
        const sy = state.lastStampY + dy * t;
        const savedSize = brush.size;
        brush.size *= velMul * tiltMul;
        stampTexture(l.ctx, brush, sx, sy, taperPr);
        brush.size = savedSize;
        state.lastStampX = sx; state.lastStampY = sy;
        state.stampAccum = overshoot;
        placed++;
      }
      state.lastX = p.x; state.lastY = p.y;
    } else {
      // Render to the stroke buffer (full opacity) or layer (eraser).
      const tgt = strokeTarget();
      configurePen(tgt, taperPr, brush, state.usingBuffer);
      tgt.lineWidth = Math.max(0.3, tgt.lineWidth * velMul * tiltMul);
      const mx = (state.lastX + p.x) / 2;
      const my = (state.lastY + p.y) / 2;
      tgt.quadraticCurveTo(state.lastX, state.lastY, mx, my);
      tgt.stroke();
      if (state.symmetryAxis === 'vertical') {
        const cx = DOC_W_PX / 2;
        const mir = (x) => 2 * cx - x;
        tgt.beginPath();
        tgt.moveTo(mir(state.lastX), state.lastY);
        tgt.quadraticCurveTo(mir(state.lastX), state.lastY, mir(mx), my);
        tgt.stroke();
      } else if (state.symmetryAxis === 'horizontal') {
        const cy = DOC_H_PX / 2;
        const mirY = (y) => 2 * cy - y;
        tgt.beginPath();
        tgt.moveTo(state.lastX, mirY(state.lastY));
        tgt.quadraticCurveTo(state.lastX, mirY(state.lastY), mx, mirY(my));
        tgt.stroke();
      }
      tgt.beginPath();
      tgt.moveTo(mx, my);
      // Grow the stroke bounding box (used for region-based undo).
      const bb = state.strokeBBox;
      if (bb) {
        const hw = tgt.lineWidth;
        bb.minX = Math.min(bb.minX, state.lastX, mx) ;
        bb.minY = Math.min(bb.minY, state.lastY, my);
        bb.maxX = Math.max(bb.maxX, state.lastX, mx);
        bb.maxY = Math.max(bb.maxY, state.lastY, my);
        bb.maxW = Math.max(bb.maxW, hw);
      }
      // Record geometry so we can replay this stroke crisply at full resolution
      // when the pen lifts (the live buffer is only display resolution).
      if (state.usingBuffer) {
        state.strokeSegs.push({ cx: state.lastX, cy: state.lastY, mx, my, w: tgt.lineWidth });
      }
      state.lastX = p.x;
      state.lastY = p.y;
    }
  }

  // Draw coalesced (actual) events
  for (const ce of coalescedEvents) drawFreehandPoint(ce, false);

  // Predicted events are disabled while using the stroke buffer (they would
  // persist in the buffer without being corrected). Coalesced 240Hz sampling
  // already keeps strokes responsive.
  if (e.getPredictedEvents && brush.tipType !== 'texture' && !state.usingBuffer) {
    const predicted = e.getPredictedEvents();
    for (const pe of predicted) drawFreehandPoint(pe, true);
  }

  // Update brush cursor ring position (main event coords in screen space)
  updateBrushCursor(e, brush);
});


// ─────────────────────────────────────────────────────────────────
// TOUCH GESTURE STATE — 2-finger tap = undo, 3-finger tap = redo
// ─────────────────────────────────────────────────────────────────
const gestureState = {
  touchTimes: new Map(),  // pointerId → timestamp of touchstart
  peakCount: 0,
};

function showGestureFlash() {
  const el = document.createElement('div');
  el.className = 'gesture-flash';
  document.body.appendChild(el);
  el.addEventListener('animationend', () => el.remove());
}

// ─────────────────────────────────────────────────────────────────
// AUTO-HIDE STATE
// ─────────────────────────────────────────────────────────────────
let _hideTimer = null;
function uiHide() {
  clearTimeout(_hideTimer);
  document.body.classList.add('nm-drawing');
}
function uiShow(delay = 700) {
  clearTimeout(_hideTimer);
  _hideTimer = setTimeout(() => document.body.classList.remove('nm-drawing'), delay);
}

// ─────────────────────────────────────────────────────────────────
// DEFERRED SNAPSHOT — never blocks the draw frame
// ─────────────────────────────────────────────────────────────────
let _snapTimer = null;
function scheduleSnapshot(layer) {
  layer._dirty = true;   // mark immediately so a forced/idle save never misses this change
  clearTimeout(_snapTimer);
  _snapTimer = setTimeout(() => {
    saveSnapshot(layer);
    // Debounce thumbnail update too
    setTimeout(() => renderLayers(), 50);
  }, 320);
}

function endPointer(e) {
  activePointers.delete(e.pointerId);
  if (activePointers.size < 2) state.pinchStart = null;

  // ─── Touch gesture detection ─────────────────────────────────────
  if (e.pointerType === 'touch' && gestureState.touchTimes.has(e.pointerId)) {
    const elapsed = Date.now() - gestureState.touchTimes.get(e.pointerId);
    gestureState.touchTimes.delete(e.pointerId);

    if (gestureState.touchTimes.size === 0) {
      // All fingers lifted — check if it was a quick tap
      if (elapsed < 220 && !state.drawing) {
        if (gestureState.peakCount === 2) {
          undo();
          showGestureFlash();
          showHint('↶  Undo');
        } else if (gestureState.peakCount === 3) {
          redo();
          showGestureFlash();
          showHint('↷  Redo');
        }
      }
      gestureState.peakCount = 0;
    }
  }

  if (state.isPanning) { state.isPanning = false; uiShow(200); }

  if (state.lineDrag && state.lineDrag.pointerId === e.pointerId) {
    const ld = state.lineDrag;
    state.lineDrag = null;
    state.measurePreview = null;
    refreshMeasurements();
    document.getElementById('snap-badge').classList.remove('show');
    if (Math.hypot(ld.x2 - ld.x1, ld.y2 - ld.y1) > 3) {
      state.polyPoints = [{ x: ld.x1, y: ld.y1 }, { x: ld.x2, y: ld.y2 }];
      commitPolygonShape(false);
    }
    return;
  }

  // Restore UI on lift
  if (e.pointerType === 'pen' || e.pointerType === 'mouse') uiShow();

  if (!state.drawing) return;
  state.drawing = false;

  const l = activeLayer();
  if (state.tool === 'ruler') {
    const pending = state.measurePreview;
    state.measurePreview = null;
    commitMeasurement(pending);
    return;
  }
  if (['rect', 'circle'].includes(state.tool)) {
    if (state._shapeEnd) {
      const s = { x: state.startX, y: state.startY }, en = state._shapeEnd;
      if (state.snapshot) l.ctx.putImageData(state.snapshot, 0, 0);   // wipe the raster preview — shape is vector now
      let geom = null, entity = null;
      const sw = Math.max(0.5, state.size);
      if (state.tool === 'rect') {
        const x = Math.min(s.x, en.x), y = Math.min(s.y, en.y), w = Math.abs(en.x - s.x), h = Math.abs(en.y - s.y);
        if (w > 2 && h > 2) {
          geom = { kind: 'rect', x, y, w, h };
          entity = { kind:'rect', pts:[{x,y},{x:x+w,y},{x:x+w,y:y+h},{x,y:y+h}], closed:true, stroke: state.color, width: sw };
        }
      } else {
        const r = Math.hypot(en.x - s.x, en.y - s.y);
        if (r > 2) {
          geom = { kind: 'circle', cx: s.x, cy: s.y, r };
          entity = { kind:'ellipse', cx:s.x, cy:s.y, rx:r, ry:r, stroke: state.color, width: sw };
        }
      }
      state._shapeEnd = null;
      if (entity) { const __b = vectorSnapshot(); state.shapes.push(entity); recordVec(__b); scheduleAutosave(); }
      renderLayers(); refreshMeasurements();
      if (geom && typeof onShapeCommitted === 'function') onShapeCommitted(geom, { x: e.clientX, y: e.clientY });
    }
    return;
  }
  if (isDrawTool(state.tool)) {
    const brush = activeBrush();
    const tgt = strokeTarget();
    if (brush.tipType !== 'texture' && !state.usingBuffer) tgt.stroke();   // eraser: finish final segment on the layer
    const rect = _bboxRect(state.strokeBBox);

    if (state.usingBuffer) {
      // Pen path: capture the region BEFORE compositing (cheap), composite the
      // full-res replay, then capture the region AFTER. Region-only undo.
      const segs = state.strokeSegs || [];
      let before = null;
      if (rect) before = l._cur ? _extractRegion(l._cur, rect.x, rect.y, rect.w, rect.h)
                                : l.ctx.getImageData(rect.x, rect.y, rect.w, rect.h);
      if (segs.length) {
        if (replayCanvas.width !== DOC_W_PX || replayCanvas.height !== DOC_H_PX) {
          replayCanvas.width = DOC_W_PX; replayCanvas.height = DOC_H_PX;
        } else {
          replayCtx.clearRect(0, 0, DOC_W_PX, DOC_H_PX);
        }
        const fctx = replayCtx;
        fctx.strokeStyle = state.strokeColor || state.color;
        fctx.lineCap = 'round'; fctx.lineJoin = 'round';
        fctx.globalAlpha = 1;
        fctx.beginPath();
        fctx.moveTo(state.strokeStart.x, state.strokeStart.y);
        for (const s of segs) {
          fctx.lineWidth = s.w;
          fctx.quadraticCurveTo(s.cx, s.cy, s.mx, s.my);
          fctx.stroke();
          fctx.beginPath();
          fctx.moveTo(s.mx, s.my);
        }
        l.ctx.save();
        l.ctx.globalAlpha = state.alpha;
        l.ctx.globalCompositeOperation = (brush.blend && brush.blend !== 'source-over') ? brush.blend : 'source-over';
        l.ctx.drawImage(replayCanvas, 0, 0);
        l.ctx.restore();
      }
      strokeCtx.setTransform(1, 0, 0, 1, 0, 0);
      strokeCtx.clearRect(0, 0, strokeCanvas.width, strokeCanvas.height);
      strokeCanvas.style.opacity = '0';        // hide via opacity — keeps the layer alive
      strokeCanvas.style.mixBlendMode = 'normal';
      state.usingBuffer = false;
      state.strokeSegs = [];
      if (rect && before) {
        const after = l.ctx.getImageData(rect.x, rect.y, rect.w, rect.h);
        pushRegionSnapshot(l, rect.x, rect.y, before, after);
      } else {
        saveSnapshot(l);
      }
    } else {
      // Eraser path: layer already modified. Pull "before" from the cached full
      // pixels (_cur) and "after" from the layer — both region-sized.
      if (rect && l._cur) {
        const before = _extractRegion(l._cur, rect.x, rect.y, rect.w, rect.h);
        const after = l.ctx.getImageData(rect.x, rect.y, rect.w, rect.h);
        pushRegionSnapshot(l, rect.x, rect.y, before, after);
      } else {
        saveSnapshot(l);
      }
    }
    state.strokeBBox = null;
    // Thumbnail refresh — debounced, off the interactive path.
    clearTimeout(_thumbTimer);
    _thumbTimer = setTimeout(() => renderLayers(), 400);
    l._dirty = true;
    scheduleAutosave();
    saveDoc();
  }
}
let _thumbTimer = null;
paper.addEventListener('pointerup', endPointer);
paper.addEventListener('pointerup', () => { if (state._draggingOpening) { state._draggingOpening = false; if (state._slideMoved && state._slideBefore) recordVec(state._slideBefore, true); state._slideBefore = null; state._slideMoved = false; scheduleAutosave(); } });
paper.addEventListener('pointercancel', endPointer);
paper.addEventListener('pointerleave', endPointer);

// Double-click closes the polygon
paper.addEventListener('dblclick', (e) => {
  if ((state.tool === 'area' || state.tool === 'line' || state.tool === 'wall') && state.polyActive) {
    e.preventDefault();
    finishPoly();
  }
});

// Returns the currently active brush (built-in or custom).
function activeBrush() {
  if (state.activeBrush) return state.activeBrush;
  // map current tool to built-in
  return BUILTIN_BRUSHES.find(b => b.id === state.tool) || BUILTIN_BRUSHES[0];
}

function configurePen(ctx, pressure, brush, skipMaster) {
  brush = brush || activeBrush();
  ctx.globalCompositeOperation = brush.kind === 'erase' ? 'destination-out' : (skipMaster ? 'source-over' : brush.blend);
  ctx.strokeStyle = state.color;
  ctx.fillStyle = state.color;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // Size override comes from puck (state.size) which is synced when brush changes.
  const baseSize = state.size;
  const size = Math.max(0.3, baseSize * (1 - brush.pressureSize + brush.pressureSize * pressure));
  ctx.lineWidth = size;

  // Opacity: when rendering to the stroke buffer (skipMaster), draw at full
  // opacity so segments don't accumulate. Master opacity is applied once when
  // the buffer is composited onto the layer. Otherwise apply the full curve.
  if (skipMaster) {
    ctx.globalAlpha = 1;
  } else {
    const alpha = state.alpha * (1 - brush.pressureOpacity + brush.pressureOpacity * pressure);
    ctx.globalAlpha = brush.kind === 'erase' ? 1 : Math.min(1, Math.max(0.02, alpha));
  }
}

// Get or load an Image object for a tip dataUrl, cached.
function getTipImage(dataUrl) {
  if (!dataUrl) return null;
  let img = state.tipImageCache[dataUrl];
  if (img) {
    if (typeof HTMLCanvasElement !== 'undefined' && img instanceof HTMLCanvasElement) return img;  // ready grain canvas
    return img.complete ? img : null;
  }
  img = new Image();
  img.src = dataUrl;
  state.tipImageCache[dataUrl] = img;
  return img.complete ? img : null;
}

// Stamp a tinted textured tip at (x,y) on the given context.
function stampTexture(ctx, brush, x, y, pressure) {
  const img = getTipImage(brush.tipImage);
  if (!img) return;
  const effSize = Math.max(2, brush.size * (1 - brush.pressureSize + brush.pressureSize * pressure));
  // jitter
  let jx = 0, jy = 0, sScale = 1;
  if (brush.jitter > 0) {
    jx = (Math.random() - 0.5) * effSize * brush.jitter * 0.5;
    jy = (Math.random() - 0.5) * effSize * brush.jitter * 0.5;
    sScale = 1 - brush.jitter * 0.3 + Math.random() * brush.jitter * 0.6;
  }
  const w = effSize * sScale, h = effSize * sScale;
  // Build a tinted version of the tip into an offscreen canvas, then draw.
  const off = document.createElement('canvas');
  off.width = Math.max(2, Math.ceil(w));
  off.height = Math.max(2, Math.ceil(h));
  const oc = off.getContext('2d');
  oc.drawImage(img, 0, 0, off.width, off.height);
  oc.globalCompositeOperation = 'source-in';
  oc.fillStyle = state.color;
  oc.fillRect(0, 0, off.width, off.height);

  const baseAlpha = state.alpha;
  const alpha = baseAlpha * (1 - brush.pressureOpacity + brush.pressureOpacity * pressure);
  ctx.save();
  ctx.globalCompositeOperation = brush.blend;
  ctx.globalAlpha = brush.kind === 'erase' ? 1 : Math.min(1, Math.max(0.02, alpha));
  ctx.drawImage(off, x - w/2 + jx, y - h/2 + jy, w, h);
  ctx.restore();
}

/* =================== MOUSE WHEEL ZOOM =================== */
area.addEventListener('wheel', (e) => {
  // Allow scroll-wheel zoom in draw mode (graphic tablets) without requiring Ctrl
  if (e.ctrlKey || e.metaKey || state.mode === 'navigate' || state.mode === 'draw') {
    e.preventDefault();
    const delta = -e.deltaY * 0.001;
    const oldZoom = state.zoom;
    state.zoom = Math.max(0.2, Math.min(8, state.zoom * (1 + delta)));
    // zoom around cursor
    const areaRect = area.getBoundingClientRect();
    const cx = e.clientX - areaRect.left - areaRect.width/2;
    const cy = e.clientY - areaRect.top - areaRect.height/2;
    const factor = state.zoom / oldZoom;
    state.panX = cx - (cx - state.panX) * factor;
    state.panY = cy - (cy - state.panY) * factor;
    applyStageTransform();
  }
}, { passive: false });

/* =================== NAVIGATE: pan on canvas-area background =================== */
function startAreaPan(e) {
  if (state.mode !== 'navigate' && state.tool !== 'hand') return false;
  if (!area || (paper && (e.target === paper || paper.contains(e.target)))) return false;
  e.preventDefault();
  area.setPointerCapture(e.pointerId);
  activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
  state.isPanning = true;
  state.panStartX = e.clientX - state.panX;
  state.panStartY = e.clientY - state.panY;
  area.style.cursor = 'grabbing';
  return true;
}

area.addEventListener('pointerdown', (e) => { startAreaPan(e); });

area.addEventListener('pointermove', (e) => {
  if (!state.isPanning) return;
  if (state.mode !== 'navigate' && state.tool !== 'hand') return;
  if (area.hasPointerCapture && !area.hasPointerCapture(e.pointerId)) return;
  state.panX = e.clientX - state.panStartX;
  state.panY = e.clientY - state.panStartY;
  applyStageTransform();
});

area.addEventListener('pointerup', (e) => {
  if (state.isPanning && area.hasPointerCapture && area.hasPointerCapture(e.pointerId)) {
    state.isPanning = false;
    area.releasePointerCapture(e.pointerId);
    if (state.mode === 'navigate') area.style.cursor = 'grab';
    else area.style.cursor = '';
  }
});

area.addEventListener('pointercancel', (e) => {
  if (area.hasPointerCapture && area.hasPointerCapture(e.pointerId)) {
    state.isPanning = false;
    area.releasePointerCapture(e.pointerId);
    area.style.cursor = state.mode === 'navigate' ? 'grab' : '';
  }
});

/* =================== MEASUREMENTS =================== */
function refreshMeasurements() {
  rulerOverlay.innerHTML = '';
  rulerOverlay.setAttribute('viewBox', `0 0 ${DOC_W_PX} ${DOC_H_PX}`);
  renderWalls2D();
  renderShapes2D();
  if (state.tool === 'offset' && state.offset) { const ov = computeOffsetPreview(); if (ov) drawOffsetPreview(ov); }
  if (state.showMeasurements) {
    state.measurements.forEach((m, i) => addMeasureSVG(m, false, i));
  }
  if (state.measurePreview) addMeasureSVG(state.measurePreview, true);

  // Draw chain anchor — visible pulsing dot at the chain end point
  if (state.dimChainMode && state.dimChainEnd && state.tool === 'ruler') {
    const svgns = 'http://www.w3.org/2000/svg';
    const { x, y } = state.dimChainEnd;
    const ring = document.createElementNS(svgns, 'circle');
    ring.setAttribute('cx', x); ring.setAttribute('cy', y); ring.setAttribute('r', '22');
    ring.setAttribute('fill', 'rgba(160,40,53,0.12)');
    ring.setAttribute('stroke', '#a02835'); ring.setAttribute('stroke-width', '3');
    ring.setAttribute('stroke-dasharray', '6 4');
    ring.setAttribute('pointer-events', 'none');
    rulerOverlay.appendChild(ring);
    const dot = document.createElementNS(svgns, 'circle');
    dot.setAttribute('cx', x); dot.setAttribute('cy', y); dot.setAttribute('r', '8');
    dot.setAttribute('fill', '#a02835');
    dot.setAttribute('pointer-events', 'none');
    rulerOverlay.appendChild(dot);
  }
}

// addMeasureSVG is defined later as a thin wrapper over addDimSVG (architectural dim renderer)

function measureDeleteAt(clientX, clientY) {
  if (!state.showMeasurements || !state.measurements.length) return false;
  const hit = document.elementFromPoint(clientX, clientY);
  if (!hit || !rulerOverlay.contains(hit)) return false;
  const raw = hit.dataset ? hit.dataset.measureIdx : null;
  if (raw == null || raw === '') return false;
  const idx = parseInt(raw, 10);
  if (Number.isNaN(idx)) return false;
  deleteMeasurement(idx);
  return true;
}

function deleteMeasurement(idx) {
  if (typeof idx !== 'number' || idx < 0 || idx >= state.measurements.length) return;
  const __b = vectorSnapshot();
  state.measurements.splice(idx, 1);
  // If chain mode, reset chain end if we deleted the last measurement
  if (state.dimChainMode && state.measurements.length === 0) state.dimChainEnd = null;
  refreshMeasurements();
  renderSchedule();
  recordVec(__b);
  showHint('Measurement deleted');
}

function commitMeasurement(m) {
  if (!m) return;
  const dx = m.x2 - m.x1, dy = m.y2 - m.y1;
  if (Math.sqrt(dx*dx + dy*dy) < 10) return;
  if (state.pendingScale) {
    state.pendingScaleStart = { x: m.x1, y: m.y1 };
    state.pendingScaleEnd = { x: m.x2, y: m.y2 };
    state.pendingScale = false;
    state.measurePreview = m;
    refreshMeasurements();
    openScaleApply();
    return;
  }
  const __b = vectorSnapshot();
  state.measurements.push({...m});
  // Chain mode: next measurement starts from this endpoint
  if (state.dimChainMode) {
    state.dimChainEnd = { x: m.x2, y: m.y2 };
  }
  refreshMeasurements();
  recordVec(__b);
}

window.addEventListener('resize', () => {
  fitToScreen();
});

/* =================== STENCILS =================== */
function placeStencil(p) {
  if (state.selectedStencil === null) return;
  const rad = (state.stencilRotation || 0) * Math.PI / 180;
  const l = activeLayer();
  const ctx = l.ctx;
  // Hatch patterns are a separate category
  if (state.stencilCat === 'hatch') {
    const hatch = hatchList()[state.selectedStencil];
    if (!hatch) return;
    const size = Math.max(200, state.size * 40) * (state.stencilScale || 1);
    placeHatch(hatch, ctx, p.x, p.y, size, rad);
    saveSnapshot(l);
    renderLayers();
    return;
  }
  const baseSize = Math.max(100, state.size * 40);
  const size = baseSize * (state.stencilScale || 1);
  const stencil = currentStencilList()[state.selectedStencil];
  if (!stencil) return;

  const drawWith = (drawFn) => {
    const half = size * 0.85;
    const rx = Math.max(0, Math.floor(p.x - half));
    const ry = Math.max(0, Math.floor(p.y - half));
    const rw = Math.min(DOC_W_PX - rx, Math.ceil(half * 2));
    const rh = Math.min(DOC_H_PX - ry, Math.ceil(half * 2));
    let before = null;
    try { before = ctx.getImageData(rx, ry, rw, rh); } catch (_) {}
    ctx.save();
    ctx.translate(p.x, p.y);
    if (rad) ctx.rotate(rad);
    ctx.globalCompositeOperation = 'source-over';
    ctx.strokeStyle = state.color;
    ctx.fillStyle = state.color;
    ctx.lineWidth = Math.max(1, state.size);
    ctx.globalAlpha = state.alpha;
    drawFn();
    ctx.restore();
    try {
      const after = ctx.getImageData(rx, ry, rw, rh);
      if (before) pushRegionSnapshot(l, rx, ry, before, after);
      else saveSnapshot(l);
    } catch (_) { saveSnapshot(l); }
    renderLayers();
  };

  if (stencil.dataUrl) {
    const img = new Image();
    img.onload = () => {
      const ratio = img.width / img.height;
      const w = size * 1.5, h = w / ratio;
      drawWith(() => ctx.drawImage(img, -w/2, -h/2, w, h));
    };
    img.src = stencil.dataUrl;
  } else if (stencil.draw) {
    drawWith(() => stencil.draw(ctx, 0, 0, size));
  }
}

function currentStencilList() {
  return state.stencilCat === 'builtin' ? BUILTIN_STENCILS : state.customStencils;
}

function renderStencils() {
  const grid = document.getElementById('stencil-grid');
  grid.innerHTML = '';
  const list = currentStencilList();
  list.forEach((s, i) => {
    const div = document.createElement('div');
    div.className = 'stencil' + (state.selectedStencil === i ? ' active' : '');
    div.title = s.name;
    if (s.dataUrl) {
      const img = document.createElement('img');
      img.src = s.dataUrl;
      div.appendChild(img);
    } else {
      const tmp = document.createElement('canvas');
      tmp.width = 80; tmp.height = 80;
      const tctx = tmp.getContext('2d');
      tctx.strokeStyle = '#0a0a0a';
      tctx.lineWidth = 1.8;
      tctx.lineCap = 'round';
      tctx.lineJoin = 'round';
      s.draw(tctx, 40, 40, 60);
      const img = document.createElement('img');
      img.src = tmp.toDataURL();
      div.appendChild(img);
    }
    div.addEventListener('click', () => {
      state.selectedStencil = i;
      renderStencils();
      showHint(`Tap canvas to place: ${s.name}`);
    });
    if (state.stencilCat === 'custom') {
      const del = document.createElement('button');
      del.className = 'del';
      del.textContent = '×';
      del.addEventListener('click', (e) => {
        e.stopPropagation();
        state.customStencils.splice(i, 1);
        if (state.selectedStencil === i) state.selectedStencil = null;
        renderStencils();
        persistStencils();
      });
      div.appendChild(del);
    }
    grid.appendChild(div);
  });
  // add button (only in custom)
  if (state.stencilCat === 'custom') {
    const add = document.createElement('div');
    add.className = 'stencil add';
    add.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>';
    add.title = 'Upload stencil';
    add.addEventListener('click', () => fileInputStencil.click());
    grid.appendChild(add);
  }
}

function persistStencils() {
  try {
    const slim = state.customStencils.map(s => ({ name: s.name, dataUrl: s.dataUrl }));
    // localStorage may fail in artifact context; try and ignore
    localStorage.setItem('nm-stencils', JSON.stringify(slim));
  } catch (e) {}
}

function loadStencils() {
  try {
    const raw = localStorage.getItem('nm-stencils');
    if (raw) state.customStencils = JSON.parse(raw);
  } catch (e) {}
}

fileInputStencil.addEventListener('change', (e) => {
  const files = Array.from(e.target.files);
  files.forEach(file => {
    const reader = new FileReader();
    reader.onload = (ev) => {
      state.customStencils.push({
        name: file.name.replace(/\.[^.]+$/, ''),
        dataUrl: ev.target.result,
      });
      renderStencils();
      persistStencils();
    };
    reader.readAsDataURL(file);
  });
  e.target.value = '';
});

document.querySelectorAll('.stencil-tab').forEach(t => {
  t.addEventListener('click', () => {
    document.querySelectorAll('.stencil-tab').forEach(x => x.classList.remove('active'));
    t.classList.add('active');
    state.stencilCat = t.dataset.cat;
    state.selectedStencil = null;
    renderStencils();
  });
});

/* =================== SCALE =================== */
function startScale() {
  setTool('ruler');
  state.pendingScale = true;
  showHint('Draw a line on the canvas, then enter its real-world length');
}

function openScaleApply() {
  scalePrompt.style.display = 'block';   // override inline display:none
  scalePrompt.classList.add('show');
  const rect = paper.getBoundingClientRect();
  const midX = (state.pendingScaleStart.x + state.pendingScaleEnd.x) / 2;
  const midY = (state.pendingScaleStart.y + state.pendingScaleEnd.y) / 2;
  const sx = midX / DOC_W_PX * rect.width + rect.left;
  const sy = midY / DOC_H_PX * rect.height + rect.top;
  const areaRect = area.getBoundingClientRect();
  scalePrompt.style.left = Math.min(areaRect.width - 260, Math.max(20, sx - areaRect.left + 20)) + 'px';
  scalePrompt.style.top = Math.max(20, sy - areaRect.top - 120) + 'px';
  const inp = document.getElementById('scale-length');
  inp.value = '';
  setTimeout(() => inp.focus(), 30);
}

  document.getElementById('scale-apply').addEventListener('click', () => {
  const v = parseFloat(document.getElementById('scale-length').value);
  const u = document.getElementById('scale-unit').value;
  if (!v || v <= 0) return;
  const dx = state.pendingScaleEnd.x - state.pendingScaleStart.x;
  const dy = state.pendingScaleEnd.y - state.pendingScaleStart.y;
  const distPx = Math.sqrt(dx*dx + dy*dy);
  state.pxPerUnit = distPx / v;
  state.scaleUnit = u;
  const label = updateScaleDisplay();
  syncProjectScale(label);
  scalePrompt.classList.remove('show');
  scalePrompt.style.display = 'none';
  state.measurePreview = null;
  state.pendingScaleStart = null;
  state.pendingScaleEnd = null;
  refreshMeasurements();
  renderSchedule();
  scheduleAutosave();
  showHint(`Scale set · ${v} ${u} reference · measurements now in real units`);
});

document.getElementById('scale-cancel').addEventListener('click', () => {
  scalePrompt.classList.remove('show');
  scalePrompt.style.display = 'none';
  state.pendingScale = false;
  state.pendingScaleStart = null;
  state.pendingScaleEnd = null;
  state.measurePreview = null;
  refreshMeasurements();
});

/* =================== TOOL UI =================== */
function setTool(tool) {
  if (typeof hideShapeChip === 'function') hideShapeChip();
  // Leaving 3D massing if another tool is chosen
  if (massing.active && tool !== 'massing') {
    massing.active = false;
    massingCanvas.style.display = 'none';
    massingBar.style.display = 'none';
    massing.dragging = null;
    massing.selected = -1;
    document.getElementById('mass-inspector').style.display = 'none';
    massHint('');
    if (typeof updateMatPalette === 'function') updateMatPalette();
    if (typeof updateBuildPalette === 'function') updateBuildPalette();
  }
  state.tool = tool;
  document.querySelectorAll('.tool').forEach(t => t.classList.toggle('active', t.dataset.tool === brushFamilyOf(tool)));

  // close popovers
  colorPopover.classList.remove('show');
  stencilPopover.classList.remove('show');

  if (tool === 'brushes') {
    // intercept: open library, don't change tool
    document.querySelectorAll('.tool').forEach(t => t.classList.remove('active'));
    document.getElementById('rail-brushes')?.classList.add('active');
    openBrushLibrary();
    return;
  }

  { const bb = BUILTIN_BRUSHES.find(x => x.id === tool); if (bb) setActiveBrush(bb); }

  if (tool === 'massing') {
    enterMassing();
    return;
  }

  if (tool === 'stencil') {
    showStencilPopover();
  }
  if (tool === 'hand') {
    showHint('Hand tool — drag to pan, scroll to zoom');
  }
  if (tool === 'fill') {
    document.body.classList.add('fill-mode');
    showHint('Flood Fill — tap inside a closed shape to fill. Open colour picker to set tolerance.');
  } else {
    document.body.classList.remove('fill-mode');
  }
  if (tool === 'wand') {
    showHint('Magic Wand — tap a region to select. Tolerance is in the colour/fill panel.');
  } else if (tool === 'lasso') {
    showHint('Lasso — drag to trace a region. Shows its area; Copy / Cut / Delete / Fill the selection.');
  } else {
    // leaving wand/lasso: place any floating pixels and clear the selection
    if (state.floating || state.selection) { commitFloating(); clearSelection(); }
  }
  if (tool === 'area') {
    startPolyTool();
    showHint('Area tool — click to place vertices · Double-click near start to close · Esc to cancel');
  } else if (tool === 'wall') {
    if (state.wallsVisible === false) setWallsVisible(true);
    startPolyTool();
    showHint('Wall — tap a centreline · double-tap to finish · tap the first point to close a room · snapping on');
  } else if (tool === 'opening') {
    if (state.polyActive) { state.polyPoints = []; state.polyActive = false; document.getElementById('poly-hint').style.display = 'none'; }
    showHint('Door / Window — tap a wall to place · drag to slide · flip & resize in the bar');
  } else if (tool === 'select') {
    if (state.polyActive) { state.polyPoints = []; state.polyActive = false; document.getElementById('poly-hint').style.display = 'none'; }
    showHint('Select — tap a wall, door, window, or room to edit it · Delete to remove');
  } else if (tool === 'offset') {
    if (state.polyActive) { state.polyPoints = []; state.polyActive = false; document.getElementById('poly-hint').style.display = 'none'; }
    showHint('Offset — tap a room, then set the distance and tap Apply');
  } else if (tool === 'line') {
    startPolyTool();
    showHint('Polygon — tap to place vertices · tap the first point or double-tap to close · 2 points = a line · Esc to cancel');
  } else if (state.polyActive) {
    // Cancel polygon if switching away
    state.polyPoints = []; state.polyActive = false;
    document.getElementById('poly-hint').style.display = 'none';
    refreshMeasurements();
  }
  showWall2dPalette(tool === 'wall');
  showOpeningPalette(tool === 'opening');
  if (tool !== 'opening') { state.selOpening2D = null; }
  else updateOpeningPalette();
  const _hadSel = !!state.sel; state.sel = null;
  if (typeof showSelectBar === 'function') showSelectBar(null);
  if (tool !== 'offset' && state.offset) { state.offset = null; if (typeof showOffsetBar === 'function') showOffsetBar(false); }
  if (_hadSel && typeof refreshMeasurements === 'function') refreshMeasurements();
  highlightRailGroups();
  updatePreview();
  updateLayerOrder();
}

function setActiveBrush(brush) {
  state.activeBrush = brush;
  state.size = brush.size;
  state.alpha = brush.opacity;
  // sync puck UI
  const maxSize = brush.maxSize || Math.max(40, brush.size * 3);
  document.getElementById('puck-name').textContent = (brush.name || 'BRUSH').toUpperCase();
  const sizeSlider = document.getElementById('puck-size-slider');
  sizeSlider.max = maxSize;
  sizeSlider.value = brush.size;
  document.getElementById('puck-size-val').textContent = brush.size;
  document.getElementById('puck-alpha-slider').value = Math.round(brush.opacity * 100);
  document.getElementById('puck-alpha-val').textContent = Math.round(brush.opacity * 100);
  // Active state is reflected by the grouped rail
  document.querySelectorAll('.tool').forEach(t => t.classList.remove('active'));
  state.tool = brush.builtIn ? brush.id : 'pen';   // custom brushes draw via the pen path
  if (typeof highlightRailGroups === 'function') highlightRailGroups();
  updatePreview();
}

// Tool buttons: single tap selects; tapping the ALREADY-active tool again
// opens that tool's settings (Procreate-style double-tap).
let _lastToolTap = { tool: null, time: 0 };
document.querySelectorAll('.tool').forEach(btn => {
  btn.addEventListener('click', (e) => {
    e.stopPropagation();   // don't let document close-on-outside fire
    const tool = btn.dataset.tool;
    const now = Date.now();
    const wasActive = (state.tool === tool) || (tool === 'brushes');
    const isDoubleTap = (_lastToolTap.tool === tool && now - _lastToolTap.time < 400);
    _lastToolTap = { tool, time: now };

    if (tool === 'brushes') { setTool('brushes'); return; }

    if (BRUSH_FAMILIES[tool]) {
      const fam = tool;
      const wasFamActive = BRUSH_FAMILIES[fam].includes(state.tool);
      state.brushLast = state.brushLast || {};
      const last = state.brushLast[fam] || fam;
      setTool(last);
      if (wasFamActive || isDoubleTap) openBrushFlyout(fam, btn);
      return;
    }

    setTool(tool);

    if (wasActive || isDoubleTap) {
      openToolSettings(tool);
    }
  });
});

// ===== Grouped rail: collapse the 20-tool strip into category buttons =====
const TOOL_GROUPS = [
  { id: 'draw',     label: 'Draw',           tools: ['pen','marker','pencil','brush','watercolour','eraser','brushes'] },
  { id: 'shapes',   label: 'Shapes',         tools: ['line','rect','circle'] },
  { id: 'fillstamp',label: 'Fill / Stamp',   tools: ['fill','stencil'] },
  { id: 'region',   label: 'Region',         tools: ['wand','lasso'] },
  { id: 'measure',  label: 'Measure / Area', tools: ['ruler','area'] },
  { id: 'build',    label: 'Build',          tools: ['wall','opening'] },
];
let _railMeta = {};
function _groupOf(toolId) { return TOOL_GROUPS.find(g => g.tools.includes(toolId)); }
function activateRailTool(t) { if (t === 'brushes') openBrushLibrary(); else setTool(t); }

function regroupRail() {
  const rail = document.querySelector('.rail');
  if (!rail || rail.dataset.grouped) return;
  // capture each tool's icon + clean name from the existing buttons
  rail.querySelectorAll('.tool').forEach(b => {
    const t = b.dataset.tool; if (!t) return;
    const svg = b.querySelector('svg');
    const lbl = (b.querySelector('.label')?.textContent || t).replace(/\s·.*$/, '');
    _railMeta[t] = { svg: svg ? svg.outerHTML : '', label: lbl };
  });
  if (!document.getElementById('grp-flyout-style')) {
    const st = document.createElement('style'); st.id = 'grp-flyout-style';
    st.textContent =
      '#grp-flyout{position:fixed;z-index:1400;display:flex;flex-direction:column;gap:3px;background:#1c1a18;border:1px solid rgba(255,255,255,0.12);border-radius:12px;padding:6px;box-shadow:0 12px 34px rgba(0,0,0,0.5);min-width:172px;}'
    + '#grp-flyout .gfi{display:flex;align-items:center;gap:11px;font:600 12px ui-sans-serif,system-ui;color:#e8e4de;padding:9px 12px;border-radius:8px;cursor:pointer;background:transparent;border:none;text-align:left;width:100%;}'
    + '#grp-flyout .gfi:hover{background:#2b2826;}#grp-flyout .gfi.on{background:#a02835;color:#fff;}'
    + '#grp-flyout .gfi svg{width:18px;height:18px;flex:0 0 18px;}';
    document.head.appendChild(st);
  }
  state.groupLast = {};
  TOOL_GROUPS.forEach(g => state.groupLast[g.id] = g.tools[0]);
  rail.innerHTML = '';
  rail.dataset.grouped = '1';

  const mkBtn = (iconTool, labelTxt) => {
    const b = document.createElement('button');
    b.className = 'tool';
    b.title = labelTxt;
    b.innerHTML = `${_railMeta[iconTool]?.svg || ''}<span class="label">${labelTxt}</span>`;
    rail.appendChild(b);
    return b;
  };
  // Top-level Select (arrow) — picks an entity and offers edit/delete
  const selBtn = document.createElement('button');
  selBtn.className = 'tool'; selBtn.dataset.tool = 'select'; selBtn.title = 'Select';
  selBtn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 3l6.5 17 2.4-7.1L20 10.5 4 3z"/></svg><span class="label">Select</span>';
  selBtn.addEventListener('click', e => { e.stopPropagation(); setTool('select'); });
  rail.appendChild(selBtn);
  // Top-level Offset (concentric) — offset a room boundary in/out
  const offBtn = document.createElement('button');
  offBtn.className = 'tool'; offBtn.dataset.tool = 'offset'; offBtn.title = 'Offset';
  offBtn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="1"/><rect x="7.5" y="7.5" width="9" height="9" rx="1"/></svg><span class="label">Offset</span>';
  offBtn.addEventListener('click', e => { e.stopPropagation(); setTool('offset'); });
  rail.appendChild(offBtn);
  const topDiv = document.createElement('div'); topDiv.className = 'rail-divider'; rail.appendChild(topDiv);
  TOOL_GROUPS.forEach(g => {
    const btn = mkBtn(g.tools[0], g.label);
    btn.dataset.group = g.id;
    btn.addEventListener('click', e => {
      e.stopPropagation();
      const active = g.tools.includes(state.tool) || g.tools.includes(brushFamilyOf(state.tool));
      if (active && g.tools.length > 1) { openGroupFlyout(g, btn); return; }
      activateRailTool(state.groupLast[g.id] || g.tools[0]);
    });
    let lp;
    btn.addEventListener('pointerdown', () => { lp = setTimeout(() => openGroupFlyout(g, btn), 450); });
    ['pointerup','pointerleave','pointercancel'].forEach(ev => btn.addEventListener(ev, () => clearTimeout(lp)));
  });
  const div = document.createElement('div'); div.className = 'rail-divider'; rail.appendChild(div);
  const b3d = mkBtn('massing', '3D'); b3d.dataset.tool = 'massing';
  b3d.addEventListener('click', e => { e.stopPropagation(); setTool('massing'); });
  rail.appendChild(b3d);
  const bpan = mkBtn('hand', 'Pan'); bpan.dataset.tool = 'hand';
  bpan.addEventListener('click', e => { e.stopPropagation(); setTool('hand'); });
  rail.appendChild(bpan);
  highlightRailGroups();
}

function updateGroupIcon(g) {
  const btn = document.querySelector(`.rail .tool[data-group="${g.id}"]`); if (!btn) return;
  const t = state.groupLast[g.id] || g.tools[0];
  const lbl = btn.querySelector('.label');
  btn.innerHTML = `${_railMeta[t]?.svg || ''}`;
  if (lbl) btn.appendChild(lbl);
}

let _grpFlyout = null;
function closeGroupFlyout() { if (_grpFlyout) { _grpFlyout.remove(); _grpFlyout = null; } }
function openGroupFlyout(g, btn) {
  closeGroupFlyout();
  const fly = document.createElement('div'); fly.id = 'grp-flyout';
  g.tools.forEach(t => {
    const it = document.createElement('button'); it.className = 'gfi';
    it.innerHTML = `${_railMeta[t]?.svg || ''}<span>${_railMeta[t]?.label || t}</span>`;
    if (t === state.tool) it.classList.add('on');
    it.addEventListener('click', e => {
      e.stopPropagation();
      if (t === 'brushes') { openBrushLibrary(); }
      else { state.groupLast[g.id] = t; setTool(t); updateGroupIcon(g); }
      closeGroupFlyout();
    });
    fly.appendChild(it);
  });
  document.body.appendChild(fly);
  const r = btn.getBoundingClientRect();
  fly.style.left = (r.right + 8) + 'px';
  fly.style.top = Math.max(8, Math.min(r.top, window.innerHeight - fly.offsetHeight - 8)) + 'px';
  _grpFlyout = fly;
  setTimeout(() => document.addEventListener('click', closeGroupFlyout, { once: true }), 0);
}

function highlightRailGroups() {
  const rail = document.querySelector('.rail'); if (!rail || !rail.dataset.grouped) return;
  const activeTool = massing.active ? 'massing' : state.tool;
  const inGroup = (g, t) => g.tools.includes(t) || g.tools.includes(brushFamilyOf(t));
  rail.querySelectorAll('.tool[data-group]').forEach(b => {
    const g = TOOL_GROUPS.find(x => x.id === b.dataset.group);
    b.classList.toggle('active', !!g && !massing.active && inGroup(g, activeTool));
  });
  rail.querySelectorAll('.tool[data-tool]').forEach(b => b.classList.toggle('active', b.dataset.tool === activeTool));
  // a group button shows the active base tool's icon (variants keep the family icon)
  TOOL_GROUPS.forEach(g => { if (state.groupLast && g.tools.includes(state.tool)) { state.groupLast[g.id] = state.tool; updateGroupIcon(g); } });
}

// ---- rail flyout: pick a pen / pencil variant ----
let _brushFlyout = null;
function ensureBrushFlyout() {
  if (_brushFlyout) return _brushFlyout;
  const style = document.createElement('style');
  style.textContent =
    '#brush-flyout{position:fixed;z-index:1300;display:none;flex-direction:column;gap:3px;background:#1c1a18;border:1px solid rgba(255,255,255,0.12);border-radius:12px;padding:6px;box-shadow:0 12px 34px rgba(0,0,0,0.5);min-width:170px;}' +
    '#brush-flyout .bfi{display:flex;align-items:center;gap:11px;font:600 12px ui-sans-serif,system-ui;color:#e8e4de;padding:9px 12px;border-radius:8px;cursor:pointer;background:transparent;border:none;text-align:left;width:100%;}' +
    '#brush-flyout .bfi:hover{background:#2b2826;}' +
    '#brush-flyout .bfi.on{background:#a02835;color:#fff;}' +
    '#brush-flyout .bfi .sw{width:26px;border-radius:3px;background:currentColor;opacity:0.9;flex-shrink:0;}';
  document.head.appendChild(style);
  const el = document.createElement('div'); el.id = 'brush-flyout';
  el.addEventListener('pointerdown', e => e.stopPropagation());
  document.body.appendChild(el); _brushFlyout = el;
  document.addEventListener('pointerdown', () => { if (_brushFlyout) _brushFlyout.style.display = 'none'; });
  return el;
}
function openBrushFlyout(fam, anchorBtn) {
  const el = ensureBrushFlyout(); el.innerHTML = '';
  (BRUSH_FAMILIES[fam] || []).forEach(id => {
    const b = BUILTIN_BRUSHES.find(x => x.id === id); if (!b) return;
    const item = document.createElement('button'); item.className = 'bfi' + (state.tool === id ? ' on' : '');
    const sw = document.createElement('span'); sw.className = 'sw'; sw.style.height = Math.max(2, Math.min(8, b.size)) + 'px';
    const nm = document.createElement('span'); nm.textContent = b.name;
    item.append(sw, nm);
    item.onclick = (ev) => { ev.stopPropagation(); state.brushLast = state.brushLast || {}; state.brushLast[fam] = id; setTool(id); el.style.display = 'none'; };
    el.appendChild(item);
  });
  const r = anchorBtn.getBoundingClientRect();
  el.style.display = 'flex';
  const fr = el.getBoundingClientRect();
  let top = r.top; if (top + fr.height > window.innerHeight - 8) top = window.innerHeight - 8 - fr.height;
  el.style.left = (r.right + 8) + 'px';
  el.style.top = Math.max(8, top) + 'px';
}

// Open the settings panel appropriate to each tool
function openToolSettings(tool) {
  if (isDrawTool(tool)) {
    openBrushLibrary();
  } else if (tool === 'stencil') {
    showStencilPopover();   // setTool already opens it; re-tap re-opens if closed
  } else if (tool === 'fill' || tool === 'wand' || tool === 'lasso') {
    document.getElementById('puck-color').click();  // colour popover holds tolerance + fill source
  }
  // ruler/area have no extra settings panel — selecting them is enough
}

function showStencilPopover() {
  const puckRect = document.getElementById('puck').getBoundingClientRect();
  const areaRect = area.getBoundingClientRect();
  stencilPopover.style.left = '24px';
  stencilPopover.style.bottom = '80px';
  stencilPopover.style.right = '';
  stencilPopover.style.top = '';
  stencilPopover.classList.add('show');
  renderStencils();
}

/* =================== BRUSH LIBRARY =================== */
const brushLibrary = document.getElementById('brush-library');
const brushModal = document.getElementById('brush-modal');

function openBrushLibrary() {
  // anchor above the puck, centered
  const puckRect = document.getElementById('puck').getBoundingClientRect();
  const areaRect = area.getBoundingClientRect();
  const desiredLeft = puckRect.left + puckRect.width/2 - 170 - areaRect.left;
  brushLibrary.style.left = Math.max(20, Math.min(areaRect.width - 360, desiredLeft)) + 'px';
  brushLibrary.style.bottom = (areaRect.height - (puckRect.top - areaRect.top) + 10) + 'px';
  brushLibrary.style.display = 'block';   // override inline display:none
  brushLibrary.classList.add('show');
  renderBrushList();
}

function closeBrushLibrary() {
  brushLibrary.style.display = 'none';    // override inline + class
  brushLibrary.classList.remove('show');
  // restore tool active state
  document.getElementById('rail-brushes')?.classList.remove('active');
  const cur = activeBrush();
  if (cur && cur.builtIn) {
    const btn = document.querySelector(`.tool[data-tool="${cur.id}"]`);
    if (btn) btn.classList.add('active');
  }
}

document.getElementById('brush-lib-close').addEventListener('click', closeBrushLibrary);

document.getElementById('rail-brushes')?.addEventListener('click', (e) => {
  e.stopPropagation();
  // override default setTool routing
});

// click outside closes
document.addEventListener('click', (e) => {
  if (brushLibrary.classList.contains('show') &&
      !e.target.closest('#brush-library') &&
      !e.target.closest('#rail-brushes') &&
      !e.target.closest('#puck-name')) {
    closeBrushLibrary();
  }
});

function renderBrushList() {
  const list = document.getElementById('brush-list');
  list.innerHTML = '';

  // Built-in group
  const builtinLabel = document.createElement('div');
  builtinLabel.className = 'brush-group-label';
  builtinLabel.textContent = 'Built-in';
  list.appendChild(builtinLabel);
  BUILTIN_BRUSHES.forEach(b => list.appendChild(renderBrushCard(b)));

  // Custom group
  const customLabel = document.createElement('div');
  customLabel.className = 'brush-group-label';
  customLabel.textContent = `My Brushes${state.customBrushes.length ? ' · ' + state.customBrushes.length : ''}`;
  list.appendChild(customLabel);
  if (state.customBrushes.length === 0) {
    const empty = document.createElement('div');
    empty.style.cssText = 'padding:12px;font-size:11px;color:var(--muted);text-align:center;';
    empty.textContent = 'No custom brushes yet. Create one below.';
    list.appendChild(empty);
  } else {
    state.customBrushes.forEach((b, i) => list.appendChild(renderBrushCard(b, i)));
  }
}

function renderBrushCard(brush, customIndex) {
  const div = document.createElement('div');
  div.className = 'brush-card' + (state.activeBrush && state.activeBrush.id === brush.id ? ' active' : '');

  // preview canvas
  const previewWrap = document.createElement('div');
  previewWrap.className = 'brush-card-preview';
  const cv = document.createElement('canvas');
  cv.width = 140; cv.height = 56;
  cv.style.cssText = 'width:100%;height:100%;';
  previewWrap.appendChild(cv);
  div.appendChild(previewWrap);

  // info
  const info = document.createElement('div');
  info.className = 'brush-card-info';
  const name = document.createElement('div');
  name.className = 'brush-card-name';
  name.textContent = brush.name;
  const meta = document.createElement('div');
  meta.className = 'brush-card-meta';
  meta.textContent = `${brush.tipType.toUpperCase()} · ${brush.size}px · ${Math.round(brush.opacity*100)}%`;
  info.appendChild(name);
  info.appendChild(meta);
  div.appendChild(info);

  // actions
  const acts = document.createElement('div');
  acts.className = 'brush-card-actions';
  if (!brush.builtIn) {
    const editBtn = document.createElement('button');
    editBtn.className = 'brush-card-act';
    editBtn.title = 'Edit';
    editBtn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 19l7-7 3 3-7 7-3-3z"/><path d="M18 13l-1.5-7.5L2 2l3.5 14.5L13 18l5-5z"/></svg>';
    editBtn.addEventListener('click', (e) => { e.stopPropagation(); openBrushEditor(brush, customIndex); });
    acts.appendChild(editBtn);

    const dupBtn = document.createElement('button');
    dupBtn.className = 'brush-card-act';
    dupBtn.title = 'Duplicate';
    dupBtn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>';
    dupBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      const dup = JSON.parse(JSON.stringify(brush));
      dup.id = 'b' + Date.now();
      dup.name = brush.name + ' Copy';
      state.customBrushes.push(dup);
      persistBrushes();
      renderBrushList();
    });
    acts.appendChild(dupBtn);

    const delBtn = document.createElement('button');
    delBtn.className = 'brush-card-act';
    delBtn.title = 'Delete';
    delBtn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L5 6"/></svg>';
    delBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (confirm(`Delete "${brush.name}"?`)) {
        state.customBrushes.splice(customIndex, 1);
        persistBrushes();
        renderBrushList();
      }
    });
    acts.appendChild(delBtn);
  }
  div.appendChild(acts);

  // click select
  div.addEventListener('click', () => {
    setActiveBrush(brush);
    renderBrushList();
    closeBrushLibrary();
    showHint(`Brush: ${brush.name}`);
  });

  // draw preview stroke after attach (so we can read size correctly)
  setTimeout(() => drawBrushPreview(cv, brush), 0);

  return div;
}

function drawBrushPreview(canvas, brush) {
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  const points = [];
  for (let i = 0; i <= 40; i++) {
    const t = i / 40;
    const x = 8 + t * (canvas.width - 16);
    const y = canvas.height/2 + Math.sin(t * Math.PI * 2.5) * 14;
    points.push({ x, y, pressure: 0.25 + Math.sin(t * Math.PI) * 0.7 });
  }
  if (brush.tipType === 'texture' && brush.tipImage) {
    const img = getTipImage(brush.tipImage);
    if (!img) { setTimeout(() => drawBrushPreview(canvas, brush), 100); return; }
    const previewBrush = { ...brush, size: Math.min(brush.size, 22) };
    const savedColor = state.color;
    state.color = '#0a0a0a';
    let last = points[0];
    let accum = 0;
    for (let i = 1; i < points.length; i++) {
      const p = points[i];
      const dx = p.x - last.x, dy = p.y - last.y;
      const d = Math.sqrt(dx*dx + dy*dy);
      const effSize = Math.max(2, previewBrush.size * (1 - previewBrush.pressureSize + previewBrush.pressureSize * p.pressure));
      const step = Math.max(0.5, previewBrush.spacing * effSize);
      accum += d;
      while (accum >= step) {
        const overshoot = accum - step;
        const t2 = (d - overshoot) / d;
        const sx = last.x + dx * t2;
        const sy = last.y + dy * t2;
        stampTexture(ctx, previewBrush, sx, sy, p.pressure);
        last = { x: sx, y: sy };
        accum = overshoot;
      }
      last = p;
    }
    state.color = savedColor;
  } else {
    // simulated stroke
    const previewBrush = { ...brush, size: Math.min(brush.size, 22) };
    const savedColor = state.color;
    const savedSize = state.size;
    const savedAlpha = state.alpha;
    state.color = '#0a0a0a';
    state.size = previewBrush.size;
    state.alpha = previewBrush.opacity;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    for (let i = 1; i < points.length; i++) {
      const p = points[i], q = points[i-1];
      configurePen(ctx, p.pressure, previewBrush);
      ctx.beginPath();
      ctx.moveTo(q.x, q.y);
      ctx.lineTo(p.x, p.y);
      ctx.stroke();
    }
    state.color = savedColor;
    state.size = savedSize;
    state.alpha = savedAlpha;
  }
}

document.getElementById('brush-new-btn').addEventListener('click', () => openBrushEditor());

/* =================================================================
   BRUSH IMPORT — PNG/JPG images, Photoshop .abr, Sketchbook/Procreate
   ================================================================= */
document.getElementById('brush-import-btn').addEventListener('click', () =>
  document.getElementById('brush-import-file').click());

document.getElementById('brush-import-file').addEventListener('change', async (e) => {
  const files = Array.from(e.target.files);
  e.target.value = '';
  let imported = 0;
  for (const file of files) {
    const lower = file.name.toLowerCase();
    try {
      if (lower.endsWith('.abr')) {
        imported += await importABR(file);
      } else if (lower.endsWith('.brushset') || lower.endsWith('.brush') || lower.endsWith('.skbrush') || lower.endsWith('.zip')) {
        imported += await importBrushArchive(file);
      } else {
        // Plain image → stamp brush
        const dataUrl = await fileToDataURL(file);
        addImportedTipBrush(file.name.replace(/\.[^.]+$/, ''), dataUrl);
        imported++;
      }
    } catch (err) {
      console.warn('Brush import failed for', file.name, err);
    }
  }
  persistBrushes();
  renderBrushList();
  showHint(imported ? `Imported ${imported} brush${imported>1?'es':''}` : 'No brushes could be read from that file');
});

function fileToDataURL(file) {
  return new Promise((res, rej) => {
    const r = new FileReader();
    r.onload = () => res(r.result);
    r.onerror = rej;
    r.readAsDataURL(file);
  });
}

// Build a texture (stamp) brush from a tip image dataURL.
// White/opaque areas of the tip become the active colour when drawn.
function addImportedTipBrush(name, dataUrl) {
  const brush = {
    id: 'imp' + Date.now() + Math.random().toString(36).slice(2,6),
    name: name.slice(0, 40) || 'Imported',
    tipType: 'texture',
    tipImage: dataUrl,
    size: 28,
    opacity: 1,
    spacing: 0.08,
    hardness: 0.7,
    pressureSize: 0.6,
    pressureOpacity: 0.2,
    jitter: 0,
    blend: 'source-over',
    kind: 'draw',
    builtIn: false,
  };
  state.customBrushes.push(brush);
}

// Convert raw RGBA/grayscale tip pixels to a tinted PNG dataURL.
function tipPixelsToDataURL(width, height, getAlpha) {
  const c = document.createElement('canvas');
  c.width = width; c.height = height;
  const ctx = c.getContext('2d');
  const img = ctx.createImageData(width, height);
  for (let i = 0; i < width * height; i++) {
    const a = getAlpha(i);
    img.data[i*4] = 0; img.data[i*4+1] = 0; img.data[i*4+2] = 0;
    img.data[i*4+3] = a;
  }
  ctx.putImageData(img, 0, 0);
  return c.toDataURL('image/png');
}

// ---- Photoshop .abr parser (sampled brushes) ----
// Supports the common sampled-brush records in v1/v2 and v6+ (8BIM 'samp').
// Parametric (computed) brushes are skipped — only bitmap tips are extracted.
async function importABR(file) {
  const buf = await file.arrayBuffer();
  const dv = new DataView(buf);
  let count = 0;
  const version = dv.getUint16(0, false);

  function readBitmapTip(pos) {
    // returns { dataUrl, next } or null
    return null;
  }

  if (version === 6 || version === 7 || version === 10) {
    // v6+ : look for 8BIM 'samp' section, then parse sampled brush blocks
    let p = 0;
    // subversion at offset 2
    // Scan for '8BIM' 'samp'
    const sig = '8BIM', tag = 'samp';
    function matchAt(o, s) {
      for (let i=0;i<s.length;i++) if (dv.getUint8(o+i)!==s.charCodeAt(i)) return false;
      return true;
    }
    while (p < buf.byteLength - 8) {
      if (matchAt(p, sig) && matchAt(p+4, tag)) {
        const len = dv.getUint32(p+8, false);
        let q = p + 12;
        const end = q + len;
        // Within samp section: each brush = 4-byte len + key(37 bytes) + data
        while (q < end - 4) {
          const blockLen = dv.getUint32(q, false); q += 4;
          const blockStart = q;
          // key string (37 bytes) then bounds rect (4×i32) then depth, compression...
          q += 37;
          if (q + 24 > end) break;
          const top = dv.getInt32(q, false), left = dv.getInt32(q+4, false),
                bottom = dv.getInt32(q+8, false), right = dv.getInt32(q+12, false);
          q += 16;
          const depth = dv.getUint16(q, false); q += 2;
          const compression = dv.getUint8(q); q += 1;
          const w = right - left, h = bottom - top;
          if (w > 0 && h > 0 && w <= 4096 && h <= 4096) {
            const px = new Uint8Array(w * h);
            try {
              if (compression === 0) {
                for (let i=0;i<w*h;i++) px[i] = dv.getUint8(q+i);
              } else {
                // RLE (PackBits) per row
                const rowLens = [];
                let rp = q;
                for (let y=0;y<h;y++){ rowLens.push(dv.getUint16(rp,false)); rp+=2; }
                let out = 0;
                for (let y=0;y<h;y++){
                  let bytes = rowLens[y];
                  let consumed = 0;
                  while (consumed < bytes) {
                    const n = (dv.getInt8(rp)); rp++; consumed++;
                    if (n >= 0) { for (let k=0;k<=n;k++){ px[out++]=dv.getUint8(rp); rp++; consumed++; } }
                    else if (n !== -128) { const val=dv.getUint8(rp); rp++; consumed++; for(let k=0;k<1-n;k++) px[out++]=val; }
                  }
                }
              }
              // ABR sampled tips: 0=black..255=white; brush uses darkness as alpha
              const dataUrl = tipPixelsToDataURL(w, h, i => px[i]); // white→opaque tint
              addImportedTipBrush(file.name.replace(/\.abr$/i,'') + ' ' + (count+1), dataUrl);
              count++;
            } catch(_) {}
          }
          q = blockStart + blockLen;
          // pad to even
          if (blockLen % 2 === 1) q++;
        }
        p = end;
      } else {
        p++;
      }
    }
  } else if (version === 1 || version === 2) {
    // Older format: count at offset 2, then brush records
    let p = 2;
    const n = dv.getUint16(p, false); p += 2;
    for (let b=0; b<n && p < buf.byteLength-6; b++) {
      const type = dv.getUint16(p, false); p += 2;
      const len = dv.getUint32(p, false); p += 4;
      const recStart = p;
      if (type === 2) { // sampled
        p += 4; // misc
        p += 2; // spacing
        // name (Pascal/Unicode varies) — skip via record length
        // bounds
        try {
          // Heuristic: bounds appear near start; fall back to skipping
        } catch(_) {}
      }
      p = recStart + len;
    }
  }
  return count;
}

// ---- Sketchbook / Procreate / generic ZIP brush sets ----
// These are ZIP archives. We extract any PNG tip images and make stamp brushes.
async function importBrushArchive(file) {
  const buf = await file.arrayBuffer();
  let entries = parseZip(new Uint8Array(buf));
  entries = await inflateEntries(entries);
  let count = 0;
  for (const ent of entries) {
    const nameLower = ent.name.toLowerCase();
    const isPng = nameLower.endsWith('.png');
    const looksLikeTip = /(shape|grain|tip|brush|stamp|texture)/.test(nameLower);
    if (isPng && (looksLikeTip || ent.data.length > 200)) {
      try {
        const blob = new Blob([ent.data], { type: 'image/png' });
        const dataUrl = await blobToDataURL(blob);
        const base = file.name.replace(/\.[^.]+$/,'');
        const tipName = ent.name.replace(/.*\//,'').replace(/\.png$/i,'');
        addImportedTipBrush(`${base} · ${tipName}`, dataUrl);
        count++;
        if (count >= 30) break;
      } catch(_) {}
    }
  }
  return count;
}

function blobToDataURL(blob) {
  return new Promise((res, rej) => {
    const r = new FileReader();
    r.onload = () => res(r.result); r.onerror = rej;
    r.readAsDataURL(blob);
  });
}

// Minimal ZIP reader (stored + deflate) using DecompressionStream when available.
function parseZip(bytes) {
  const entries = [];
  const dv = new DataView(bytes.buffer);
  // Find End Of Central Directory
  let eocd = -1;
  for (let i = bytes.length - 22; i >= 0; i--) {
    if (dv.getUint32(i, true) === 0x06054b50) { eocd = i; break; }
  }
  if (eocd < 0) return entries;
  const cdOffset = dv.getUint32(eocd + 16, true);
  const cdCount = dv.getUint16(eocd + 10, true);
  let p = cdOffset;
  const pending = [];
  for (let i = 0; i < cdCount; i++) {
    if (dv.getUint32(p, true) !== 0x02014b50) break;
    const method = dv.getUint16(p + 10, true);
    const compSize = dv.getUint32(p + 20, true);
    const nameLen = dv.getUint16(p + 28, true);
    const extraLen = dv.getUint16(p + 30, true);
    const commentLen = dv.getUint16(p + 32, true);
    const localOffset = dv.getUint32(p + 42, true);
    const name = new TextDecoder().decode(bytes.subarray(p + 46, p + 46 + nameLen));
    pending.push({ name, method, compSize, localOffset });
    p += 46 + nameLen + extraLen + commentLen;
  }
  for (const ent of pending) {
    const lp = ent.localOffset;
    if (dv.getUint32(lp, true) !== 0x04034b50) continue;
    const nameLen = dv.getUint16(lp + 26, true);
    const extraLen = dv.getUint16(lp + 28, true);
    const dataStart = lp + 30 + nameLen + extraLen;
    const raw = bytes.subarray(dataStart, dataStart + ent.compSize);
    if (ent.method === 0) {
      entries.push({ name: ent.name, data: raw });
    } else if (ent.method === 8) {
      entries.push({ name: ent.name, data: raw, deflate: true });
    }
  }
  return entries;
}

// Inflate any deflated entries (async) — wraps importBrushArchive's sync use.
async function inflateEntries(entries) {
  const out = [];
  for (const e of entries) {
    if (e.deflate && typeof DecompressionStream !== 'undefined') {
      try {
        const ds = new DecompressionStream('deflate-raw');
        const stream = new Blob([e.data]).stream().pipeThrough(ds);
        const ab = await new Response(stream).arrayBuffer();
        out.push({ name: e.name, data: new Uint8Array(ab) });
      } catch (_) { /* skip */ }
    } else {
      out.push(e);
    }
  }
  return out;
}

