/* =================== COLOR =================== */
/* =================== COLOUR WHEEL (HSV) =================== */
// Internal colour state in HSV (0-360, 0-100, 0-100)
const hsv = { h: 0, s: 0, v: 0 };

function hsvToHex(h, s, v) {
  s /= 100; v /= 100;
  const c = v * s;
  const x = c * (1 - Math.abs((h / 60) % 2 - 1));
  const m = v - c;
  let r=0,g=0,b=0;
  if (h<60){r=c;g=x;}else if(h<120){r=x;g=c;}else if(h<180){g=c;b=x;}
  else if(h<240){g=x;b=c;}else if(h<300){r=x;b=c;}else{r=c;b=x;}
  const toHex = n => Math.round((n+m)*255).toString(16).padStart(2,'0');
  return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

function hexToHsv(hex) {
  const r = parseInt(hex.slice(1,3),16)/255;
  const g = parseInt(hex.slice(3,5),16)/255;
  const b = parseInt(hex.slice(5,7),16)/255;
  const max = Math.max(r,g,b), min = Math.min(r,g,b), d = max-min;
  let h=0,s=max===0?0:d/max,v=max;
  if(d>0){
    if(max===r) h=((g-b)/d+6)%6;
    else if(max===g) h=(b-r)/d+2;
    else h=(r-g)/d+4;
    h*=60;
  }
  return { h: Math.round(h), s: Math.round(s*100), v: Math.round(v*100) };
}

function hexToRgba(hex, alpha=255) {
  const r = parseInt(hex.slice(1,3),16);
  const g = parseInt(hex.slice(3,5),16);
  const b = parseInt(hex.slice(5,7),16);
  return [r, g, b, alpha];
}

function hsvToHarmony(h, s, v) {
  return [
    hsvToHex(h, s, v),
    hsvToHex((h+180)%360, s, v),
    hsvToHex((h+120)%360, s, v),
    hsvToHex((h+240)%360, s, v),
    hsvToHex((h+30)%360, s, v),
  ];
}

// Draw the hue ring
function drawHueWheel() {
  const canvas = document.getElementById('hue-wheel');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const cx = canvas.width/2, cy = canvas.height/2;
  const outerR = cx - 4, innerR = outerR - 22;
  for (let a = 0; a < 360; a++) {
    const start = (a - 1) * Math.PI / 180;
    const end = (a + 1) * Math.PI / 180;
    ctx.beginPath();
    ctx.moveTo(cx + innerR * Math.cos(start), cy + innerR * Math.sin(start));
    ctx.arc(cx, cy, outerR, start, end);
    ctx.arc(cx, cy, innerR, end, start, true);
    ctx.closePath();
    ctx.fillStyle = `hsl(${a},100%,50%)`;
    ctx.fill();
  }
  // Ring overlay markers
  drawHueMarker();
}

function drawHueMarker() {
  const canvas = document.getElementById('hue-wheel');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const cx = canvas.width/2, cy = canvas.height/2;
  const outerR = cx - 4, innerR = outerR - 22, midR = (outerR + innerR) / 2;
  const a = (hsv.h - 90) * Math.PI / 180;
  const mx = cx + midR * Math.cos(a);
  const my = cy + midR * Math.sin(a);
  ctx.beginPath();
  ctx.arc(mx, my, 9, 0, Math.PI*2);
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.strokeStyle = '#333';
  ctx.lineWidth = 1.5;
  ctx.stroke();
}

// Draw the SV square
function drawSVSquare() {
  const canvas = document.getElementById('sv-square');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const w = canvas.width, h = canvas.height;
  // Saturation gradient left-right
  const gS = ctx.createLinearGradient(0, 0, w, 0);
  gS.addColorStop(0, '#fff');
  gS.addColorStop(1, `hsl(${hsv.h},100%,50%)`);
  ctx.fillStyle = gS;
  ctx.fillRect(0, 0, w, h);
  // Value gradient top-bottom (white to black)
  const gV = ctx.createLinearGradient(0, 0, 0, h);
  gV.addColorStop(0, 'rgba(0,0,0,0)');
  gV.addColorStop(1, 'rgba(0,0,0,1)');
  ctx.fillStyle = gV;
  ctx.fillRect(0, 0, w, h);
  // Marker
  const mx = (hsv.s / 100) * w;
  const my = (1 - hsv.v / 100) * h;
  ctx.beginPath();
  ctx.arc(mx, my, 8, 0, Math.PI*2);
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.strokeStyle = '#333';
  ctx.lineWidth = 1.5;
  ctx.stroke();
}

function syncWheelFromColor(hex) {
  const h = hexToHsv(hex);
  hsv.h = h.h; hsv.s = h.s; hsv.v = h.v;
  drawSVSquare();
  drawHueWheel();
  updateWheelSliders();
  updateHarmony();
  document.getElementById('color-swatch-display').style.background = hex;
  document.getElementById('wheel-hex').value = hex.toUpperCase();
}

function updateWheelSliders() {
  document.getElementById('sl-h').value = hsv.h;
  document.getElementById('sl-h-v').textContent = Math.round(hsv.h);
  document.getElementById('sl-s').value = hsv.s;
  document.getElementById('sl-s-v').textContent = Math.round(hsv.s);
  document.getElementById('sl-v').value = hsv.v;
  document.getElementById('sl-v-v').textContent = Math.round(hsv.v);
}

function updateHarmony() {
  const row = document.getElementById('harmony-row');
  if (!row) return;
  row.innerHTML = '';
  hsvToHarmony(hsv.h, hsv.s, hsv.v).forEach(c => {
    const sw = document.createElement('div');
    sw.className = 'harmony-swatch';
    sw.style.background = c;
    sw.title = c;
    sw.addEventListener('click', () => { setColor(c); });
    row.appendChild(sw);
  });
}

function initWheelEvents() {
  const hueCanvas = document.getElementById('hue-wheel');
  const svCanvas = document.getElementById('sv-square');
  if (!hueCanvas || !svCanvas) return;

  function onHueDrag(e) {
    e.preventDefault();
    const rect = hueCanvas.getBoundingClientRect();
    const cx = rect.width/2, cy = rect.height/2;
    const ex = (e.clientX || e.touches?.[0]?.clientX) - rect.left - cx;
    const ey = (e.clientY || e.touches?.[0]?.clientY) - rect.top - cy;
    hsv.h = Math.round((Math.atan2(ey, ex) * 180 / Math.PI + 90 + 360) % 360);
    drawHueWheel();
    drawSVSquare();
    const hex = hsvToHex(hsv.h, hsv.s, hsv.v);
    setColor(hex);
    updateWheelSliders();
    updateHarmony();
  }
  function onSVDrag(e) {
    e.preventDefault();
    const rect = svCanvas.getBoundingClientRect();
    const ex = Math.max(0, Math.min(rect.width, (e.clientX || e.touches?.[0]?.clientX) - rect.left));
    const ey = Math.max(0, Math.min(rect.height, (e.clientY || e.touches?.[0]?.clientY) - rect.top));
    hsv.s = Math.round((ex / rect.width) * 100);
    hsv.v = Math.round((1 - ey / rect.height) * 100);
    drawSVSquare();
    const hex = hsvToHex(hsv.h, hsv.s, hsv.v);
    setColor(hex);
    updateWheelSliders();
    updateHarmony();
  }
  // Hue ring
  hueCanvas.addEventListener('pointerdown', e => {
    hueCanvas.setPointerCapture(e.pointerId);
    onHueDrag(e);
    const move = ev => onHueDrag(ev);
    const up = () => { document.removeEventListener('pointermove', move); document.removeEventListener('pointerup', up); };
    document.addEventListener('pointermove', move);
    document.addEventListener('pointerup', up);
  });
  // SV square
  svCanvas.addEventListener('pointerdown', e => {
    svCanvas.setPointerCapture(e.pointerId);
    onSVDrag(e);
    const move = ev => onSVDrag(ev);
    const up = () => { document.removeEventListener('pointermove', move); document.removeEventListener('pointerup', up); };
    document.addEventListener('pointermove', move);
    document.addEventListener('pointerup', up);
  });
  // Sliders
  ['h','s','v'].forEach(ch => {
    document.getElementById(`sl-${ch}`).addEventListener('input', e => {
      hsv[ch] = parseInt(e.target.value);
      document.getElementById(`sl-${ch}-v`).textContent = hsv[ch];
      drawSVSquare();
      if (ch === 'h') drawHueWheel();
      const hex = hsvToHex(hsv.h, hsv.s, hsv.v);
      setColor(hex);
      updateHarmony();
      document.getElementById('wheel-hex').value = hex.toUpperCase();
    });
  });
  // Hex input
  document.getElementById('wheel-hex').addEventListener('change', e => {
    let v = e.target.value.trim();
    if (!v.startsWith('#')) v = '#' + v;
    if (/^#[0-9a-f]{6}$/i.test(v)) { setColor(v); }
  });
}

function renderSwatches() {
  const cont = document.getElementById('swatches');
  if (!cont) return;
  cont.innerHTML = '';
  SWATCHES.forEach(c => {
    const sw = document.createElement('div');
    sw.className = 'swatch' + (c.toLowerCase() === state.color.toLowerCase() ? ' active' : '');
    sw.style.background = c;
    sw.addEventListener('click', () => { setColor(c); renderSwatches(); });
    cont.appendChild(sw);
  });
}

function setColor(c) {
  state.color = c;
  document.getElementById('puck-color').style.background = c;
  document.getElementById('color-swatch-display').style.background = c;
  document.getElementById('wheel-hex').value = c.toUpperCase();
  syncWheelFromColor(c);
  updatePreview();
  renderSwatches();
}

document.getElementById('puck-color').addEventListener('click', (e) => {
  e.stopPropagation();
  const puckRect = document.getElementById('puck').getBoundingClientRect();
  const areaRect = area.getBoundingClientRect();
  colorPopover.style.left = Math.max(8, puckRect.left - areaRect.left - 100) + 'px';
  colorPopover.style.top = '';
  colorPopover.style.bottom = '';
  const spaceBelow = areaRect.bottom - puckRect.bottom;
  const spaceAbove = puckRect.top - areaRect.top;
  if (spaceBelow >= 300 || spaceBelow >= spaceAbove) {
    colorPopover.style.bottom = (areaRect.height - (puckRect.top - areaRect.top) + 10) + 'px';
  } else {
    colorPopover.style.top = (puckRect.bottom - areaRect.top + 10) + 'px';
  }
  colorPopover.classList.toggle('show');
  if (colorPopover.classList.contains('show')) {
    drawHueWheel();
    drawSVSquare();
    updateHarmony();
    renderSwatches();
    // Show fill tolerance row only when fill tool active
    document.getElementById('fill-tolerance-row').style.display = (state.tool === 'fill' || state.tool === 'wand' || state.tool === 'lasso') ? 'block' : 'none';
  }
});

