/* =================== FLOOD FILL =================== */
// Flatten all visible layers (image + strokes, honouring opacity) into one ctx.
function flattenVisibleToCtx(ctx) {
  ctx.clearRect(0, 0, DOC_W_PX, DOC_H_PX);
  for (const l of state.layers) {
    if (l.visible === false) continue;
    ctx.save();
    ctx.globalAlpha = (l.opacity != null ? l.opacity : 1);
    if (l.imageCanvas && !l.imageBaked) ctx.drawImage(l.imageCanvas, 0, 0);
    ctx.drawImage(l.canvas, 0, 0);
    ctx.restore();
  }
}

let _thumbCanvas = null;
async function generateThumbnailBlob(maxW) {
  maxW = maxW != null ? maxW : 420;
  if (!state.layers.length || DOC_W_PX <= 0 || DOC_H_PX <= 0) return null;
  const tw = Math.min(maxW, DOC_W_PX);
  const th = Math.max(1, Math.round(tw * (DOC_H_PX / DOC_W_PX)));
  if (!_thumbCanvas) _thumbCanvas = document.createElement('canvas');
  _thumbCanvas.width = tw;
  _thumbCanvas.height = th;
  const tctx = _thumbCanvas.getContext('2d');
  tctx.fillStyle = state.paperBg || '#ffffff';
  tctx.fillRect(0, 0, tw, th);
  const full = document.createElement('canvas');
  full.width = DOC_W_PX;
  full.height = DOC_H_PX;
  flattenVisibleToCtx(full.getContext('2d'));
  tctx.drawImage(full, 0, 0, tw, th);
  return new Promise((resolve) => _thumbCanvas.toBlob(resolve, 'image/jpeg', 0.84));
}

async function saveThumbnailLocal(blob) {
  if (!blob) return;
  const db = await idb();
  if (!db) return;
  await new Promise((resolve, reject) => {
    const tx = db.transaction(AUTOSAVE_STORE, 'readwrite');
    tx.objectStore(AUTOSAVE_STORE).put({ blob, savedAt: Date.now() }, 'thumb-' + autosaveKey());
    tx.oncomplete = resolve;
    tx.onerror = () => reject(tx.error);
  });
}

let _thumbSyncTimer = null;
function syncProjectThumbnail(blob) {
  const pid = typeof window !== 'undefined' ? window.__SKETCHTRUDE_PROJECT_ID : null;
  if (!pid || pid === 'local' || !blob) return;
  clearTimeout(_thumbSyncTimer);
  _thumbSyncTimer = setTimeout(async () => {
    try {
      const fd = new FormData();
      fd.append('file', blob, 'preview.jpg');
      await fetch('/api/projects/' + pid + '/thumbnail', { method: 'POST', body: fd, credentials: 'same-origin' });
    } catch (_) { /* offline — local thumb still works */ }
  }, 1200);
}

let _projThumbTimer = null;
function scheduleThumbnail() {
  clearTimeout(_projThumbTimer);
  _projThumbTimer = setTimeout(async () => {
    if (state.drawing) { scheduleThumbnail(); return; }
    try {
      const blob = await generateThumbnailBlob();
      if (!blob) return;
      await saveThumbnailLocal(blob);
      syncProjectThumbnail(blob);
    } catch (_) {}
  }, 2500);
}

// Reusable scratch canvas for sampling composites.
let _sampleCanvas = null, _sampleCtx = null;
function sampleData(sampleAll) {
  if (!_sampleCanvas) {
    _sampleCanvas = document.createElement('canvas');
    _sampleCtx = _sampleCanvas.getContext('2d', { willReadFrequently: true });
  }
  if (_sampleCanvas.width !== DOC_W_PX || _sampleCanvas.height !== DOC_H_PX) {
    _sampleCanvas.width = DOC_W_PX; _sampleCanvas.height = DOC_H_PX;
  }
  if (sampleAll) {
    flattenVisibleToCtx(_sampleCtx);
  } else {
    const l = activeLayer();
    _sampleCtx.clearRect(0, 0, DOC_W_PX, DOC_H_PX);
    if (l.imageCanvas && !l.imageBaked) _sampleCtx.drawImage(l.imageCanvas, 0, 0);
    _sampleCtx.drawImage(l.canvas, 0, 0);
  }
  return _sampleCtx.getImageData(0, 0, DOC_W_PX, DOC_H_PX).data;
}

// Compute the contiguous region matching the seed pixel in `sample`, returns a mask.
function computeFillMask(sample, startX, startY, tolerance) {
  const w = DOC_W_PX, h = DOC_H_PX;
  startX = Math.max(0, Math.min(w - 1, Math.round(startX)));
  startY = Math.max(0, Math.min(h - 1, Math.round(startY)));
  const seed = (startY * w + startX) * 4;
  const sr = sample[seed], sg = sample[seed+1], sb = sample[seed+2], sa = sample[seed+3];
  const mask = new Uint8Array(w * h);
  const match = (idx) =>
    Math.abs(sample[idx]-sr) + Math.abs(sample[idx+1]-sg) +
    Math.abs(sample[idx+2]-sb) + Math.abs(sample[idx+3]-sa) <= tolerance;
  const stack = [startX + startY * w];
  mask[startX + startY * w] = 1;
  while (stack.length) {
    const pos = stack.pop();
    let x = pos % w;
    const y = (pos / w) | 0;
    while (x > 0 && match(((y*w)+x-1)*4) && !mask[y*w+x-1]) x--;
    let spanA = false, spanB = false;
    while (x < w && match((y*w+x)*4)) {
      mask[y*w + x] = 1;
      if (y > 0) {
        const a = (y-1)*w + x;
        if (!mask[a] && match(a*4)) { if (!spanA) { stack.push(a); mask[a]=1; spanA=true; } }
        else spanA = false;
      }
      if (y < h-1) {
        const b = (y+1)*w + x;
        if (!mask[b] && match(b*4)) { if (!spanB) { stack.push(b); mask[b]=1; spanB=true; } }
        else spanB = false;
      }
      x++;
    }
  }
  return mask;
}

// Grow a mask by `r` pixels (so the fill tucks under anti-aliased boundary lines).
function expandMask(mask, r) {
  if (!r) return mask;
  const w = DOC_W_PX, h = DOC_H_PX;
  let cur = mask;
  for (let pass = 0; pass < r; pass++) {
    const next = new Uint8Array(cur);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y*w + x;
        if (cur[i]) continue;
        if ((x>0 && cur[i-1]) || (x<w-1 && cur[i+1]) || (y>0 && cur[i-w]) || (y<h-1 && cur[i+w])) next[i] = 1;
      }
    }
    cur = next;
  }
  return cur;
}

// Shrink a mask inward so fills stay inside line boundaries (prevents colour spill).
function shrinkMask(mask, r) {
  if (!r) return mask;
  const w = DOC_W_PX, h = DOC_H_PX;
  let cur = mask;
  for (let pass = 0; pass < r; pass++) {
    const next = new Uint8Array(cur);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y*w + x;
        if (!cur[i]) continue;
        if ((x>0 && !cur[i-1]) || (x<w-1 && !cur[i+1]) || (y>0 && !cur[i-w]) || (y<h-1 && !cur[i+w])) next[i] = 0;
      }
    }
    cur = next;
  }
  return cur;
}

// Paint a mask region with a flat colour onto ctx.
function paintMaskColor(ctx, mask, fillHex, fa) {
  const w = DOC_W_PX, h = DOC_H_PX;
  const [fr, fg, fb] = hexToRgba(fillHex);
  const target = ctx.getImageData(0, 0, w, h);
  const d = target.data;
  for (let i = 0; i < mask.length; i++) {
    if (mask[i]) { const o = i * 4; d[o] = fr; d[o+1] = fg; d[o+2] = fb; d[o+3] = fa; }
  }
  ctx.putImageData(target, 0, 0);
}

// Paint a mask region with an image texture (tiled or stretched), clipped to the mask.
function paintMaskWithImage(layer, mask, bbox, img, mode, scale) {
  const c = document.createElement('canvas');
  c.width = bbox.w; c.height = bbox.h;
  const cx = c.getContext('2d', { willReadFrequently: true });
  if (mode === 'stretch') {
    cx.drawImage(img, 0, 0, bbox.w, bbox.h);
  } else {
    // tile: build a scaled tile, repeat across the bbox
    const s = scale || 1;
    const tw = Math.max(1, Math.round((img.naturalWidth || img.width) * s));
    const th = Math.max(1, Math.round((img.naturalHeight || img.height) * s));
    let tile = img;
    if (tw !== (img.naturalWidth || img.width) || th !== (img.naturalHeight || img.height)) {
      const tc = document.createElement('canvas'); tc.width = tw; tc.height = th;
      tc.getContext('2d').drawImage(img, 0, 0, tw, th);
      tile = tc;
    }
    const pat = cx.createPattern(tile, 'repeat');
    cx.fillStyle = pat;
    cx.fillRect(0, 0, bbox.w, bbox.h);
  }
  // clip to the mask (zero alpha outside the selected pixels)
  const id = cx.getImageData(0, 0, bbox.w, bbox.h);
  const d = id.data, W = DOC_W_PX;
  for (let y = 0; y < bbox.h; y++) {
    for (let x = 0; x < bbox.w; x++) {
      if (!mask[(bbox.y + y) * W + (bbox.x + x)]) d[(y * bbox.w + x) * 4 + 3] = 0;
    }
  }
  cx.putImageData(id, 0, 0);
  layer.ctx.save();
  layer.ctx.globalAlpha = state.alpha;
  layer.ctx.drawImage(c, bbox.x, bbox.y);
  layer.ctx.restore();
}

function currentFillTexture() {
  if (state.fillTexIndex == null) return null;
  const t = state.fillTextures[state.fillTexIndex];
  return (t && t.img && t.img.complete) ? t.img : null;
}

// Apply the current fill source (colour or image) to a mask on a layer.
function applyFill(layer, mask) {
  if (state.fillStyle === 'image' && currentFillTexture()) {
    const bbox = computeMaskBBox(mask);
    if (bbox) paintMaskWithImage(layer, mask, bbox, currentFillTexture(), state.fillTexMode, state.fillTexScale);
  } else {
    paintMaskColor(layer.ctx, mask, state.color, Math.round(state.alpha * 255));
  }
}

// Bucket fill: detect region on the sample source, paint with the current source.
function floodFill(ctx, startX, startY, fillHex, tolerance, sampleAll, expand) {
  const sample = sampleData(sampleAll);
  let mask = computeFillMask(sample, startX, startY, tolerance);
  if (expand) mask = expandMask(mask, expand);
  paintMaskColor(ctx, mask, fillHex, Math.round(state.alpha * 255));
}

document.getElementById('fill-tolerance').addEventListener('input', e => {
  document.getElementById('fill-tol-v').textContent = e.target.value;
});
document.getElementById('fill-expand').addEventListener('input', e => {
  document.getElementById('fill-expand-v').textContent = e.target.value;
});

/* ---- Fill texture picker (image/texture fill source) ---- */
const fileInputFillTex = document.createElement('input');
fileInputFillTex.type = 'file';
fileInputFillTex.accept = 'image/png,image/jpeg,image/webp,image/svg+xml';
fileInputFillTex.multiple = true;
fileInputFillTex.style.display = 'none';
document.body.appendChild(fileInputFillTex);
fileInputFillTex.addEventListener('change', e => { Array.from(e.target.files).forEach(addFillTexture); e.target.value = ''; });

function addFillTexture(file) {
  const reader = new FileReader();
  reader.onload = ev => {
    const img = new Image();
    img.onload = () => {
      const name = file.name.replace(/\.[^.]+$/, '') || 'Texture';
      state.fillTextures.push({ name, dataUrl: ev.target.result, img });
      state.fillTexIndex = state.fillTextures.length - 1;
      state.fillStyle = 'image';
      syncFillStyleUI();
      renderTexStrip();
      persistFillTextures();
      showHint('Texture added: ' + name);
    };
    img.src = ev.target.result;
  };
  reader.readAsDataURL(file);
}

function renderTexStrip() {
  const strip = document.getElementById('fill-tex-strip');
  if (!strip) return;
  strip.innerHTML = '';
  state.fillTextures.forEach((t, i) => {
    const d = document.createElement('div');
    d.className = 'tex-thumb' + (i === state.fillTexIndex ? ' active' : '');
    d.style.backgroundImage = `url(${t.dataUrl})`;
    d.title = t.name;
    d.addEventListener('click', () => { state.fillTexIndex = i; renderTexStrip(); });
    const del = document.createElement('button');
    del.className = 'del'; del.textContent = '×';
    del.addEventListener('click', ev => {
      ev.stopPropagation();
      state.fillTextures.splice(i, 1);
      if (state.fillTexIndex === i) state.fillTexIndex = null;
      else if (state.fillTexIndex > i) state.fillTexIndex--;
      renderTexStrip(); persistFillTextures();
    });
    d.appendChild(del);
    strip.appendChild(d);
  });
}

function syncFillStyleUI() {
  document.querySelectorAll('[data-fillstyle]').forEach(b => b.classList.toggle('active', b.dataset.fillstyle === state.fillStyle));
  const opts = document.getElementById('fill-image-opts');
  if (opts) opts.style.display = state.fillStyle === 'image' ? 'block' : 'none';
}

document.querySelectorAll('[data-fillstyle]').forEach(b => b.addEventListener('click', () => { state.fillStyle = b.dataset.fillstyle; syncFillStyleUI(); }));
document.querySelectorAll('[data-texmode]').forEach(b => b.addEventListener('click', () => {
  state.fillTexMode = b.dataset.texmode;
  document.querySelectorAll('[data-texmode]').forEach(x => x.classList.toggle('active', x === b));
  document.getElementById('fill-tex-scale-row').style.display = state.fillTexMode === 'tile' ? 'flex' : 'none';
}));
document.getElementById('fill-tex-scale').addEventListener('input', e => {
  state.fillTexScale = parseFloat(e.target.value);
  document.getElementById('fill-tex-scale-v').textContent = state.fillTexScale.toFixed(1) + '×';
});
document.getElementById('fill-tex-import').addEventListener('click', () => fileInputFillTex.click());

function persistFillTextures() {
  try { localStorage.setItem('nm-fill-textures', JSON.stringify(state.fillTextures.map(t => ({ name: t.name, dataUrl: t.dataUrl })))); } catch (e) {}
}
function loadFillTextures() {
  try {
    const raw = localStorage.getItem('nm-fill-textures'); if (!raw) return;
    JSON.parse(raw).forEach(rec => { const img = new Image(); img.onload = () => { state.fillTextures.push({ name: rec.name, dataUrl: rec.dataUrl, img }); renderTexStrip(); }; img.src = rec.dataUrl; });
  } catch (e) {}
}

/* =================== SELECTION (magic wand) =================== */
const selOverlay = document.createElement('canvas');
selOverlay.id = 'sel-overlay';
selOverlay.width = DOC_W_PX; selOverlay.height = DOC_H_PX;
paper.appendChild(selOverlay);
const selCtx = selOverlay.getContext('2d');
const selBar = document.getElementById('sel-bar');

state.selection = null;   // { mask:Uint8Array, bbox:{x,y,w,h} }
state.clipboard = null;   // { canvas, w, h }
state.floating  = null;   // { canvas, x, y, w, h }
let _selPendingBefore = null;   // full ImageData captured before a move-lift (for 1-step undo)

function computeMaskBBox(mask) {
  const w = DOC_W_PX, h = DOC_H_PX;
  let minX = w, minY = h, maxX = -1, maxY = -1;
  for (let y = 0; y < h; y++) {
    const row = y * w;
    for (let x = 0; x < w; x++) {
      if (mask[row + x]) { if (x < minX) minX = x; if (x > maxX) maxX = x; if (y < minY) minY = y; if (y > maxY) maxY = y; }
    }
  }
  if (maxX < 0) return null;
  return { x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 };
}

// Area (matched-pixel count) and centroid of a mask, scanned within its bbox.
function maskAreaCentroid(mask, bbox) {
  const W = DOC_W_PX; let count = 0, sx = 0, sy = 0;
  for (let y = bbox.y; y < bbox.y + bbox.h; y++) {
    const row = y * W;
    for (let x = bbox.x; x < bbox.x + bbox.w; x++) {
      if (mask[row + x]) { count++; sx += x; sy += y; }
    }
  }
  return { count, cx: count ? sx / count : bbox.x + bbox.w / 2, cy: count ? sy / count : bbox.y + bbox.h / 2 };
}

// Magic wand: sample the ACTIVE layer (image + strokes), grab the contiguous region.
function magicWandSelect(p, tolerance) {
  commitFloating();
  const l = activeLayer();
  if (!_sampleCanvas) { _sampleCanvas = document.createElement('canvas'); _sampleCtx = _sampleCanvas.getContext('2d', { willReadFrequently: true }); }
  if (_sampleCanvas.width !== DOC_W_PX || _sampleCanvas.height !== DOC_H_PX) { _sampleCanvas.width = DOC_W_PX; _sampleCanvas.height = DOC_H_PX; }
  _sampleCtx.clearRect(0, 0, DOC_W_PX, DOC_H_PX);
  if (l.imageCanvas && !l.imageBaked) _sampleCtx.drawImage(l.imageCanvas, 0, 0);
  _sampleCtx.drawImage(l.canvas, 0, 0);
  const sample = _sampleCtx.getImageData(0, 0, DOC_W_PX, DOC_H_PX).data;
  const mask = computeFillMask(sample, p.x, p.y, tolerance);
  const bbox = computeMaskBBox(mask);
  if (!bbox) { clearSelection(); showHint('Nothing to select there'); return; }
  const ac = maskAreaCentroid(mask, bbox);
  const areaStr = formatArea(ac.count);
  state.selection = { mask, bbox, area: areaStr, centroid: { x: ac.cx, y: ac.cy } };
  drawSelectionOverlay();
  showSelBar();
  showHint('Selected · ' + areaStr + ' · Copy / Cut / Delete / Fill · drag to move · Done');
}

// Rasterize a freehand polygon (doc-coord points) into a selection mask.
function lassoToMask(points) {
  if (!_sampleCanvas) { _sampleCanvas = document.createElement('canvas'); _sampleCtx = _sampleCanvas.getContext('2d', { willReadFrequently: true }); }
  if (_sampleCanvas.width !== DOC_W_PX || _sampleCanvas.height !== DOC_H_PX) { _sampleCanvas.width = DOC_W_PX; _sampleCanvas.height = DOC_H_PX; }
  const cx = _sampleCtx;
  cx.setTransform(1, 0, 0, 1, 0, 0);
  cx.clearRect(0, 0, DOC_W_PX, DOC_H_PX);
  cx.fillStyle = '#fff';
  cx.beginPath();
  cx.moveTo(points[0].x, points[0].y);
  for (let i = 1; i < points.length; i++) cx.lineTo(points[i].x, points[i].y);
  cx.closePath();
  cx.fill();
  const d = cx.getImageData(0, 0, DOC_W_PX, DOC_H_PX).data;
  const mask = new Uint8Array(DOC_W_PX * DOC_H_PX);
  for (let i = 0; i < mask.length; i++) if (d[i * 4 + 3] > 128) mask[i] = 1;
  return mask;
}

function drawLassoPath() {
  selCtx.setTransform(1, 0, 0, 1, 0, 0);
  selCtx.clearRect(0, 0, DOC_W_PX, DOC_H_PX);
  selOverlay.style.display = 'block';
  selOverlay.style.zIndex = (state.layers.length * 2 + 6).toString();
  selOverlay.classList.remove('pulse');
  const pts = state.lassoPoints;
  if (!pts || pts.length < 2) return;
  selCtx.strokeStyle = 'rgba(160,40,53,0.95)';
  selCtx.lineWidth = 2.5; selCtx.lineJoin = 'round'; selCtx.setLineDash([9, 6]);
  selCtx.beginPath();
  selCtx.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < pts.length; i++) selCtx.lineTo(pts[i].x, pts[i].y);
  selCtx.stroke();
  selCtx.setLineDash([]);
}

function finishLasso() {
  const pts = state.lassoPoints || [];
  state.lassoPoints = null;
  if (pts.length < 3) { selOverlay.style.display = 'none'; return; }
  const mask = lassoToMask(pts);
  const bbox = computeMaskBBox(mask);
  if (!bbox) { selOverlay.style.display = 'none'; return; }
  const areaStr = formatArea(shoelaceArea(pts));
  let sx = 0, sy = 0; pts.forEach(p => { sx += p.x; sy += p.y; });
  state.selection = { mask, bbox, area: areaStr, centroid: { x: sx / pts.length, y: sy / pts.length } };
  state.floating = null;
  drawSelectionOverlay();
  showSelBar();
  showHint('Lasso area: ' + areaStr + ' · Copy / Cut / Delete / Fill · Done');
}

function drawSelectionOverlay() {
  selCtx.setTransform(1, 0, 0, 1, 0, 0);
  selCtx.clearRect(0, 0, DOC_W_PX, DOC_H_PX);
  selOverlay.style.zIndex = (state.layers.length * 2 + 6).toString();
  if (state.floating) {
    selOverlay.style.display = 'block';
    selOverlay.classList.remove('pulse');
    selCtx.drawImage(state.floating.canvas, state.floating.x, state.floating.y);
    selCtx.strokeStyle = 'rgba(160,40,53,0.95)';
    selCtx.lineWidth = 2.5; selCtx.setLineDash([11, 7]);
    selCtx.strokeRect(state.floating.x, state.floating.y, state.floating.w, state.floating.h);
    selCtx.setLineDash([]);
    return;
  }
  if (!state.selection) { selOverlay.style.display = 'none'; selOverlay.classList.remove('pulse'); return; }
  selOverlay.style.display = 'block';
  const { mask, bbox } = state.selection;
  const W = DOC_W_PX, H = DOC_H_PX;
  const img = selCtx.createImageData(bbox.w, bbox.h);
  const d = img.data;
  for (let y = 0; y < bbox.h; y++) {
    const gy = bbox.y + y;
    for (let x = 0; x < bbox.w; x++) {
      const gx = bbox.x + x;
      const gi = gy * W + gx;
      if (!mask[gi]) continue;
      const edge = gx === 0 || gx === W-1 || gy === 0 || gy === H-1 ||
                   !mask[gi-1] || !mask[gi+1] || !mask[gi-W] || !mask[gi+W];
      const o = (y * bbox.w + x) * 4;
      d[o] = 160; d[o+1] = 40; d[o+2] = 53;
      d[o+3] = edge ? 240 : 48;
    }
  }
  selCtx.putImageData(img, bbox.x, bbox.y);
  selOverlay.classList.add('pulse');

  // Lasso area label at the centroid
  if (state.selection.area && state.selection.centroid) {
    const c = state.selection.centroid;
    selCtx.font = '700 30px ui-monospace, monospace';
    selCtx.textAlign = 'center';
    selCtx.textBaseline = 'middle';
    const txt = state.selection.area;
    const tw = selCtx.measureText(txt).width;
    const bw = tw + 28, bh = 46;
    selCtx.fillStyle = 'rgba(20,20,22,0.9)';
    const rx = c.x - bw/2, ry = c.y - bh/2, r = 10;
    selCtx.beginPath();
    selCtx.moveTo(rx + r, ry);
    selCtx.arcTo(rx + bw, ry, rx + bw, ry + bh, r);
    selCtx.arcTo(rx + bw, ry + bh, rx, ry + bh, r);
    selCtx.arcTo(rx, ry + bh, rx, ry, r);
    selCtx.arcTo(rx, ry, rx + bw, ry, r);
    selCtx.closePath();
    selCtx.fill();
    selCtx.fillStyle = '#fff';
    selCtx.fillText(txt, c.x, c.y);
  }
}

function clearSelection() {
  state.selection = null;
  selOverlay.style.display = 'none';
  selOverlay.classList.remove('pulse');
  selBar.classList.remove('show');
}

function showSelBar() {
  selBar.classList.add('show');
  document.getElementById('sel-paste').disabled = !state.clipboard;
}

function ensureBaked(l) {
  if (l.imageCanvas && !l.imageBaked && l.image) bakeImageLayer(l);
}

// Active-layer pixels within the mask → a bbox-sized canvas.
function maskedToCanvas(l, mask, bbox) {
  const c = document.createElement('canvas'); c.width = bbox.w; c.height = bbox.h;
  const region = l.ctx.getImageData(bbox.x, bbox.y, bbox.w, bbox.h);
  const rd = region.data, W = DOC_W_PX;
  for (let y = 0; y < bbox.h; y++) {
    for (let x = 0; x < bbox.w; x++) {
      if (!mask[(bbox.y + y) * W + (bbox.x + x)]) region.data[(y * bbox.w + x) * 4 + 3] = 0;
    }
  }
  c.getContext('2d').putImageData(region, 0, 0);
  return c;
}

function clearMaskPixels(l, mask, bbox) {
  const region = l.ctx.getImageData(bbox.x, bbox.y, bbox.w, bbox.h);
  const d = region.data, W = DOC_W_PX;
  for (let y = 0; y < bbox.h; y++) {
    for (let x = 0; x < bbox.w; x++) {
      if (mask[(bbox.y + y) * W + (bbox.x + x)]) {
        const o = (y * bbox.w + x) * 4; d[o] = d[o+1] = d[o+2] = d[o+3] = 0;
      }
    }
  }
  l.ctx.putImageData(region, bbox.x, bbox.y);
}

function selCopy() {
  if (!state.selection) return;
  const l = activeLayer(); ensureBaked(l);
  const { mask, bbox } = state.selection;
  state.clipboard = { canvas: maskedToCanvas(l, mask, bbox), w: bbox.w, h: bbox.h };
  document.getElementById('sel-paste').disabled = false;
  showHint('Copied');
}

function selDelete() {
  if (!state.selection) return;
  const l = activeLayer(); ensureBaked(l);
  const { mask, bbox } = state.selection;
  clearMaskPixels(l, mask, bbox);
  saveSnapshot(l); renderLayers();
  clearSelection();
  showHint('Deleted');
}

function selCut() {
  if (!state.selection) return;
  const l = activeLayer(); ensureBaked(l);
  const { mask, bbox } = state.selection;
  state.clipboard = { canvas: maskedToCanvas(l, mask, bbox), w: bbox.w, h: bbox.h };
  clearMaskPixels(l, mask, bbox);
  saveSnapshot(l); renderLayers();
  clearSelection();
  showHint('Cut');
}

function selPaste() {
  if (!state.clipboard) return;
  commitFloating();
  const cb = state.clipboard;
  const c = document.createElement('canvas'); c.width = cb.w; c.height = cb.h;
  c.getContext('2d').drawImage(cb.canvas, 0, 0);
  state.floating = { canvas: c, x: Math.round((DOC_W_PX - cb.w) / 2), y: Math.round((DOC_H_PX - cb.h) / 2), w: cb.w, h: cb.h };
  state.selection = null;
  _selPendingBefore = null;   // paste adds pixels; commit will saveSnapshot
  drawSelectionOverlay();
  showSelBar();
  showHint('Drag to position · Done to place');
}

function selDuplicate() {
  if (!state.selection) return;
  selCopy();
  selPaste();
}

// Fill the current selection with the active fill source (colour or image texture).
function selFill() {
  if (!state.selection) return;
  const l = activeLayer(); ensureBaked(l);
  applyFill(l, state.selection.mask);
  saveSnapshot(l);
  renderLayers();
  drawSelectionOverlay();   // selection stays so you can try other textures
  showHint(state.fillStyle === 'image' && currentFillTexture() ? 'Filled with texture' : 'Filled');
}

// Lift the current selection into a floating layer for moving.
function floatSelection() {
  if (!state.selection) return;
  const l = activeLayer(); ensureBaked(l);
  const { mask, bbox } = state.selection;
  _selPendingBefore = l._cur
    ? new ImageData(new Uint8ClampedArray(l._cur.data), l._cur.width, l._cur.height)
    : l.ctx.getImageData(0, 0, DOC_W_PX, DOC_H_PX);
  const c = maskedToCanvas(l, mask, bbox);
  clearMaskPixels(l, mask, bbox);   // lift (snapshot deferred to commit for a single undo step)
  state.floating = { canvas: c, x: bbox.x, y: bbox.y, w: bbox.w, h: bbox.h };
  state.selection = null;
  renderLayers();
  drawSelectionOverlay();
}

function commitFloating() {
  if (!state.floating) return;
  const l = activeLayer();
  l.ctx.drawImage(state.floating.canvas, state.floating.x, state.floating.y);
  if (_selPendingBefore) {
    // single undo step spanning lift + move
    const after = l.ctx.getImageData(0, 0, DOC_W_PX, DOC_H_PX);
    l.history.push({ x: 0, y: 0, before: _selPendingBefore, after });
    l.redo = []; l._cur = after; _capHistory(l); l._dirty = true; scheduleAutosave();
    _selPendingBefore = null;
  } else {
    saveSnapshot(l);   // paste
  }
  state.floating = null;
  renderLayers();
  drawSelectionOverlay();
}

function insideFloating(p) {
  const f = state.floating; if (!f) return false;
  return p.x >= f.x && p.x <= f.x + f.w && p.y >= f.y && p.y <= f.y + f.h;
}
function maskAt(p) {
  const s = state.selection; if (!s) return false;
  const x = Math.round(p.x), y = Math.round(p.y);
  if (x < 0 || y < 0 || x >= DOC_W_PX || y >= DOC_H_PX) return false;
  return !!s.mask[y * DOC_W_PX + x];
}

function startFloatDrag(e, p0) {
  paper.setPointerCapture && paper.setPointerCapture(e.pointerId);
  const f = state.floating; const sx = f.x, sy = f.y;
  let raf = false, last = p0;
  const mv = (ev) => {
    last = clientToCanvas(ev.clientX, ev.clientY);
    if (raf) return; raf = true;
    requestAnimationFrame(() => { raf = false; if (!state.floating) return;
      state.floating.x = Math.round(sx + (last.x - p0.x));
      state.floating.y = Math.round(sy + (last.y - p0.y));
      drawSelectionOverlay();
    });
  };
  const up = () => { document.removeEventListener('pointermove', mv); document.removeEventListener('pointerup', up); document.removeEventListener('pointercancel', up); };
  document.addEventListener('pointermove', mv);
  document.addEventListener('pointerup', up);
  document.addEventListener('pointercancel', up);
}

selBar.querySelectorAll('button').forEach(b => b.addEventListener('click', (e) => {
  e.stopPropagation();
  const a = b.dataset.act;
  if (a === 'copy') selCopy();
  else if (a === 'cut') selCut();
  else if (a === 'fill') selFill();
  else if (a === 'delete') selDelete();
  else if (a === 'duplicate') selDuplicate();
  else if (a === 'extrude') extrudeSelection();
  else if (a === 'paste') selPaste();
  else if (a === 'move') { if (state.selection) { floatSelection(); showHint('Drag to move · Done to place'); } }
  else if (a === 'deselect') { commitFloating(); clearSelection(); }
}));

