function updatePreview() {
  const svg = document.getElementById('puck-preview-svg');
  svg.innerHTML = '';
  const svgns = 'http://www.w3.org/2000/svg';
  const path = document.createElementNS(svgns, 'path');
  let d = 'M 2 10';
  for (let i = 0; i < 6; i++) {
    const x = 2 + i * 5;
    const y = 10 + Math.sin(i * 0.9) * 4;
    d += ` L ${x} ${y}`;
  }
  path.setAttribute('d', d);
  path.setAttribute('stroke', state.color);
  path.setAttribute('stroke-width', Math.max(1, Math.min(8, state.size * 0.4)));
  path.setAttribute('stroke-linecap', 'round');
  path.setAttribute('fill', 'none');
  path.setAttribute('opacity', state.alpha);
  svg.appendChild(path);
}

