// --- Pencil-only mode: reject finger/palm on the drawing surfaces *while the pen is down*
// (that's when a palm yanks the stroke). When no pen is touching, finger gestures —
// 2-finger undo, 3-finger redo, pinch pan/zoom — pass through untouched. ---
let stylusOnly = localStorage.getItem('nm-stylus-only') === '1';
let _penDown = 0;
document.addEventListener('pointerdown', e => { if (e.pointerType === 'pen') _penDown++; }, true);
document.addEventListener('pointerup',   e => { if (e.pointerType === 'pen') _penDown = Math.max(0, _penDown - 1); }, true);
document.addEventListener('pointercancel', e => { if (e.pointerType === 'pen') _penDown = Math.max(0, _penDown - 1); }, true);
function updateStylusBtn() { const b = document.getElementById('btn-stylus'); if (b) b.classList.toggle('active', stylusOnly); }
function _stylusGuard(e) {
  if (!stylusOnly || e.pointerType !== 'touch' || _penDown === 0) return;   // no pen down → let finger gestures through
  const t = e.target;
  if (t && t.closest && t.closest('#paper, #massing-canvas, #fe-canvas')) { e.stopPropagation(); e.preventDefault(); }
}
['pointerdown', 'pointermove', 'pointerup'].forEach(ev => document.addEventListener(ev, _stylusGuard, true));
document.getElementById('btn-stylus').addEventListener('click', () => {
  stylusOnly = !stylusOnly;
  localStorage.setItem('nm-stylus-only', stylusOnly ? '1' : '0');
  updateStylusBtn();
  showHint(stylusOnly ? 'Pencil-only ON — palm ignored while drawing · 2-finger undo still works' : 'Pencil-only OFF — touch enabled');
});
updateStylusBtn();
