/* =================================================================
   DOCUMENT GRID — canvas-rendered, supports architectural styles
   ================================================================= */
const gridCanvas = document.getElementById('grid-canvas');
const gridCtx = gridCanvas.getContext('2d');

// Grid cell size: millimetres on the sheet → document pixels.
// Predictable regardless of drawing scale (a 20mm grid is 20mm on paper).
function mmToDocPx(mm) {
  return mm / 25.4 * DOC_DPI;
}

function drawDocGrid() {
  gridCanvas.width = DOC_W_PX;
  gridCanvas.height = DOC_H_PX;
  const show = state.showGrid && state.gridType !== 'off';
  gridCanvas.style.display = show ? 'block' : 'none';
  if (!show) return;

  const ctx = gridCtx;
  ctx.clearRect(0, 0, DOC_W_PX, DOC_H_PX);
  const op = state.gridOpacity;
  let spacing = Math.max(8, mmToDocPx(state.gridSpacingMM));
  // Line widths scaled to document resolution (so they survive the display downscale)
  const minorW = Math.max(1.5, DOC_W_PX / 1400);
  const majorW = minorW * 2.2;
  const minorColor = `rgba(40,70,140,${op * 0.5})`;
  const majorColor = `rgba(40,70,140,${op})`;

  if (state.gridType === 'square') {
    ctx.strokeStyle = majorColor;
    ctx.lineWidth = minorW;
    for (let x = 0; x <= DOC_W_PX; x += spacing) line(ctx, x, 0, x, DOC_H_PX);
    for (let y = 0; y <= DOC_H_PX; y += spacing) line(ctx, 0, y, DOC_W_PX, y);
  } else if (state.gridType === 'arch') {
    // Minor lines, with every Nth line major (heavier) — classic drafting grid
    const major = state.gridMajor;
    let i = 0;
    for (let x = 0; x <= DOC_W_PX; x += spacing, i++) {
      ctx.strokeStyle = (i % major === 0) ? majorColor : minorColor;
      ctx.lineWidth = (i % major === 0) ? majorW : minorW;
      line(ctx, x, 0, x, DOC_H_PX);
    }
    i = 0;
    for (let y = 0; y <= DOC_H_PX; y += spacing, i++) {
      ctx.strokeStyle = (i % major === 0) ? majorColor : minorColor;
      ctx.lineWidth = (i % major === 0) ? majorW : minorW;
      line(ctx, 0, y, DOC_W_PX, y);
    }
  } else if (state.gridType === 'dot') {
    ctx.fillStyle = majorColor;
    const r = Math.max(1.2, minorW);
    for (let x = spacing / 2; x < DOC_W_PX; x += spacing) {
      for (let y = spacing / 2; y < DOC_H_PX; y += spacing) {
        ctx.beginPath();
        ctx.arc(x, y, r, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  } else if (state.gridType === 'column') {
    // Structural column grid: heavy lines at MAJOR spacing only, with
    // bubble labels A,B,C across the top and 1,2,3 down the left.
    const colSpacing = spacing * state.gridMajor;
    ctx.strokeStyle = majorColor;
    ctx.lineWidth = majorW;
    ctx.setLineDash([majorW * 3, majorW * 2]);
    const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    let ci = 0;
    for (let x = colSpacing; x < DOC_W_PX; x += colSpacing, ci++) {
      line(ctx, x, 0, x, DOC_H_PX);
      gridBubble(ctx, x, colSpacing * 0.35, letters[ci % 26], majorColor);
    }
    let ri = 0;
    for (let y = colSpacing; y < DOC_H_PX; y += colSpacing, ri++) {
      line(ctx, 0, y, DOC_W_PX, y);
      gridBubble(ctx, colSpacing * 0.35, y, String(ri + 1), majorColor);
    }
    ctx.setLineDash([]);
  }
}

function line(ctx, x1, y1, x2, y2) {
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
}
function gridBubble(ctx, cx, cy, label, color) {
  const r = Math.max(28, DOC_W_PX / 70);
  ctx.save();
  ctx.setLineDash([]);
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(255,255,255,0.92)';
  ctx.fill();
  ctx.strokeStyle = color;
  ctx.lineWidth = Math.max(2, DOC_W_PX / 900);
  ctx.stroke();
  ctx.fillStyle = color;
  ctx.font = `700 ${r * 1.1}px Archivo, sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(label, cx, cy);
  ctx.restore();
}

