document.getElementById('btn-export').addEventListener('click', async () => {
  const out = document.createElement('canvas');
  out.width = DOC_W_PX; out.height = DOC_H_PX;
  const octx = out.getContext('2d');
  octx.fillStyle = '#ffffff';
  octx.fillRect(0, 0, DOC_W_PX, DOC_H_PX);
  state.layers.forEach(l => {
    if (!l.visible) return;
    if (l.imageCanvas && !l.imageBaked) {
      octx.globalAlpha = l.opacity;
      octx.drawImage(l.imageCanvas, 0, 0);
    }
    octx.globalAlpha = l.opacity;
    octx.drawImage(l.canvas, 0, 0);
  });
  octx.globalAlpha = 1;

  // SketchTrude wordmark + date/time stamp — bottom left
  try {
    const margin = Math.round(DOC_W_PX * 0.018);
    const fs = Math.max(11, Math.round(DOC_W_PX * 0.0072));
    const now = new Date();
    const pad = n => String(n).padStart(2, '0');
    const dateStr = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
    const timeStr = `${pad(now.getHours())}:${pad(now.getMinutes())}`;
    const stampText = ['SketchTrude', dateStr, timeStr].join('    ·    ');

    octx.save();
    octx.font = `600 ${fs}px 'JetBrains Mono', ui-monospace, monospace`;
    octx.textAlign = 'left';
    octx.textBaseline = 'alphabetic';
    octx.fillStyle = 'rgba(10,10,10,0.62)';
    octx.fillText(stampText, margin, DOC_H_PX - margin);
    octx.restore();
  } catch(e) { /* continue without stamp */ }

  out.toBlob((blob) => {
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `SketchTrude-${new Date().toISOString().slice(0,10)}.png`;
    a.click();
  }, 'image/png');
  showHint('Exported · SketchTrude · date');
});

/* =================== ZOOM CONTROLS =================== */
function updateZoomDisplay() {
  const el = document.getElementById('zoom-level');
  if (!el) return;
  if (typeof massing !== 'undefined' && massing.active) {
    el.textContent = Math.round(massing.cam.scale) + '%';
  } else {
    el.textContent = Math.round(state.zoom * 100) + '%';
  }
}

function handleZoomIn() {
  if (massing.active) {
    massing.cam.scale = Math.max(6, Math.min(160, massing.cam.scale * 1.08));
    renderMassing();
    updateZoomDisplay();
    return;
  }
  state.zoom = (window.StudioHelpers ? StudioHelpers.zoomIn(state.zoom) : Math.min(8, state.zoom * 1.25));
  applyStageTransform();
}

function handleZoomOut() {
  if (massing.active) {
    massing.cam.scale = Math.max(6, Math.min(160, massing.cam.scale / 1.08));
    renderMassing();
    updateZoomDisplay();
    return;
  }
  state.zoom = (window.StudioHelpers ? StudioHelpers.zoomOut(state.zoom) : Math.max(0.2, state.zoom / 1.25));
  applyStageTransform();
}

function handleZoomFit() {
  if (massing.active) {
    massing.panX = 0;
    massing.panY = 0;
    const r = area.getBoundingClientRect();
    massing.cam.scale = Math.min(r.width, r.height) / 26;
    renderMassing();
    updateZoomDisplay();
    return;
  }
  fitToScreen();
}

document.getElementById('zoom-in').addEventListener('click', handleZoomIn);
document.getElementById('zoom-out').addEventListener('click', handleZoomOut);
document.getElementById('zoom-fit').addEventListener('click', handleZoomFit);

