let hintTimer;
function showHint(msg) {
  hintEl.textContent = msg;
  hintEl.classList.add('show');
  clearTimeout(hintTimer);
  hintTimer = setTimeout(() => hintEl.classList.remove('show'), 3000);
}

/* =================================================================
   ERROR BOUNDARY — one thrown error must never leave the canvas
   stuck mid-stroke. Catch, recover transient state, keep drawing alive.
   ================================================================= */
let _lastErrToast = 0;
function recoverFromError(where, err) {
  console.error('[SketchTrude] recovered from error in', where, err);
  try {
    // Reset anything that could wedge the draw loop
    state.drawing = false;
    if (state.usingBuffer) {
      state.usingBuffer = false;
      if (typeof strokeCtx !== 'undefined') { strokeCtx.setTransform(1,0,0,1,0,0); strokeCtx.clearRect(0, 0, strokeCanvas.width, strokeCanvas.height); }
      if (typeof strokeCanvas !== 'undefined') { strokeCanvas.style.opacity = '0'; strokeCanvas.style.mixBlendMode = 'normal'; }
    }
    if (typeof massing !== 'undefined') massing.dragging = null;
    document.body.classList.remove('nm-drawing');
  } catch (_) { /* never throw from the handler */ }
  // Throttle the toast so a repeating error doesn't spam
  if (Date.now() - _lastErrToast > 4000) {
    _lastErrToast = Date.now();
    showHint('Something hiccuped — your work is safe. Carry on.');
  }
}
window.addEventListener('error', (e) => recoverFromError('window.error', e.error || e.message));
window.addEventListener('unhandledrejection', (e) => recoverFromError('promise', e.reason));

function updateUI() {
  const l = activeLayer();
  document.getElementById('layer-opacity').value = Math.round(l.opacity * 100);
  document.getElementById('layer-opacity-val').textContent = Math.round(l.opacity * 100) + '%';
  document.getElementById('layer-trace').value = Math.round(l.trace * 100);
  document.getElementById('layer-trace-val').textContent = Math.round(l.trace * 100) + '%';
  refreshImageOverlay();
  refreshImageProps();
}

/* =================== IMAGE LAYER: PROPERTIES PANEL =================== */
const imageProps = document.getElementById('image-props');

function refreshImageProps() {
  const l = activeLayer();
  const hasUnbaked = l && l.image && !l.imageBaked;
  imageProps.style.display = hasUnbaked ? 'block' : 'none';
  if (!hasUnbaked) return;
  const t = l.imageTransform;
  document.getElementById('img-x').value = Math.round(pxToMm(t.x));
  document.getElementById('img-y').value = Math.round(pxToMm(t.y));
  document.getElementById('img-w').value = Math.round(pxToMm(t.w));
  document.getElementById('img-h').value = Math.round(pxToMm(t.h));
  document.getElementById('img-rot').value = Math.round(t.rotation);
  document.getElementById('img-opacity').value = Math.round(l.imageOpacity * 100);
  document.getElementById('img-crop-toggle').classList.toggle('active', state.cropMode);
}

function pxToMm(px) { return px / DOC_W_PX * DOC_W_MM; }
function mmToPx(mm) { return mm / DOC_W_MM * DOC_W_PX; }

// Property input bindings
function bindImageInput(id, fn) {
  const el = document.getElementById(id);
  el.addEventListener('change', () => {
    const l = activeLayer();
    if (!l.image || l.imageBaked) return;
    fn(l, parseFloat(el.value));
    renderImageCanvas(l);
    refreshImageOverlay();
    renderLayers();
  });
}
bindImageInput('img-x', (l, v) => l.imageTransform.x = mmToPx(v));
bindImageInput('img-y', (l, v) => l.imageTransform.y = mmToPx(v));
bindImageInput('img-w', (l, v) => l.imageTransform.w = Math.max(10, mmToPx(v)));
bindImageInput('img-h', (l, v) => l.imageTransform.h = Math.max(10, mmToPx(v)));
bindImageInput('img-rot', (l, v) => l.imageTransform.rotation = v);
bindImageInput('img-opacity', (l, v) => l.imageOpacity = Math.max(0, Math.min(100, v)) / 100);

document.getElementById('img-reset').addEventListener('click', () => {
  const l = activeLayer();
  if (!l.image || l.imageBaked) return;
  const aspect = l.image.naturalWidth / l.image.naturalHeight;
  let w, h;
  if (DOC_W_PX / DOC_H_PX > aspect) {
    h = DOC_H_PX * 0.9; w = h * aspect;
  } else {
    w = DOC_W_PX * 0.9; h = w / aspect;
  }
  l.imageTransform = { x: DOC_W_PX/2, y: DOC_H_PX/2, w, h, rotation: 0 };
  l.imageOpacity = 1;
  l.imageCrop = null;
  renderImageCanvas(l);
  refreshImageOverlay();
  refreshImageProps();
});

document.getElementById('img-apply').addEventListener('click', () => {
  const l = activeLayer();
  if (!l.image || l.imageBaked) return;
  bakeImageLayer(l);
  showHint('Image flattened · paint and erase work normally now');
});

document.getElementById('img-replace').addEventListener('click', () => {
  state.replaceImageInLayer = activeLayer();
  fileInputImportImage.click();
});

document.getElementById('img-scale-ref').addEventListener('click', () => {
  const l = activeLayer();
  if (!l.image || !l.imageTransform) return;
  // Use the current image width as the reference
  const wPx = l.imageTransform.w;
  // Ask the user the real-world width
  state.pendingScaleStart = { x: l.imageTransform.x - wPx/2, y: l.imageTransform.y };
  state.pendingScaleEnd = { x: l.imageTransform.x + wPx/2, y: l.imageTransform.y };
  state.pendingScale = false;
  state.measurePreview = { x1: state.pendingScaleStart.x, y1: state.pendingScaleStart.y, x2: state.pendingScaleEnd.x, y2: state.pendingScaleEnd.y };
  refreshMeasurements();
  openScaleApply();
  showHint('Enter the real-world width of this image, then Apply');
});

document.getElementById('img-crop-toggle').addEventListener('click', () => {
  state.cropMode = !state.cropMode;
  document.getElementById('img-crop-toggle').classList.toggle('active', state.cropMode);
  refreshImageOverlay();
  if (state.cropMode) showHint('Crop mode · drag corners on the image to crop');
});

// Augment importImageAsLayer for replace flow via state
// (state.replaceImageInLayer is checked inside importImageAsLayer below)

/* =================== IMAGE LAYER: TRANSFORM OVERLAY =================== */
function hideImageOverlay() {
  imgOverlay.style.display = 'none';
  imgOverlay.classList.remove('active-overlay');
  imgOverlay.innerHTML = '';
}

function refreshImageOverlay() {
  const l = activeLayer();
  if (!l || !l.image || l.imageBaked) { hideImageOverlay(); return; }
  drawImageOverlay(l);
}

function drawImageOverlay(layer) {
  const t = layer.imageTransform;
  imgOverlay.style.display = 'block';
  imgOverlay.classList.add('active-overlay');
  imgOverlay.setAttribute('viewBox', `0 0 ${DOC_W_PX} ${DOC_H_PX}`);
  imgOverlay.innerHTML = '';

  const svgns = 'http://www.w3.org/2000/svg';
  const group = document.createElementNS(svgns, 'g');
  // rotate around image center
  group.setAttribute('transform', `translate(${t.x} ${t.y}) rotate(${t.rotation})`);
  imgOverlay.appendChild(group);

  // Frame
  const frame = document.createElementNS(svgns, 'rect');
  frame.setAttribute('x', -t.w/2);
  frame.setAttribute('y', -t.h/2);
  frame.setAttribute('width', t.w);
  frame.setAttribute('height', t.h);
  frame.setAttribute('class', 'img-frame' + (state.cropMode ? ' cropping' : ''));
  group.appendChild(frame);

  // Handles size in doc px (will look scaled by zoom but acceptable)
  const handleR = Math.max(14, 30 / (state.zoom * state.baseZoom));
  const handles = [
    { x: -t.w/2, y: -t.h/2, role: 'corner-tl' },
    { x:  t.w/2, y: -t.h/2, role: 'corner-tr' },
    { x: -t.w/2, y:  t.h/2, role: 'corner-bl' },
    { x:  t.w/2, y:  t.h/2, role: 'corner-br' },
  ];
  handles.forEach(h => {
    const c = document.createElementNS(svgns, 'circle');
    c.setAttribute('cx', h.x);
    c.setAttribute('cy', h.y);
    c.setAttribute('r', handleR);
    c.setAttribute('class', 'img-handle ' + h.role);
    c.dataset.role = h.role;
    group.appendChild(c);
  });
  // Rotate handle line + circle (above the top middle, or below if no room)
  const rotateDist = Math.max(50, 100 / (state.zoom * state.baseZoom));
  // If image top is too close to top of doc, put the rotate handle below instead.
  const topInDoc = t.y - t.h/2;
  const placeBelow = topInDoc < rotateDist + handleR + 20;
  const rotateY = placeBelow ? (t.h/2 + rotateDist) : (-t.h/2 - rotateDist);
  const lineY1 = placeBelow ? t.h/2 : -t.h/2;
  const rline = document.createElementNS(svgns, 'line');
  rline.setAttribute('x1', 0);
  rline.setAttribute('y1', lineY1);
  rline.setAttribute('x2', 0);
  rline.setAttribute('y2', rotateY);
  rline.setAttribute('class', 'img-rotate-line');
  group.appendChild(rline);
  const rc = document.createElementNS(svgns, 'circle');
  rc.setAttribute('cx', 0);
  rc.setAttribute('cy', rotateY);
  rc.setAttribute('r', handleR);
  rc.setAttribute('class', 'img-handle rotate');
  rc.dataset.role = 'rotate';
  group.appendChild(rc);

  // Wire pointer events
  attachImageOverlayHandlers(layer);
}

function attachImageOverlayHandlers(layer) {
  const elements = imgOverlay.querySelectorAll('.img-frame, .img-handle');
  elements.forEach(el => {
    el.addEventListener('pointerdown', (e) => {
      e.stopPropagation();
      e.preventDefault();
      const role = el.dataset.role || 'move';
      startImageManipulation(layer, role, e);
    });
  });
}

function startImageManipulation(layer, role, e) {
  imgOverlay.setPointerCapture && imgOverlay.setPointerCapture(e.pointerId);
  const start = clientToCanvas(e.clientX, e.clientY);
  const t0 = { ...layer.imageTransform };
  layer.imageManipulating = true;   // use fast downscaled preview during the drag
  let rafPending = false, lastEv = e;

  const apply = () => {
    rafPending = false;
    const ev = lastEv;
    const p = clientToCanvas(ev.clientX, ev.clientY);
    const dx = p.x - start.x;
    const dy = p.y - start.y;
    if (role === 'move') {
      layer.imageTransform.x = t0.x + dx;
      layer.imageTransform.y = t0.y + dy;
    } else if (role === 'rotate') {
      const a = Math.atan2(p.y - t0.y, p.x - t0.x) * 180 / Math.PI + 90;
      let next = a;
      if (ev.shiftKey) next = Math.round(next / 15) * 15;
      layer.imageTransform.rotation = next;
    } else if (role.startsWith('corner')) {
      const r = -t0.rotation * Math.PI / 180;
      const lx = (p.x - t0.x) * Math.cos(r) - (p.y - t0.y) * Math.sin(r);
      const ly = (p.x - t0.x) * Math.sin(r) + (p.y - t0.y) * Math.cos(r);
      const sx = role.endsWith('tr') || role.endsWith('br') ? 1 : -1;
      const sy = role.endsWith('bl') || role.endsWith('br') ? 1 : -1;
      let newW = Math.max(10, lx * sx * 2);
      let newH = Math.max(10, ly * sy * 2);
      if (!ev.altKey) {
        const rw = newW / t0.w, rh = newH / t0.h;
        const scale = Math.max(rw, rh);
        newW = t0.w * scale;
        newH = t0.h * scale;
      }
      layer.imageTransform.w = newW;
      layer.imageTransform.h = newH;
    }
    renderImageCanvas(layer);
    drawImageOverlay(layer);
    refreshImageProps();
  };

  const onMove = (ev) => {
    lastEv = ev;
    if (rafPending) return;       // coalesce the flood of pointer events to one redraw/frame
    rafPending = true;
    requestAnimationFrame(apply);
  };
  const onUp = () => {
    document.removeEventListener('pointermove', onMove);
    document.removeEventListener('pointerup', onUp);
    document.removeEventListener('pointercancel', onUp);
    layer.imageManipulating = false;
    renderImageCanvas(layer);     // final full-resolution redraw
    drawImageOverlay(layer);
  };
  document.addEventListener('pointermove', onMove);
  document.addEventListener('pointerup', onUp);
  document.addEventListener('pointercancel', onUp);
}


/* =================================================================
   FEATURE 1 — ORTHOGONAL SNAP (Shift key)
   ================================================================= */
function snapToOrtho(x, y, anchorX, anchorY) {
  const dx = x - anchorX, dy = y - anchorY;
  const angle = Math.atan2(dy, dx);
  const snapped = Math.round(angle / (Math.PI / 4)) * (Math.PI / 4);
  const dist = Math.sqrt(dx * dx + dy * dy);
  return {
    x: anchorX + dist * Math.cos(snapped),
    y: anchorY + dist * Math.sin(snapped),
  };
}

function applyOrthoSnap(p, e) {
  if (!e.shiftKey) {
    if (state.snapActive) {
      state.snapActive = false;
      document.getElementById('snap-badge').classList.remove('show');
    }
    return p;
  }
  if (!state.snapActive) {
    state.snapActive = true;
    state.snapAnchor = { x: state.lastX, y: state.lastY };
    document.getElementById('snap-badge').classList.add('show');
  }
  return snapToOrtho(p.x, p.y, state.snapAnchor.x, state.snapAnchor.y);
}

// Add snapAnchor + snapActive to state (done inline here, no object literal edit needed)
state.snapActive = false;
state.snapAnchor = null;

/* =================================================================
   FEATURE 2 — MATERIAL HATCHING STENCILS
   ================================================================= */
// Each hatch draws a tiled patch using canvas pattern at the stamp location.
const HATCH_PATTERNS = [
  {
    name: 'Brick', category: 'hatch',
    tile: (ctx, tileW, tileH) => {
      ctx.strokeStyle = '#333'; ctx.lineWidth = 1.5;
      // row 1
      ctx.strokeRect(1, 1, tileW/2-2, tileH/2-1);
      ctx.strokeRect(tileW/2, 1, tileW/2-1, tileH/2-1);
      // row 2 (offset)
      ctx.strokeRect(1-tileW/4, tileH/2, tileW/2-2, tileH/2-1);
      ctx.strokeRect(tileW/4+1, tileH/2, tileW/2-2, tileH/2-1);
      ctx.strokeRect(tileW-tileW/4+1, tileH/2, tileW/2-2, tileH/2-1);
    }, tileW: 60, tileH: 30,
  },
  {
    name: 'Concrete', category: 'hatch',
    tile: (ctx, tileW, tileH) => {
      ctx.fillStyle = '#333';
      const pts = [[8,8],[20,15],[35,5],[45,20],[55,10],[12,22],[30,25],[48,28]];
      pts.forEach(([x,y]) => { ctx.beginPath(); ctx.arc(x%tileW, y%tileH, 1.2, 0, Math.PI*2); ctx.fill(); });
      ctx.strokeStyle = '#555'; ctx.lineWidth = 0.8;
      ctx.beginPath(); ctx.moveTo(0,tileH*0.6); ctx.lineTo(tileW,tileH*0.4); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0,tileH*0.2); ctx.lineTo(tileW,tileH*0.35); ctx.stroke();
    }, tileW: 60, tileH: 30,
  },
  {
    name: 'Wood', category: 'hatch',
    tile: (ctx, tileW, tileH) => {
      ctx.strokeStyle = '#8b5a2b'; ctx.lineWidth = 1;
      for (let i = 0; i < 4; i++) {
        const y = (i / 4) * tileH + 3;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.bezierCurveTo(tileW*0.25, y-2, tileW*0.5, y+2, tileW*0.75, y-1);
        ctx.bezierCurveTo(tileW*0.85, y, tileW, y+1, tileW, y);
        ctx.stroke();
      }
    }, tileW: 80, tileH: 20,
  },
  {
    name: 'Insulation', category: 'hatch',
    tile: (ctx, tileW, tileH) => {
      ctx.strokeStyle = '#e0a020'; ctx.lineWidth = 1.5;
      const mid = tileH / 2;
      ctx.beginPath();
      for (let x = 0; x <= tileW; x += 10) {
        ctx.lineTo(x, x % 20 === 0 ? mid - 6 : mid + 6);
      }
      ctx.stroke();
      ctx.strokeStyle = '#555'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(tileW,0); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0,tileH); ctx.lineTo(tileW,tileH); ctx.stroke();
    }, tileW: 60, tileH: 24,
  },
  {
    name: 'Earth', category: 'hatch',
    tile: (ctx, tileW, tileH) => {
      ctx.strokeStyle = '#6b4c2a'; ctx.lineWidth = 1;
      // diagonal hatching
      for (let i = -tileH; i < tileW + tileH; i += 10) {
        ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i + tileH, tileH); ctx.stroke();
      }
      // dots
      ctx.fillStyle = '#6b4c2a';
      [[15,10],[35,6],[55,15],[10,20],[45,22]].forEach(([x,y]) => {
        ctx.beginPath(); ctx.arc(x, y, 1.5, 0, Math.PI*2); ctx.fill();
      });
    }, tileW: 60, tileH: 30,
  },
  {
    name: 'Water', category: 'hatch',
    tile: (ctx, tileW, tileH) => {
      ctx.strokeStyle = '#1e6fa8'; ctx.lineWidth = 1.2;
      [0.3, 0.65, 1.0].forEach(f => {
        const y = f * tileH;
        ctx.beginPath();
        for (let x = 0; x <= tileW; x += 12) {
          ctx.quadraticCurveTo(x + 3, y - 4, x + 6, y);
          ctx.quadraticCurveTo(x + 9, y + 4, x + 12, y);
        }
        ctx.stroke();
      });
    }, tileW: 48, tileH: 18,
  },
];

// Pre-build OffscreenCanvas tiles for fast pattern access
const _hatchTiles = {};
function getHatchTile(hatch) {
  const key = hatch._key || hatch.name;
  if (_hatchTiles[key]) return _hatchTiles[key];
  const oc = document.createElement('canvas');
  oc.width = hatch.tileW; oc.height = hatch.tileH;
  const octx = oc.getContext('2d');
  octx.clearRect(0, 0, hatch.tileW, hatch.tileH);
  hatch.tile(octx, hatch.tileW, hatch.tileH);
  _hatchTiles[key] = oc;
  return oc;
}

// Built-in + user-imported hatches, in one list.
function hatchList() { return HATCH_PATTERNS.concat(state.customHatches); }

// Build a custom hatch object from a loaded image. The image becomes the
// repeating tile (capped to 256px on the long side for tiling performance).
function buildCustomHatch(name, img, dataUrl) {
  const cap = 256;
  const scale = Math.min(1, cap / Math.max(img.naturalWidth || img.width, img.naturalHeight || img.height));
  const tileW = Math.max(2, Math.round((img.naturalWidth || img.width) * scale));
  const tileH = Math.max(2, Math.round((img.naturalHeight || img.height) * scale));
  return {
    name, category: 'hatch', custom: true,
    _key: 'custom:' + name + ':' + Date.now() + ':' + Math.random().toString(36).slice(2, 6),
    img, dataUrl, tileW, tileH,
    tile: (ctx, w, h) => ctx.drawImage(img, 0, 0, w, h),
  };
}

function addCustomHatchFromFile(file) {
  const reader = new FileReader();
  reader.onload = (ev) => {
    const img = new Image();
    img.onload = () => {
      const name = file.name.replace(/\.[^.]+$/, '') || 'Hatch';
      state.customHatches.push(buildCustomHatch(name, img, ev.target.result));
      if (state.stencilCat === 'hatch') renderStencilsWithHatch();
      persistHatches();
      showHint(`Added hatch: ${name}`);
    };
    img.src = ev.target.result;
  };
  reader.readAsDataURL(file);
}

function persistHatches() {
  try {
    const slim = state.customHatches.map(h => ({ name: h.name, dataUrl: h.dataUrl }));
    localStorage.setItem('nm-hatches', JSON.stringify(slim));
  } catch (e) {}
}

function loadHatches() {
  try {
    const raw = localStorage.getItem('nm-hatches');
    if (!raw) return;
    JSON.parse(raw).forEach(rec => {
      const img = new Image();
      img.onload = () => {
        state.customHatches.push(buildCustomHatch(rec.name, img, rec.dataUrl));
        if (state.stencilCat === 'hatch') renderStencilsWithHatch();
      };
      img.src = rec.dataUrl;
    });
  } catch (e) {}
}

function placeHatch(hatchPattern, ctx, cx, cy, size, rad) {
  const tile = getHatchTile(hatchPattern);
  const pattern = ctx.createPattern(tile, 'repeat');
  const s = size;
  ctx.save();
  ctx.globalAlpha = state.alpha;
  ctx.globalCompositeOperation = 'source-over';
  ctx.translate(cx, cy);
  if (rad) ctx.rotate(rad);
  // offset pattern so it tiles from the patch origin
  const mat = new DOMMatrix().translate(-s/2, -s/2);
  pattern.setTransform(mat);
  ctx.fillStyle = pattern;
  ctx.fillRect(-s/2, -s/2, s, s);
  ctx.restore();
}

/* =================================================================
   FEATURE 3 — ROOM AREA POLYGON
   ================================================================= */
state.polyPoints = [];
state.polyActive = false;

function startPolyTool() {
  state.polyPoints = [];
  state.polyActive = true;
  document.getElementById('poly-hint').style.display = 'block';
  refreshAreaOverlay();
}

function snapVertex(p) {
  if (state.snapEnabled === false) return { x: p.x, y: p.y, snap: null };
  const scale = (state.zoom || 1) * (state.baseZoom || 1);
  const thr = 14 / scale;                 // 14 screen-px tolerance → doc px
  // 1) snap to an existing corner (rooms, poly points, wall endpoints)
  let best = null, bestD = thr;
  const consider = (v) => { const d = Math.hypot(p.x - v.x, p.y - v.y); if (d < bestD) { bestD = d; best = v; } };
  state.measurements.forEach(m => { if (m.type === 'area' && m.points) m.points.forEach(consider); });
  state.polyPoints.forEach(consider);
  if (state.wallsVisible !== false) {
    (state.walls || []).forEach(w => { if (w.pts) w.pts.forEach(consider); });
  }
  if (best) return { x: best.x, y: best.y, snap: 'corner' };
  // 2) snap to the grid when one is shown
  if (state.showGrid && state.gridType && state.gridType !== 'off') {
    const sp = mmToDocPx(state.gridSpacingMM);
    if (sp > 1) {
      const gx = Math.round(p.x / sp) * sp, gy = Math.round(p.y / sp) * sp;
      if (Math.hypot(p.x - gx, p.y - gy) < thr) return { x: gx, y: gy, snap: 'grid' };
    }
  }
  return { x: p.x, y: p.y, snap: null };
}

function flashSnap(kind) {
  const b = document.getElementById('snap-badge');
  if (!b) return;
  b.textContent = kind === 'grid' ? '\u2610 GRID SNAP' : '\u2610 CORNER SNAP';
  b.classList.add('show');
  clearTimeout(state._snapBadgeT);
  state._snapBadgeT = setTimeout(() => b.classList.remove('show'), 650);
}

function addPolyVertex(p) {
  if (!state.polyActive) return;
  const s = snapVertex(p);
  p = { x: s.x, y: s.y };
  if (s.snap) flashSnap(s.snap);
  // Close if near first vertex
  if (state.polyPoints.length >= 3) {
    const first = state.polyPoints[0];
    const dx = p.x - first.x, dy = p.y - first.y;
    const screenDist = Math.sqrt(dx*dx+dy*dy) * state.zoom * state.baseZoom;
    if (screenDist < 22) { closePoly(); return; }
  }
  state.polyPoints.push({ x: p.x, y: p.y });
  refreshAreaOverlay();
}

function closePoly() {
  if (state.tool === 'wall') { commitWall(true); return; }
  if (state.polyPoints.length < 3) return;
  if (state.tool === 'line') { commitPolygonShape(true); return; }
  const area = shoelaceArea(state.polyPoints);
  const areaLabel = formatArea(area);
  const roomName = 'Room ' + (state.measurements.filter(m => m.type === 'area').length + 1);
  const __b = vectorSnapshot();
  state.measurements.push({
    type: 'area',
    name: roomName,
    points: [...state.polyPoints],
    label: areaLabel,
    x1: state.polyPoints[0].x, y1: state.polyPoints[0].y,
    x2: state.polyPoints[0].x, y2: state.polyPoints[0].y,
  });
  state.polyPoints = [];
  state.polyActive = false;
  document.getElementById('poly-hint').style.display = 'none';
  refreshMeasurements();
  renderSchedule();
  recordVec(__b);
  showHint(`${roomName}: ${areaLabel}`);
}

// Finish the in-progress polyline. Polygon tool: 3+ pts → closed polygon,
// exactly 2 → an open line, otherwise cancel. Area tool: needs 3+ to close.
function finishPoly() {
  if (state.tool === 'wall') {
    if (state.polyPoints.length >= 2) commitWall(false); else cancelPoly();
    return;
  }
  if (state.tool === 'line') {
    if (state.polyPoints.length >= 3) commitPolygonShape(true);
    else if (state.polyPoints.length === 2) commitPolygonShape(false);
    else cancelPoly();
  } else if (state.polyPoints.length >= 3) {
    closePoly();
  }
}

function commitWall(closed) {
  const pts = state.polyPoints.slice();
  if (pts.length < 2) { cancelPoly(); return; }
  if (closed && pts.length >= 3 &&
      (pts[0].x !== pts[pts.length - 1].x || pts[0].y !== pts[pts.length - 1].y)) {
    pts.push({ x: pts[0].x, y: pts[0].y });   // seal the loop
  }
  const __b = vectorSnapshot();
  state.walls.push({ pts, thickMM: state.wallThickMM, heightM: state.wallHeightM });
  // Rasterize wall centerline onto the active layer (erasable like other ink)
  const l = activeLayer();
  l.ctx.save();
  l.ctx.globalCompositeOperation = 'source-over';
  l.ctx.globalAlpha = state.alpha;
  l.ctx.strokeStyle = state.color;
  l.ctx.lineWidth = Math.max(1, state.size);
  l.ctx.lineCap = 'round';
  l.ctx.lineJoin = 'round';
  l.ctx.beginPath();
  l.ctx.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < pts.length; i++) l.ctx.lineTo(pts[i].x, pts[i].y);
  l.ctx.stroke();
  l.ctx.restore();
  saveSnapshot(l);
  state.polyPoints = [];
  state.polyActive = false;
  document.getElementById('poly-hint').style.display = 'none';
  refreshMeasurements();
  syncWallsToMasses();
  recordVec(__b);
  scheduleAutosave();
  showHint(`Wall added · ${state.wallThickMM} mm \u00d7 ${state.wallHeightM} m · view in 3D`);
}

function cancelPoly() {
  state.polyPoints = [];
  state.polyActive = false;
  const ph = document.getElementById('poly-hint');
  if (ph) ph.style.display = 'none';
  refreshMeasurements();
}

// Commit the in-progress polygon as ink on the active layer.
// closed=true → closed polygon (fill/extrude-ready); false → open polyline.
function commitPolygonShape(closed) {
  const pts = state.polyPoints.slice();
  if (pts.length < 2) { cancelPoly(); return; }
  const isPolygon = closed && pts.length >= 3;
  const entity = { kind: 'polygon', pts: pts.map(p => ({ x: p.x, y: p.y })), closed: !!closed, stroke: state.color, width: Math.max(0.5, state.size) };
  const __b = vectorSnapshot(); state.shapes.push(entity); recordVec(__b); scheduleAutosave();
  // Rasterize onto the active layer so eraser and partial edits work
  const l = activeLayer();
  l.ctx.save();
  l.ctx.globalCompositeOperation = 'source-over';
  l.ctx.globalAlpha = state.alpha;
  l.ctx.strokeStyle = state.color;
  l.ctx.lineWidth = Math.max(0.5, state.size);
  l.ctx.lineCap = 'round';
  l.ctx.lineJoin = 'round';
  l.ctx.beginPath();
  l.ctx.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < pts.length; i++) l.ctx.lineTo(pts[i].x, pts[i].y);
  if (isPolygon) l.ctx.closePath();
  l.ctx.stroke();
  l.ctx.restore();
  saveSnapshot(l);
  state.polyPoints = [];
  state.polyActive = false;
  const ph = document.getElementById('poly-hint');
  if (ph) ph.style.display = 'none';
  refreshMeasurements();
  renderLayers();
  if (isPolygon && typeof onShapeCommitted === 'function') {
    onShapeCommitted({ kind: 'polygon', pts }, state._lastPolyClient);
  }
  showHint(isPolygon ? 'Polygon placed' : 'Line placed');
}

function shoelaceArea(pts) {
  let area = 0;
  for (let i = 0; i < pts.length; i++) {
    const j = (i + 1) % pts.length;
    area += pts[i].x * pts[j].y;
    area -= pts[j].x * pts[i].y;
  }
  return Math.abs(area) / 2; // in doc px²
}

function perimeterPx(pts, closed = true) {
  if (!pts || pts.length < 2) return 0;
  let per = 0;
  const n = pts.length;
  const last = closed ? n : n - 1;
  for (let i = 0; i < last; i++) {
    const a = pts[i], b = pts[(i + 1) % n];
    per += Math.hypot(b.x - a.x, b.y - a.y);
  }
  return per; // in doc px
}

function formatArea(areaPx2) {
  if (state.pxPerUnit && state.scaleUnit) {
    const u = state.scaleUnit;
    const unitInMm = { mm:1, cm:10, m:1000, in:25.4, ft:304.8 }[u] || 1;
    const mmPerPx = unitInMm / state.pxPerUnit;
    const areaMm2 = areaPx2 * mmPerPx * mmPerPx;   // true physical area, in mm²
    if (u === 'in' || u === 'ft') {                // imperial family → in² ↔ ft²
      const ft2 = areaMm2 / 92903.04;              // 1 ft² = 304.8² mm²
      if (ft2 >= 1) return `${ft2.toFixed(2)} ft²`;
      return `${(areaMm2 / 645.16).toFixed(1)} in²`; // 1 in² = 25.4² mm²
    }
    // metric family → mm² ↔ cm² ↔ m²
    const m2 = areaMm2 / 1e6;
    if (m2 >= 1) return `${m2.toFixed(2)} m²`;
    const cm2 = areaMm2 / 100;
    if (cm2 >= 1) return `${cm2.toFixed(1)} cm²`;
    return `${areaMm2.toFixed(0)} mm²`;
  }
  // No scale set — estimate from canvas px
  const docPxPerMm = DOC_W_PX / DOC_W_MM;
  const areaMm2 = areaPx2 / (docPxPerMm * docPxPerMm);
  return `${(areaMm2 / 100).toFixed(0)} cm² (est.)`;
}

function formatLen(px) {
  if (state.pxPerUnit && state.scaleUnit) {
    const u = state.scaleUnit;
    const unitInMm = { mm:1, cm:10, m:1000, in:25.4, ft:304.8 }[u] || 1;
    const mm = (px / state.pxPerUnit) * unitInMm;   // true physical length, in mm
    if (u === 'in' || u === 'ft') {                 // imperial → in ↔ ft
      const ft = mm / 304.8;
      if (ft >= 1) return `${ft.toFixed(2)} ft`;
      return `${(mm / 25.4).toFixed(1)} in`;
    }
    const m = mm / 1000;                            // metric → mm ↔ cm ↔ m
    if (m >= 1) return `${m.toFixed(2)} m`;
    const cm = mm / 10;
    if (cm >= 1) return `${cm.toFixed(1)} cm`;
    return `${mm.toFixed(0)} mm`;
  }
  return `${Math.round(px)} px`;
}

function ensureSchedulePanel() {
  if (document.getElementById('room-schedule')) return;
  const style = document.createElement('style');
  style.textContent = `
    #room-schedule{position:fixed;left:68px;bottom:16px;width:290px;max-height:46vh;background:rgba(255,255,255,0.97);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border:1px solid rgba(0,0,0,0.10);border-radius:12px;box-shadow:0 8px 30px rgba(0,0,0,0.20);z-index:30;display:none;flex-direction:column;overflow:hidden;}
    #room-schedule.show{display:flex;}
    #rs-head{display:flex;align-items:center;gap:8px;padding:10px 12px;border-bottom:1px solid rgba(0,0,0,0.08);}
    #rs-head .t{font-size:12px;font-weight:700;letter-spacing:0.4px;color:#0a0a0a;flex:1;}
    #rs-head button{border:none;background:transparent;cursor:pointer;font-size:14px;color:#666;padding:2px 7px;border-radius:6px;}
    #rs-head button:hover{background:rgba(0,0,0,0.06);}
    #rs-rows{overflow-y:auto;padding:3px 0;}
    .rs-row{display:flex;align-items:center;gap:5px;padding:5px 10px 5px 12px;}
    .rs-row input.nm{flex:1;min-width:0;border:1px solid transparent;background:transparent;font-family:inherit;font-size:12px;font-weight:600;color:#0a0a0a;padding:3px 5px;border-radius:5px;}
    .rs-row input.nm:focus{border-color:#cbcbcb;background:#fff;outline:none;}
    .rs-row .ar{font-family:JetBrains Mono,monospace;font-size:11px;color:#333;white-space:nowrap;}
    .rs-row .vd{font-size:9px;font-weight:700;letter-spacing:0.3px;text-transform:uppercase;color:#888;cursor:pointer;border:1px solid #cbcbcb;border-radius:5px;padding:3px 5px;user-select:none;}
    .rs-row .vd.on{background:#a02835;color:#fff;border-color:#a02835;}
    .rs-row .dl{border:none;background:transparent;color:#b00020;cursor:pointer;font-size:16px;line-height:1;padding:0 3px;}
    .rs-row.void input.nm{text-decoration:line-through;color:#9aa;}
    #rs-foot{display:flex;align-items:center;justify-content:space-between;padding:9px 13px;border-top:1px solid rgba(0,0,0,0.08);}
    #rs-foot .tl{font-size:11px;font-weight:700;letter-spacing:0.6px;color:#666;text-transform:uppercase;}
    #rs-foot .tv{font-family:JetBrains Mono,monospace;font-size:14px;font-weight:700;color:#15803d;}
    #rs-toggle{position:fixed;left:68px;bottom:16px;z-index:29;background:#15803d;color:#fff;border:none;border-radius:20px;padding:9px 15px;font-family:inherit;font-size:12px;font-weight:700;letter-spacing:0.3px;box-shadow:0 4px 14px rgba(0,0,0,0.22);cursor:pointer;display:none;align-items:center;gap:6px;}
    #rs-toggle.show{display:flex;}
  `;
  document.head.appendChild(style);
  const panel = document.createElement('div');
  panel.id = 'room-schedule';
  panel.innerHTML = '<div id="rs-head"><span class="t">Room Schedule</span><button id="rs-collapse" title="Hide">\u25be</button></div><div id="rs-rows"></div><div id="rs-foot"><span class="tl">Total</span><span class="tv" id="rs-total">\u2014</span></div>';
  document.body.appendChild(panel);
  const toggle = document.createElement('button');
  toggle.id = 'rs-toggle';
  document.body.appendChild(toggle);
  document.getElementById('rs-collapse').addEventListener('click', () => { state._scheduleHidden = true; renderSchedule(); });
  toggle.addEventListener('click', () => { state._scheduleHidden = false; renderSchedule(); });
}

function scheduleAreaRooms() {
  return state.measurements
    .map((m, i) => ({ m, i }))
    .filter(o => o.m.type === 'area' && o.m.points && o.m.points.length >= 3);
}

function renderSchedule() {
  ensureSchedulePanel();
  const panel = document.getElementById('room-schedule');
  const toggle = document.getElementById('rs-toggle');
  const rows = document.getElementById('rs-rows');
  const rooms = scheduleAreaRooms();

  if (rooms.length === 0) {
    panel.classList.remove('show');
    toggle.classList.remove('show');
    rows.innerHTML = '';
    return;
  }

  rows.innerHTML = '';
  let totalPx2 = 0;
  rooms.forEach(({ m, i }) => {
    const a = shoelaceArea(m.points);
    if (!m.void) totalPx2 += a;   // void = kept for reference but not counted

    const row = document.createElement('div');
    row.className = 'rs-row' + (m.void ? ' void' : '');

    const nm = document.createElement('input');
    nm.className = 'nm';
    nm.value = m.name || ('Room ' + (i + 1));
    nm.setAttribute('aria-label', 'Room name');
    nm.addEventListener('input', () => { m.name = nm.value; });
    nm.addEventListener('change', () => { m.name = nm.value; refreshMeasurements(); scheduleAutosave(); });

    const ar = document.createElement('span');
    ar.className = 'ar';
    ar.innerHTML = formatArea(a) + ' <span style="color:#9aa;font-weight:400;">\u00b7 ' + formatLen(perimeterPx(m.points)) + '</span>';

    const vd = document.createElement('span');
    vd.className = 'vd' + (m.void ? ' on' : '');
    vd.textContent = 'void';
    vd.title = 'Subtract from total (courtyard, shaft, etc.)';
    vd.addEventListener('click', () => { m.void = !m.void; refreshMeasurements(); renderSchedule(); scheduleAutosave(); });

    const dl = document.createElement('button');
    dl.className = 'dl';
    dl.textContent = '\u00d7';
    dl.title = 'Delete room';
    dl.addEventListener('click', () => { deleteMeasurement(i); });

    row.append(nm, ar, vd, dl);
    rows.appendChild(row);
  });

  document.getElementById('rs-total').textContent = formatArea(Math.max(0, totalPx2));

  if (state._scheduleHidden) {
    panel.classList.remove('show');
    toggle.textContent = 'Schedule (' + rooms.length + ')';
    toggle.classList.add('show');
  } else {
    panel.classList.add('show');
    toggle.classList.remove('show');
  }
}

function wallThickPx(w) {
  return Math.max(2, (w.thickMM / 1000) * pxPerMetre());
}

const _SVGNS = 'http://www.w3.org/2000/svg';
function _ovLine(x1, y1, x2, y2, stroke, wdt, dash) {
  const l = document.createElementNS(_SVGNS, 'line');
  l.setAttribute('x1', x1); l.setAttribute('y1', y1); l.setAttribute('x2', x2); l.setAttribute('y2', y2);
  l.setAttribute('stroke', stroke); l.setAttribute('stroke-width', wdt); l.setAttribute('stroke-linecap', 'round');
  if (dash) l.setAttribute('stroke-dasharray', dash);
  rulerOverlay.appendChild(l);
}
// Door plan symbol: leaf + quarter swing arc. J0/J1 = jamb centre points; px,py = wall normal.
function drawDoorSymbol(o, J0, J1, px, py, col) {
  const Wpx = Math.hypot(J1.x - J0.x, J1.y - J0.y);
  const hand = (o.hand >= 0) ? 1 : -1, sw = (o.swing >= 0) ? 1 : -1;
  const H = hand > 0 ? J0 : J1, O = hand > 0 ? J1 : J0;   // hinge / latch jamb
  const tip = { x: H.x + px * sw * Wpx, y: H.y + py * sw * Wpx };
  _ovLine(H.x, H.y, tip.x, tip.y, col, 1.6);               // leaf at 90°
  const a0 = Math.atan2(O.y - H.y, O.x - H.x), a1 = Math.atan2(tip.y - H.y, tip.x - H.x);
  let da = a1 - a0; while (da > Math.PI) da -= 2 * Math.PI; while (da < -Math.PI) da += 2 * Math.PI;
  let d = `M ${O.x} ${O.y}`;
  for (let k = 1; k <= 16; k++) { const ang = a0 + da * (k / 16); d += ` L ${H.x + Math.cos(ang) * Wpx} ${H.y + Math.sin(ang) * Wpx}`; }
  const arc = document.createElementNS(_SVGNS, 'path');
  arc.setAttribute('d', d); arc.setAttribute('fill', 'none'); arc.setAttribute('stroke', '#9a9a9a'); arc.setAttribute('stroke-width', '1'); arc.setAttribute('stroke-dasharray', '4 3');
  rulerOverlay.appendChild(arc);
}
// Window plan symbol: frame faces across the opening + two glass lines.
function drawWindowSymbol(o, J0, J1, px, py, h, col) {
  _ovLine(J0.x + px*h, J0.y + py*h, J1.x + px*h, J1.y + py*h, col, 1.2);
  _ovLine(J0.x - px*h, J0.y - py*h, J1.x - px*h, J1.y - py*h, col, 1.2);
  const g = h * 0.42;
  _ovLine(J0.x + px*g, J0.y + py*g, J1.x + px*g, J1.y + py*g, '#4a6b8a', 1);
  _ovLine(J0.x - px*g, J0.y - py*g, J1.x - px*g, J1.y - py*g, '#4a6b8a', 1);
}

// Render one wall: poché + double-lines, broken at openings, with door/window symbols.
function renderOneWall(w, svgns, wi) {
  const pts = w.pts;
  if (!pts || pts.length < 2) return;
  const tPx = wallThickPx(w), h = tPx / 2;
  const n = pts.length;
  const closed = n > 2 && pts[0].x === pts[n - 1].x && pts[0].y === pts[n - 1].y;
  const segs = n - 1;
  const ppm = pxPerMetre();
  const selW = state.sel && state.sel.type === 'wall' && state.sel.wi === wi;
  const wFill = selW ? 'rgba(160,40,53,0.32)' : 'rgba(48,48,52,0.82)';
  const wcol = selW ? '#a02835' : '#161616';
  for (let i = 0; i < segs; i++) {
    const a = pts[i], b = pts[i + 1];
    const dx = b.x - a.x, dy = b.y - a.y, segLen = Math.hypot(dx, dy) || 1e-6;
    const ux = dx / segLen, uy = dy / segLen, px = -uy, py = ux;
    const sIn = closed || i > 0, eIn = closed || i < segs - 1;
    const ops = (w.openings || []).map((o, idx) => ({ o, idx })).filter(x => x.o.seg === i).map(x => {
      const half = (x.o.wMM / 1000 * ppm) / 2, c = x.o.t * segLen;
      return { o: x.o, idx: x.idx, d0: Math.max(0, c - half), d1: Math.min(segLen, c + half) };
    }).sort((A, B) => A.d0 - B.d0);
    // solid spans = segment minus opening intervals
    const spans = []; let cur = 0;
    ops.forEach(op => { if (op.d0 > cur) spans.push([cur, op.d0]); cur = Math.max(cur, op.d1); });
    if (cur < segLen) spans.push([cur, segLen]);
    spans.forEach(([s0, s1]) => {
      const startJoint = (s0 <= 0.01 && sIn), endJoint = (s1 >= segLen - 0.01 && eIn);
      const pax = a.x + ux * (s0 - (startJoint ? h : 0)), pay = a.y + uy * (s0 - (startJoint ? h : 0));
      const pbx = a.x + ux * (s1 + (endJoint ? h : 0)), pby = a.y + uy * (s1 + (endJoint ? h : 0));
      const poly = document.createElementNS(svgns, 'polygon');
      poly.setAttribute('points', `${pax + px*h},${pay + py*h} ${pbx + px*h},${pby + py*h} ${pbx - px*h},${pby - py*h} ${pax - px*h},${pay - py*h}`);
      poly.setAttribute('fill', wFill); poly.setAttribute('stroke', 'none');
      rulerOverlay.appendChild(poly);
      const ls = s0 + (startJoint ? h : 0), le = s1 - (endJoint ? h : 0);
      const Ax = a.x + ux*ls, Ay = a.y + uy*ls, Bx = a.x + ux*le, By = a.y + uy*le;
      _ovLine(Ax + px*h, Ay + py*h, Bx + px*h, By + py*h, wcol, 1.5);
      _ovLine(Ax - px*h, Ay - py*h, Bx - px*h, By - py*h, wcol, 1.5);
      if (s0 <= 0.01 && !sIn) _ovLine(a.x + px*h, a.y + py*h, a.x - px*h, a.y - py*h, wcol, 1.5);
      if (s1 >= segLen - 0.01 && !eIn) _ovLine(b.x + px*h, b.y + py*h, b.x - px*h, b.y - py*h, wcol, 1.5);
    });
    ops.forEach(op => {
      const sel = state.selOpening2D && state.selOpening2D.wi === wi && state.selOpening2D.idx === op.idx;
      const col = sel ? '#a02835' : '#161616';
      const J0 = { x: a.x + ux*op.d0, y: a.y + uy*op.d0 }, J1 = { x: a.x + ux*op.d1, y: a.y + uy*op.d1 };
      _ovLine(J0.x + px*h, J0.y + py*h, J0.x - px*h, J0.y - py*h, col, 1.6);
      _ovLine(J1.x + px*h, J1.y + py*h, J1.x - px*h, J1.y - py*h, col, 1.6);
      if (op.o.kind === 'door') drawDoorSymbol(op.o, J0, J1, px, py, col);
      else drawWindowSymbol(op.o, J0, J1, px, py, h, col);
    });
  }
}

function renderShapes2D() {
  const svgns = 'http://www.w3.org/2000/svg';
  (state.shapes || []).forEach((sh, si) => {
    const selSh = state.sel && state.sel.type === 'shape' && state.sel.idx === si;
    const stroke = selSh ? '#a02835' : (sh.stroke || '#1c1a18');
    const w = sh.width || 2;
    if (sh.kind === 'ellipse') {
      const el = document.createElementNS(svgns, 'ellipse');
      el.setAttribute('cx', sh.cx); el.setAttribute('cy', sh.cy);
      el.setAttribute('rx', sh.rx); el.setAttribute('ry', sh.ry);
      el.setAttribute('fill', 'none'); el.setAttribute('stroke', stroke); el.setAttribute('stroke-width', w);
      rulerOverlay.appendChild(el);
    } else {
      const pts = sh.pts || []; if (pts.length < 2) return;
      const tag = (sh.closed || sh.kind === 'rect') ? 'polygon' : 'polyline';
      const el = document.createElementNS(svgns, tag);
      el.setAttribute('points', pts.map(p => `${p.x},${p.y}`).join(' '));
      el.setAttribute('fill', 'none'); el.setAttribute('stroke', stroke); el.setAttribute('stroke-width', w);
      el.setAttribute('stroke-linejoin', 'round'); el.setAttribute('stroke-linecap', 'round');
      rulerOverlay.appendChild(el);
    }
  });
}

function renderWalls2D() {
  if (state.wallsVisible === false) return;
  if (!state.walls || !state.walls.length) return;
  const svgns = _SVGNS;
  state.walls.forEach((w, wi) => renderOneWall(w, svgns, wi));
}

// Rebuild extruded wall masses from the 2D walls (carrying openings) so they appear & cut in 3D.
// Face features added in 3D (push/pull regions, sketches, materials) are preserved across the
// rebuild, keyed by wall:segment, so a 2D↔3D round-trip or a reload doesn't wipe them.
function syncWallsToMasses() {
  if (typeof massing === 'undefined' || !massing.masses) return;
  const anchor = massing.baseAnchor || { px: DOC_W_PX / 2, py: DOC_H_PX / 2, ppm: pxPerMetre() };
  const ax = anchor.px, ay = anchor.py, ppm = anchor.ppm || pxPerMetre();
  const saved = {};
  massing.masses.forEach(m => {
    if (m._fromWall && m._wallKey) saved[m._wallKey] = { faceRegions: m.faceRegions, faceArt: m.faceArt, faceMat: m.faceMat, _faceImg: m._faceImg };
  });
  massing.masses = massing.masses.filter(m => !m._fromWall);
  (state.walls || []).forEach((w, wi) => {
    const tW = (w.thickMM || 230) / 1000;
    const pts = w.pts;
    for (let i = 0; i < pts.length - 1; i++) {
      const a = { x: (pts[i].x - ax) / ppm, z: (pts[i].y - ay) / ppm };
      const b = { x: (pts[i + 1].x - ax) / ppm, z: (pts[i + 1].y - ay) / ppm };
      const mass = { poly: wallSegPoly(a, b, tW), h: (w.heightM || 3), _wall: true, _fromWall: true, _wallKey: wi + ':' + i };
      const segOps = (w.openings || []).filter(o => o.seg === i);
      if (segOps.length) {
        const segLenW = Math.hypot(b.x - a.x, b.z - a.z), massLen = segLenW + tW;
        mass.openings = segOps.map(o => {
          const u = Math.min(0.97, Math.max(0.03, (o.t * segLenW + tW / 2) / massLen));
          return { kind: o.kind, u, w: o.wMM / 1000, h: o.hMM / 1000, sill: o.sillMM / 1000 };
        });
      }
      const sv = saved[mass._wallKey];
      if (sv) {                                  // re-attach 3D face features to the same wall segment
        if (sv.faceRegions) mass.faceRegions = sv.faceRegions;
        if (sv.faceArt) mass.faceArt = sv.faceArt;
        if (sv.faceMat) mass.faceMat = sv.faceMat;
        if (sv._faceImg) mass._faceImg = sv._faceImg;
      }
      massing.masses.push(mass);
    }
  });
}

// ---- placing / selecting / sliding openings on 2D walls ----
function wallSegHit(p) {
  if (state.wallsVisible === false) return null;
  let best = null;
  (state.walls || []).forEach((w, wi) => {
    const tPx = wallThickPx(w);
    for (let i = 0; i < w.pts.length - 1; i++) {
      const a = w.pts[i], b = w.pts[i + 1];
      const dx = b.x - a.x, dy = b.y - a.y, len2 = dx*dx + dy*dy || 1;
      let t = ((p.x - a.x) * dx + (p.y - a.y) * dy) / len2; t = Math.max(0, Math.min(1, t));
      const cx = a.x + dx*t, cy = a.y + dy*t, d = Math.hypot(p.x - cx, p.y - cy);
      if (d < tPx/2 + 14 && (!best || d < best.d)) best = { wi, seg: i, t, d, segLen: Math.hypot(dx, dy) };
    }
  });
  return best;
}
function openingDims(kind) {
  return kind === 'door'
    ? { wMM: state.doorWMM, hMM: state.doorHMM, sillMM: 0 }
    : { wMM: state.winWMM, hMM: state.winHMM, sillMM: state.winSillMM };
}
function placeOpening2D(p) {
  const hit = wallSegHit(p);
  if (!hit) { showHint('Tap on a wall to place a ' + state.openingKind); return; }
  const w = state.walls[hit.wi];
  const dims = openingDims(state.openingKind);
  const halfFrac = ((dims.wMM / 1000) * pxPerMetre() / 2) / Math.max(1, hit.segLen);
  if (halfFrac >= 0.48) { showHint('Wall segment too short for this ' + state.openingKind); return; }
  const t = Math.max(halfFrac + 0.02, Math.min(1 - halfFrac - 0.02, hit.t));
  const __b = vectorSnapshot();
  w.openings = w.openings || [];
  w.openings.push({ kind: state.openingKind, seg: hit.seg, t, wMM: dims.wMM, hMM: dims.hMM, sillMM: dims.sillMM, hand: 1, swing: 1 });
  state.selOpening2D = { wi: hit.wi, idx: w.openings.length - 1 };
  refreshMeasurements(); syncWallsToMasses(); updateOpeningPalette(); recordVec(__b); scheduleAutosave();
  showHint(`${state.openingKind === 'door' ? 'Door' : 'Window'} placed · drag to slide · flip & resize in the bar`);
}
function openingHitTest2D(p) {
  if (state.wallsVisible === false) return null;
  let best = null;
  (state.walls || []).forEach((w, wi) => {
    (w.openings || []).forEach((o, idx) => {
      const a = w.pts[o.seg], b = w.pts[o.seg + 1]; if (!a || !b) return;
      const cx = a.x + (b.x - a.x) * o.t, cy = a.y + (b.y - a.y) * o.t, d = Math.hypot(p.x - cx, p.y - cy);
      if (d < wallThickPx(w)/2 + 12 && (!best || d < best.d)) best = { wi, idx, d };
    });
  });
  return best ? { wi: best.wi, idx: best.idx } : null;
}
function slideOpening2D(sel, p) {
  const w = state.walls[sel.wi]; if (!w) return;
  const o = w.openings[sel.idx]; if (!o) return;
  const a = w.pts[o.seg], b = w.pts[o.seg + 1];
  const dx = b.x - a.x, dy = b.y - a.y, len2 = dx*dx + dy*dy || 1, segLen = Math.sqrt(len2);
  let t = ((p.x - a.x) * dx + (p.y - a.y) * dy) / len2;
  const halfFrac = ((o.wMM / 1000) * pxPerMetre() / 2) / Math.max(1, segLen);
  o.t = Math.max(halfFrac + 0.02, Math.min(1 - halfFrac - 0.02, t));
  refreshMeasurements(); syncWallsToMasses();
}
function deleteOpening2D(sel) {
  const w = state.walls[sel.wi]; if (!w || !w.openings) return;
  const __b = vectorSnapshot();
  w.openings.splice(sel.idx, 1);
  state.selOpening2D = null;
  refreshMeasurements(); syncWallsToMasses(); updateOpeningPalette(); recordVec(__b); scheduleAutosave();
}
function selectedOpening2D() {
  const s = state.selOpening2D; if (!s) return null;
  const w = state.walls[s.wi]; return (w && w.openings) ? w.openings[s.idx] : null;
}

let _wall2dPaletteEl = null;
function ensureWall2dPalette() {
  if (_wall2dPaletteEl) return _wall2dPaletteEl;
  const el = document.createElement('div');
  el.id = 'wall2d-palette';
  el.style.cssText = 'position:fixed;top:64px;left:50%;transform:translateX(-50%);display:none;gap:12px;align-items:center;background:rgba(255,255,255,0.97);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border:1px solid rgba(0,0,0,0.10);border-radius:10px;padding:7px 13px;box-shadow:0 6px 22px rgba(0,0,0,0.16);z-index:31;font-size:11px;';
  el.innerHTML = '<span style="font-weight:700;letter-spacing:0.5px;color:#a02835;">WALL</span>'
    + '<label style="display:flex;align-items:center;gap:5px;color:#555;">Thick <input id="w2-thick" type="number" min="50" max="600" step="10" value="230" style="width:56px;font-family:inherit;font-size:11px;padding:3px 5px;border:1px solid #ccc;border-radius:5px;"> mm</label>'
    + '<label style="display:flex;align-items:center;gap:5px;color:#555;">Height <input id="w2-height" type="number" min="0.5" max="20" step="0.1" value="3" style="width:52px;font-family:inherit;font-size:11px;padding:3px 5px;border:1px solid #ccc;border-radius:5px;"> m</label>';
  document.body.appendChild(el);
  el.querySelector('#w2-thick').addEventListener('input', e => { const v = parseFloat(e.target.value); if (v > 0) state.wallThickMM = v; });
  el.querySelector('#w2-height').addEventListener('input', e => { const v = parseFloat(e.target.value); if (v > 0) state.wallHeightM = v; });
  _wall2dPaletteEl = el;
  return el;
}
function showWall2dPalette(show) {
  ensureWall2dPalette();
  _wall2dPaletteEl.style.display = show ? 'flex' : 'none';
  if (show) {
    _wall2dPaletteEl.querySelector('#w2-thick').value = state.wallThickMM;
    _wall2dPaletteEl.querySelector('#w2-height').value = state.wallHeightM;
  }
}

