    el.querySelector('#se-height').addEventListener('input', e => { const v = parseFloat(e.target.value); if (v > 0) { const __b = vectorSnapshot(); w.heightM = v; syncWallsToMasses(); recordVec(__b, true); scheduleAutosave(); } });
