function refreshAreaOverlay() {
  // Redraw current polygon preview in the ruler overlay
  refreshMeasurements();
  if (!state.polyActive || state.polyPoints.length === 0) return;
  const svgns = 'http://www.w3.org/2000/svg';
  rulerOverlay.setAttribute('viewBox', `0 0 ${DOC_W_PX} ${DOC_H_PX}`);
  const pts = state.polyPoints;
  // Fill shape
  if (pts.length >= 3) {
    const fill = document.createElementNS(svgns, 'polygon');
    fill.setAttribute('points', pts.map(p => `${p.x},${p.y}`).join(' '));
    fill.setAttribute('class', 'area-fill');
    rulerOverlay.appendChild(fill);
  }
  // Edges
  for (let i = 0; i < pts.length - 1; i++) {
    const l = document.createElementNS(svgns, 'line');
    l.setAttribute('x1', pts[i].x); l.setAttribute('y1', pts[i].y);
    l.setAttribute('x2', pts[i+1].x); l.setAttribute('y2', pts[i+1].y);
    l.setAttribute('class', 'area-edge');
    rulerOverlay.appendChild(l);
  }
  // Vertices
  pts.forEach((p, i) => {
    const c = document.createElementNS(svgns, 'circle');
    c.setAttribute('cx', p.x); c.setAttribute('cy', p.y); c.setAttribute('r', i === 0 ? 14 : 9);
    c.setAttribute('class', 'area-vertex');
    if (i === 0) { c.style.cursor = 'pointer'; }
    rulerOverlay.appendChild(c);
  });
  // Live area (only for the area-measure tool, not the polygon shape tool)
  if (pts.length >= 3 && state.tool === 'area') {
    const area = shoelaceArea(pts);
    const cx = pts.reduce((s, p) => s + p.x, 0) / pts.length;
    const cy = pts.reduce((s, p) => s + p.y, 0) / pts.length;
    const lbl = formatArea(area) + '  \u00b7  ' + formatLen(perimeterPx(pts));
    const bg = document.createElementNS(svgns, 'rect');
    const bw = lbl.length * 16 + 30;
    bg.setAttribute('x', cx - bw/2); bg.setAttribute('y', cy - 22);
    bg.setAttribute('width', bw); bg.setAttribute('height', 36);
    bg.setAttribute('rx', 6); bg.setAttribute('fill', '#15803d');
    rulerOverlay.appendChild(bg);
    const txt = document.createElementNS(svgns, 'text');
    txt.setAttribute('x', cx); txt.setAttribute('y', cy + 4);
    txt.setAttribute('text-anchor', 'middle');
    txt.setAttribute('fill', 'white');
    txt.setAttribute('font-family', 'JetBrains Mono,monospace');
    txt.setAttribute('font-weight', '600');
    txt.setAttribute('font-size', '22');
    txt.setAttribute('pointer-events', 'none');
    txt.textContent = lbl;
    rulerOverlay.appendChild(txt);
  }
}

/* =================================================================
   FEATURE 4 — ARCHITECTURAL DIMENSION CHAIN
   ================================================================= */
state.dimChainMode = false;
state.dimChainEnd = null;

function toggleDimChain() {
  state.dimChainMode = !state.dimChainMode;
  const btn = document.getElementById('btn-dim-chain');
  btn.classList.toggle('chain-active', state.dimChainMode);
  if (!state.dimChainMode) state.dimChainEnd = null;
  showHint(state.dimChainMode
    ? 'Dimension Chain ON — each measurement starts from the last endpoint'
    : 'Dimension Chain OFF');
}

// Architectural-style dimension rendering — replaces addMeasureSVG for ruler lines
function addDimSVG(m, isPreview, mIndex) {
  const svgns = 'http://www.w3.org/2000/svg';
  rulerOverlay.setAttribute('viewBox', `0 0 ${DOC_W_PX} ${DOC_H_PX}`);

  if (m.type === 'area') { addAreaSVG(m, mIndex); return; }

  const color = isPreview ? '#a02835' : '#1d4ed8';
  const dx = m.x2 - m.x1, dy = m.y2 - m.y1;
  const len = Math.sqrt(dx*dx + dy*dy);
  if (len < 2) return;
  const nx = -dy / len, ny = dx / len;
  const extLen = 28, tickLen = 12;

  // Extension lines — non-interactive
  [[m.x1,m.y1],[m.x2,m.y2]].forEach(([x,y]) => {
    const el = document.createElementNS(svgns, 'line');
    el.setAttribute('x1', x + nx * extLen); el.setAttribute('y1', y + ny * extLen);
    el.setAttribute('x2', x - nx * 6);      el.setAttribute('y2', y - ny * 6);
    el.setAttribute('stroke', color); el.setAttribute('stroke-width', '1.5');
    el.setAttribute('pointer-events', 'none');
    rulerOverlay.appendChild(el);
  });

  // Main dimension line — non-interactive
  const dline = document.createElementNS(svgns, 'line');
  dline.setAttribute('x1', m.x1 + nx * extLen); dline.setAttribute('y1', m.y1 + ny * extLen);
  dline.setAttribute('x2', m.x2 + nx * extLen); dline.setAttribute('y2', m.y2 + ny * extLen);
  dline.setAttribute('stroke', color); dline.setAttribute('stroke-width', '2');
  dline.setAttribute('pointer-events', 'none');
  rulerOverlay.appendChild(dline);

  // Tick marks — non-interactive
  [[m.x1,m.y1],[m.x2,m.y2]].forEach(([x,y]) => {
    const tx = x + nx * extLen, ty = y + ny * extLen;
    const ux = dx / len, uy = dy / len;
    const tick = document.createElementNS(svgns, 'line');
    tick.setAttribute('x1', tx - ux * tickLen - nx * tickLen/2);
    tick.setAttribute('y1', ty - uy * tickLen - ny * tickLen/2);
    tick.setAttribute('x2', tx + ux * tickLen + nx * tickLen/2);
    tick.setAttribute('y2', ty + uy * tickLen + ny * tickLen/2);
    tick.setAttribute('stroke', color); tick.setAttribute('stroke-width', '2.5');
    tick.setAttribute('pointer-events', 'none');
    rulerOverlay.appendChild(tick);
  });

  // Endpoint dots — non-interactive
  [[m.x1,m.y1],[m.x2,m.y2]].forEach(([x,y]) => {
    const c = document.createElementNS(svgns, 'circle');
    c.setAttribute('cx', x); c.setAttribute('cy', y); c.setAttribute('r', '7');
    c.setAttribute('fill', color);
    c.setAttribute('pointer-events', 'none');
    rulerOverlay.appendChild(c);
  });

  // Label group — clickable for delete
  const distPx = len;
  let text = formatLen(distPx);
  const lx = (m.x1 + m.x2) / 2 + nx * (extLen + 20);
  const ly = (m.y1 + m.y2) / 2 + ny * (extLen + 20);
  const angle = Math.atan2(dy, dx) * 180 / Math.PI;
  const readableAngle = (angle > 90 || angle < -90) ? angle + 180 : angle;
  const pW = text.length * 15 + (isPreview ? 20 : 60);

  const g = document.createElementNS(svgns, 'g');
  g.setAttribute('transform', `rotate(${readableAngle} ${lx} ${ly})`);

  const bg = document.createElementNS(svgns, 'rect');
  bg.setAttribute('x', lx - pW/2); bg.setAttribute('y', ly - 18);
  bg.setAttribute('width', pW); bg.setAttribute('height', 34);
  bg.setAttribute('rx', 5);
  bg.setAttribute('fill', isPreview ? '#a02835' : '#1d4ed8');
  bg.setAttribute('pointer-events', isPreview ? 'none' : 'auto');
  if (!isPreview && typeof mIndex === 'number') bg.dataset.measureIdx = String(mIndex);
  if (!isPreview) {
    bg.style.cursor = 'pointer';
    bg.addEventListener('pointerdown', (e) => { e.stopPropagation(); e.preventDefault(); deleteMeasurement(mIndex); });
  }
  g.appendChild(bg);

  const lbl = document.createElementNS(svgns, 'text');
  lbl.setAttribute('x', lx - (isPreview ? 0 : 14)); lbl.setAttribute('y', ly + 6);
  lbl.setAttribute('text-anchor', 'middle');
  lbl.setAttribute('fill', 'white');
  lbl.setAttribute('font-family', 'JetBrains Mono,monospace');
  lbl.setAttribute('font-weight', '600');
  lbl.setAttribute('font-size', '19');
  lbl.setAttribute('pointer-events', 'none');
  lbl.textContent = text;
  g.appendChild(lbl);

  if (!isPreview && typeof mIndex === 'number') {
    const xHit = document.createElementNS(svgns, 'circle');
    xHit.setAttribute('cx', lx + pW/2 - 18);
    xHit.setAttribute('cy', ly);
    xHit.setAttribute('r', '16');
    xHit.setAttribute('fill', 'transparent');
    xHit.setAttribute('pointer-events', 'auto');
    xHit.dataset.measureIdx = String(mIndex);
    xHit.style.cursor = 'pointer';
    xHit.addEventListener('pointerdown', (e) => { e.stopPropagation(); e.preventDefault(); deleteMeasurement(mIndex); });
    g.appendChild(xHit);
    const xBtn = document.createElementNS(svgns, 'text');
    xBtn.setAttribute('x', lx + pW/2 - 18); xBtn.setAttribute('y', ly + 8);
    xBtn.setAttribute('text-anchor', 'middle');
    xBtn.setAttribute('fill', 'rgba(255,255,255,0.8)');
    xBtn.setAttribute('font-size', '26');
    xBtn.setAttribute('font-family', 'sans-serif');
    xBtn.setAttribute('pointer-events', 'none');
    xBtn.textContent = '×';
    g.appendChild(xBtn);
  }
  rulerOverlay.appendChild(g);
}

function addAreaSVG(m, mIndex) {
  const svgns = 'http://www.w3.org/2000/svg';
  if (!m.points || m.points.length < 3) return;
  const fill = document.createElementNS(svgns, 'polygon');
  fill.setAttribute('points', m.points.map(p => `${p.x},${p.y}`).join(' '));
  fill.setAttribute('class', 'area-fill');
  fill.setAttribute('pointer-events', 'none');
  rulerOverlay.appendChild(fill);
  for (let i = 0; i < m.points.length; i++) {
    const j = (i+1) % m.points.length;
    const l = document.createElementNS(svgns, 'line');
    l.setAttribute('x1', m.points[i].x); l.setAttribute('y1', m.points[i].y);
    l.setAttribute('x2', m.points[j].x); l.setAttribute('y2', m.points[j].y);
    l.setAttribute('class', 'area-edge');
    l.setAttribute('pointer-events', 'none');
    rulerOverlay.appendChild(l);
  }
  const cx = m.points.reduce((s, p) => s + p.x, 0) / m.points.length;
  const cy = m.points.reduce((s, p) => s + p.y, 0) / m.points.length;
  const liveLabel = formatArea(shoelaceArea(m.points));
  const display = (m.name ? m.name + ' · ' : '') + liveLabel + (m.void ? '  (void)' : '');
  const pW = display.length * 11 + 50;
  const bg = document.createElementNS(svgns, 'rect');
  bg.setAttribute('x', cx - pW/2); bg.setAttribute('y', cy - 20);
  bg.setAttribute('width', pW); bg.setAttribute('height', 34);
  bg.setAttribute('rx', 6); bg.setAttribute('fill', m.void ? '#6b7280' : '#15803d');
  bg.setAttribute('pointer-events', 'auto');
  bg.dataset.measureIdx = String(mIndex);
  bg.style.cursor = 'pointer';
  bg.addEventListener('pointerdown', (e) => { e.stopPropagation(); e.preventDefault(); deleteMeasurement(mIndex); });
  rulerOverlay.appendChild(bg);
  const txt = document.createElementNS(svgns, 'text');
  txt.setAttribute('x', cx - 14); txt.setAttribute('y', cy + 3);
  txt.setAttribute('text-anchor', 'middle'); txt.setAttribute('fill', 'white');
  txt.setAttribute('font-family', 'JetBrains Mono,monospace');
  txt.setAttribute('font-weight', '600'); txt.setAttribute('font-size', '17');
  txt.setAttribute('pointer-events', 'none');
  txt.textContent = display;
  rulerOverlay.appendChild(txt);
  const xHit = document.createElementNS(svgns, 'circle');
  xHit.setAttribute('cx', cx + pW/2 - 18);
  xHit.setAttribute('cy', cy);
  xHit.setAttribute('r', '16');
  xHit.setAttribute('fill', 'transparent');
  xHit.setAttribute('pointer-events', 'auto');
  xHit.dataset.measureIdx = String(mIndex);
  xHit.style.cursor = 'pointer';
  xHit.addEventListener('pointerdown', (e) => { e.stopPropagation(); e.preventDefault(); deleteMeasurement(mIndex); });
  rulerOverlay.appendChild(xHit);
  const xBtn = document.createElementNS(svgns, 'text');
  xBtn.setAttribute('x', cx + pW/2 - 18); xBtn.setAttribute('y', cy + 6);
  xBtn.setAttribute('fill', 'rgba(255,255,255,0.8)');
  xBtn.setAttribute('font-size', '26'); xBtn.setAttribute('font-family', 'sans-serif');
  xBtn.setAttribute('pointer-events', 'none');
  xBtn.textContent = '×';
  rulerOverlay.appendChild(xBtn);
}

