    if (fmat && fmat.kind === 'color' && !f.selected) { const c = hexToRgba(fmat.hex); base = [c[0], c[1], c[2]]; }
    if (f.interior && !f.selected) { base = [150, 142, 132]; shade = 0.46; }   // recessed reveal — fixed dim
