      if (f.mat.kind === 'texture') { const pat = regionPattern(f.mat); if (pat) fillStyle = pat; }
      else { const tr = matFill(f.mat); if (tr) fillStyle = tr; else if (f.mat.kind === 'color') { const c = hexToRgba(f.mat.hex); fillStyle = `rgb(${Math.round(c[0] * shade)},${Math.round(c[1] * shade)},${Math.round(c[2] * shade)})`; } }
