// ---- base 2D drawing projected onto the ground plane ----
let _massBaseCanvas = null;
function buildMassingBase() {
  if (!_massBaseCanvas) _massBaseCanvas = document.createElement('canvas');
  _massBaseCanvas.width = DOC_W_PX; _massBaseCanvas.height = DOC_H_PX;
  flattenVisibleToCtx(_massBaseCanvas.getContext('2d'));
  massing.baseImg = _massBaseCanvas;
}
// doc pixel → world (anchored so the extruded footprint sits over its plan) → screen
