// ===== Polygon offset (shared by the 2D Offset tool + 3D footprint offset) =====
function _offArea(pts){ let a=0; for(let i=0;i<pts.length;i++){const p=pts[i],q=pts[(i+1)%pts.length]; a+=p.x*q.y-q.x*p.y;} return a/2; }
