    const sh=state.shapes[state.offset.idx]; if(!sh) return null;
    if(sh.kind==='ellipse'){ const rx=sh.rx+d, ry=sh.ry+d; if(rx<=1||ry<=1) return null; return {ellipse:true,cx:sh.cx,cy:sh.cy,rx,ry}; }
