    { x: a2.x + px * h, z: a2.z + pz * h }, { x: b2.x + px * h, z: b2.z + pz * h },
    { x: b2.x - px * h, z: b2.z - pz * h }, { x: a2.x - px * h, z: a2.z - pz * h }
