function updateBuildPalette() {
  const show = massing.active && massing.tool === 'build';
  if (show) { buildBuildPalette(); ensureWallPalette().style.display = 'flex'; }
  else if (_wallPaletteEl) { _wallPaletteEl.style.display = 'none'; massing.selOpening = null; if (massing.wall) finishWall(); }
}

// ---- the floating Fill · Extrude chip ----
let _shapeChipEl = null;
function ensureShapeChip() {
  if (_shapeChipEl) return _shapeChipEl;
  const style = document.createElement('style');
  style.textContent =
    '#shape-chip{position:fixed;z-index:9999;display:none;gap:6px;padding:5px;background:rgba(20,20,22,0.94);' +
    'border:1px solid rgba(255,255,255,0.12);border-radius:11px;box-shadow:0 8px 24px rgba(0,0,0,0.4);backdrop-filter:blur(6px);}' +
    '#shape-chip button{font:600 12px/1 ui-sans-serif,system-ui,sans-serif;color:#fff;border:none;border-radius:7px;' +
    'padding:9px 15px;cursor:pointer;letter-spacing:.02em;}' +
    '#shape-chip button[data-act="fill"]{background:#2c2c33;}' +
    '#shape-chip button[data-act="extrude"]{background:#a02835;}' +
    '#shape-chip button:active{transform:scale(0.96);}';
  document.head.appendChild(style);
  const el = document.createElement('div');
  el.id = 'shape-chip';
  el.innerHTML = '<button data-act="fill">Fill</button><button data-act="extrude">Extrude</button>';
  document.body.appendChild(el);
  el.addEventListener('pointerdown', ev => ev.stopPropagation());
  el.addEventListener('click', ev => {
    const act = ev.target && ev.target.dataset && ev.target.dataset.act;
    if (!act) return;
    const geom = state._lastShape;
    if (!geom) { hideShapeChip(); return; }
    if (act === 'fill') { fillShape(geom); }           // keep chip so Extrude is still offered
    else if (act === 'extrude') { hideShapeChip(); extrudeShape(geom); }
  });
  _shapeChipEl = el;
  return el;
}
function showShapeChip(geom, screenPt) {
  const el = ensureShapeChip();
  state._lastShape = geom;
  el.style.display = 'flex';
  const r = el.getBoundingClientRect();
  const px = screenPt ? screenPt.x : window.innerWidth / 2;
  const py = screenPt ? screenPt.y : window.innerHeight / 2;
  let left = px - r.width / 2, top = py - r.height - 18;
  left = Math.max(8, Math.min(window.innerWidth - r.width - 8, left));
  top = Math.max(8, Math.min(window.innerHeight - r.height - 8, top));
  el.style.left = left + 'px';
  el.style.top = top + 'px';
}
function hideShapeChip() { if (_shapeChipEl) _shapeChipEl.style.display = 'none'; }

// Called from shape-commit paths (rect/circle on pointerup, polygon on close).
function onShapeCommitted(geom, screenPt) {
  if (!geom) return;
  state._lastShapeFill = null;
  showShapeChip(geom, screenPt);
}

// ---- enter / exit ----
// ---- massing undo / redo (snapshots the masses, independent of the 2D pixel history) ----
function massState() {
  // Drop only non-serializable cached images (not semantic flags like _wall / _opening / _host).
  const skipCache = (k, v) => {
    if (typeof v === 'function') return undefined;
    if (typeof HTMLImageElement !== 'undefined' && v instanceof HTMLImageElement) return undefined;
    if (typeof HTMLCanvasElement !== 'undefined' && v instanceof HTMLCanvasElement) return undefined;
    if (typeof ImageBitmap !== 'undefined' && v instanceof ImageBitmap) return undefined;
    return v;
  };
  return {
    masses: JSON.parse(JSON.stringify(massing.masses, skipCache)),
    selected: massing.selected,
    anchor: massing.baseAnchor ? { ...massing.baseAnchor } : null,
  };
}
function massApply(s) {
  massing.masses = JSON.parse(JSON.stringify(s.masses));
  massing.selected = s.selected;
  massing.baseAnchor = s.anchor ? { ...s.anchor } : null;
}
function massSnapshot() {
  massing.undoStack.push(massState());
  if (massing.undoStack.length > 60) massing.undoStack.shift();
  massing.redoStack = [];
  if (typeof scheduleMassAutosave === 'function') scheduleMassAutosave();   // 3D edits persist quickly
}
function massUndo() {
  if (!massing.undoStack.length) { massHint('Nothing to undo'); return; }
  massing.redoStack.push(massState());
  massApply(massing.undoStack.pop());
  renderMassing();
  refreshInspector();
  massHint('Undo');
}
function massRedo() {
  if (!massing.redoStack.length) { massHint('Nothing to redo'); return; }
  massing.undoStack.push(massState());
  massApply(massing.redoStack.pop());
  renderMassing();
  refreshInspector();
  massHint('Redo');
}
// ---- numeric inspector for the selected mass ----
const massInspector = document.getElementById('mass-inspector');
let _inspBefore = null;
function refreshInspector() {
  const b = (massing.selected >= 0) ? massing.masses[massing.selected] : null;
  const show = b && massing.active && (window.StudioHelpers
    ? StudioHelpers.shouldShowMassInspector(massing)
    : ['select', 'move', 'height', 'push', 'material'].includes(massing.tool));
  if (!show) { massInspector.style.display = 'none'; return; }
  massInspector.style.display = 'flex';
  document.getElementById('insp-h').value = (+b.h).toFixed(1);
  document.getElementById('insp-base').value = (+(b.baseY || 0)).toFixed(1);
  document.getElementById('insp-rot').value = Math.round((b.rot || 0) * 180 / Math.PI);
  document.getElementById('insp-fscale').value = Math.round((b.fsx != null ? b.fsx : (b.fscale != null ? b.fscale : 1)) * 100);
  document.getElementById('insp-taper').value = Math.round((b.taper != null ? b.taper : 1) * 100);
}
function _inspApply() {
  const b = (massing.selected >= 0) ? massing.masses[massing.selected] : null;
  if (!b) return;
  const h = parseFloat(document.getElementById('insp-h').value);
  const base = parseFloat(document.getElementById('insp-base').value);
  const rot = parseFloat(document.getElementById('insp-rot').value);
  const fs = parseFloat(document.getElementById('insp-fscale').value);
  const tp = parseFloat(document.getElementById('insp-taper').value);
  if (!isNaN(h)) b.h = Math.max(0.1, h);
  if (!isNaN(base)) b.baseY = Math.max(0, base);
  if (!isNaN(rot)) b.rot = rot * Math.PI / 180;
  if (!isNaN(fs)) { b.fsx = Math.max(0.1, fs / 100); b.fsz = Math.max(0.1, fs / 100); delete b.fscale; }
  if (!isNaN(tp)) b.taper = Math.max(0.05, tp / 100);
  renderMassing();
}
['insp-h','insp-base','insp-rot','insp-fscale','insp-taper'].forEach(id => {
  const el = document.getElementById(id);
  el.addEventListener('focus', () => { _inspBefore = massState(); });
  el.addEventListener('input', _inspApply);
  el.addEventListener('change', () => {
    if (_inspBefore) { massing.undoStack.push(_inspBefore); if (massing.undoStack.length > 60) massing.undoStack.shift(); massing.redoStack = []; _inspBefore = null; }
  });
});

function duplicateMass() {
  if (massing.selected < 0 || !massing.masses[massing.selected]) { massHint('Select a mass first (Move-tap), then Duplicate'); return; }
  massSnapshot();
  const copy = JSON.parse(JSON.stringify(massing.masses[massing.selected]));
  const off = 2;   // 2 m offset so the copy is visible
  if (copy.poly) copy.poly = copy.poly.map(p => ({ x: p.x + off, z: p.z + off }));
  else { copy.x += off; copy.z += off; }
  massing.masses.push(copy);
  massing.selected = massing.masses.length - 1;
  renderMassing();
  refreshInspector();
  massHint('Duplicated · Move to reposition');
}
function deleteSelectedMass() {
  if (massing.selected < 0 || !massing.masses[massing.selected]) { massHint('Select a mass first (Move-tap), then Delete'); return; }
  massSnapshot();
  massing.masses.splice(massing.selected, 1);
  massing.selected = -1;
  if (massing.masses.length === 0) massing.baseAnchor = null;
  renderMassing();
  refreshInspector();
  massHint('Deleted');
}

function enterMassing() {
  dismissSketchOverlays();
  releaseTransientInput();
  state.tool = 'massing';
  massing.active = true;
  if (!massing.baseAnchor) massing.baseAnchor = { px: DOC_W_PX / 2, py: DOC_H_PX / 2, ppm: pxPerMetre() };
  syncWallsToMasses();             // bring 2D walls into the 3D model
  buildMassingBase();              // always reflect the current 2D drawing
  massingCanvas.style.display = 'block';
  massingBar.style.display = 'flex';
  updateMassBaseBtn();
  if (massing.cam.scale === 1) {
    // first run: sensible default zoom relative to viewport
    const r = area.getBoundingClientRect();
    massing.cam.scale = Math.min(r.width, r.height) / 26;
  }
  massHint('Add: drag a footprint on the ground, then use Height');
  renderMassing();
  updateZoomDisplay();
  highlightRailGroups();
  syncMassToolButtons();
}
function exitMassing() {
  massing.active = false;
  massing.dragging = null;
  massing.selected = -1;
  if (window._closeMassMenus) window._closeMassMenus();
  if (typeof updateMatPalette === 'function') updateMatPalette();
  if (typeof updateBuildPalette === 'function') updateBuildPalette();
  document.getElementById('mass-inspector').style.display = 'none';
  massingCanvas.style.display = 'none';
  massingBar.style.display = 'none';
  massHint('');
  initGrainTips();
  regroupRail();
  setTool('pen');
}

// ---- flatten current masses onto a new 2D layer, ALIGNED to the plan ----
// Top-down commit: each footprint is drawn at its exact original document location
// (no orbit lean), with a height tag — i.e. a true plan outline locked to your drawing.
function drawMassingAligned(ctx) {
  const A = massing.baseAnchor || { px: DOC_W_PX / 2, py: DOC_H_PX / 2, ppm: pxPerMetre() };
  massing.masses.forEach(b => {
    const foot = massBaseTop(b).base;
    const pts = foot.map(p => ({ x: A.px + p.x * A.ppm, y: A.py + p.z * A.ppm }));
    ctx.beginPath();
    ctx.moveTo(pts[0].x, pts[0].y);
    for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
    ctx.closePath();
    ctx.fillStyle = 'rgba(160,40,53,0.10)';
    ctx.fill();
    ctx.lineJoin = 'round';
    ctx.strokeStyle = 'rgba(34,30,28,0.92)';
    ctx.lineWidth = 3;
    ctx.stroke();
    // roof sketch, mapped onto the footprint (clipped to the plan outline)
    if (b.faceArt && b.faceArt.top) {
      ensureFaceImg(b);
      const g = faceGeom(b, 'top', 'base');
      const dp = p => ({ x: A.px + p.x * A.ppm, y: A.py + p.z * A.ppm });
      drawFaceArt(ctx, g.quad, b._faceImg.top, g.clip, dp);
    }
    let cx = 0, cy = 0; pts.forEach(p => { cx += p.x; cy += p.y; }); cx /= pts.length; cy /= pts.length;
    ctx.fillStyle = 'rgba(34,30,28,0.85)';
    ctx.font = '600 30px ui-monospace, monospace';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(`${b.h.toFixed(1)} m`, cx, cy);
  });
}

function flattenMassingToLayer() {
  if (!massing.masses.length) { showHint('Add some masses first'); return; }
  const tmp = document.createElement('canvas');
  tmp.width = DOC_W_PX; tmp.height = DOC_H_PX;
  drawMassingAligned(tmp.getContext('2d'));
  createLayer('Massing plan');
  const layer = state.layers[state.layers.length - 1];
  state.activeLayer = state.layers.length - 1;
  layer.ctx.drawImage(tmp, 0, 0);
  saveSnapshot(layer);
  updateLayerOrder(); renderLayers(); updateUI();
  massHint('Plan added on a new layer · Exit when done');
}

// Export the current angled 3D view (plan-on-ground + masses) onto a new 2D layer.
function exportAngledView() {
  if (!massing.masses.length) { showHint('Add some masses first'); return; }
  massing._export = true; renderMassing();          // transparent, no grid
  const src = massingCanvas;
  const tmp = document.createElement('canvas');
  tmp.width = DOC_W_PX; tmp.height = DOC_H_PX;
  const scale = Math.min(DOC_W_PX / src.width, DOC_H_PX / src.height) * 0.94;
  const dw = src.width * scale, dh = src.height * scale;
  tmp.getContext('2d').drawImage(src, (DOC_W_PX - dw) / 2, (DOC_H_PX - dh) / 2, dw, dh);
  massing._export = false; renderMassing();
  createLayer('3D view');
  const layer = state.layers[state.layers.length - 1];
  state.activeLayer = state.layers.length - 1;
  layer.ctx.drawImage(tmp, 0, 0);
  saveSnapshot(layer);
  updateLayerOrder(); renderLayers(); updateUI();
  massHint('3D view added on a new layer · Exit when done');
}

// Render all masses head-on (el=0) for a given azimuth into a target, world y=0 at groundY.
function drawElevationInto(ctx, az, scale, ox, groundY) {
  const proj = p => { const q = mRotY(p, az); return { x: ox + q.x * scale, y: groundY - q.y * scale, depth: q.z }; };
  const faces = [];
  massing.masses.forEach(b => {
    const vs = massVerts(b).map(proj);
    massFaces(b).forEach(f => {
      let d = 0; for (const i of f.idx) d += vs[i].depth; d /= f.idx.length;
      faces.push({ b, id: f.id, pts: f.idx.map(i => vs[i]), n: f.n, depth: d });
    });
  });
  faces.sort((a, b) => a.depth - b.depth);
  faces.forEach(f => {
    ctx.beginPath(); ctx.moveTo(f.pts[0].x, f.pts[0].y);
    for (let i = 1; i < f.pts.length; i++) ctx.lineTo(f.pts[i].x, f.pts[i].y);
    ctx.closePath();
    ctx.fillStyle = 'rgba(236,232,226,0.95)'; ctx.fill();
    ctx.lineJoin = 'round'; ctx.strokeStyle = 'rgba(26,23,21,0.92)'; ctx.lineWidth = 2; ctx.stroke();
    if (f.b.faceArt && f.b.faceArt[f.id]) {
      ensureFaceImg(f.b);
      const g = faceGeom(f.b, f.id);
      drawFaceArt(ctx, g.quad, f.b._faceImg[f.id], g.clip, proj);
    }
  });
}

// Generate a 2×2 elevation sheet (Front/Right/Back/Left) at a consistent scale.
function generateElevations() {
  if (!massing.masses.length) { showHint('Add some masses first'); return; }
  const views = [
    { a: 0, label: 'FRONT (S)' }, { a: Math.PI / 2, label: 'RIGHT (E)' },
    { a: Math.PI, label: 'BACK (N)' }, { a: -Math.PI / 2, label: 'LEFT (W)' },
  ];
  let gW = 0, gH = 0;
  const measured = views.map(o => {
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    massing.masses.forEach(b => massVerts(b).forEach(p => {
      const q = mRotY(p, o.a);
      if (q.x < minX) minX = q.x; if (q.x > maxX) maxX = q.x;
      if (q.y < minY) minY = q.y; if (q.y > maxY) maxY = q.y;
    }));
    gW = Math.max(gW, maxX - minX); gH = Math.max(gH, maxY - minY);
    return { minX, maxX, maxY };
  });
  const pad = Math.min(DOC_W_PX, DOC_H_PX) * 0.06;
  const cellW = (DOC_W_PX - pad * 3) / 2;
  const cellH = (DOC_H_PX - pad * 3) / 2 - 44;     // room for label
  const fit = Math.min(cellW / (gW || 1), cellH / (gH || 1)) * 0.82;
  const tmp = document.createElement('canvas'); tmp.width = DOC_W_PX; tmp.height = DOC_H_PX;
  const ctx = tmp.getContext('2d');
  views.forEach((o, i) => {
    const col = i % 2, row = (i / 2) | 0;
    const cx0 = pad + col * (cellW + pad), cy0 = pad + row * (cellH + pad + 44);
    const m = measured[i];
    const midX = (m.minX + m.maxX) / 2;
    const ox = cx0 + cellW / 2 - midX * fit;
    const groundY = cy0 + cellH - cellH * 0.08;
    drawElevationInto(ctx, o.a, fit, ox, groundY);
    ctx.fillStyle = 'rgba(34,30,28,0.82)';
    ctx.font = '600 26px ui-monospace, monospace';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(o.label, cx0 + cellW / 2, cy0 + cellH + 22);
  });
  createLayer('Elevations');
  const layer = state.layers[state.layers.length - 1];
  state.activeLayer = state.layers.length - 1;
  layer.ctx.drawImage(tmp, 0, 0);
  saveSnapshot(layer);
  updateLayerOrder(); renderLayers(); updateUI();
  massHint('Elevations added on a new layer · Exit when done');
}

// Render massing to an arbitrary ctx (used for flatten). bg=false → transparent.
function drawMassingTo(ctx, W, H, bg) {
  const saveCx = massing.cx, saveCy = massing.cy;
  massing.cx = W/2; massing.cy = H*0.58;
  if (bg) { ctx.fillStyle = '#e9e5e0'; ctx.fillRect(0,0,W,H); }
  const faces = [];
  massing.masses.forEach((b, bi) => {
    const vs = massVerts(b).map(mProject);
    const cull = false;   // all masses are polygonal — depth-sort only
    massFaces(b).forEach(f => {
      const p0=vs[f.idx[0]], p1=vs[f.idx[1]], p2=vs[f.idx[2]];
      const cross=(p1.x-p0.x)*(p2.y-p0.y)-(p1.y-p0.y)*(p2.x-p0.x);
      if (cull && cross<=0) return;
      let depth=0; for (const i of f.idx) depth += vs[i].depth; depth /= f.idx.length;
      faces.push({ pts:f.idx.map(i=>vs[i]), n:f.n, depth });
    });
  });
  faces.sort((a,b)=>a.depth-b.depth);
  const L=[-0.4,0.82,0.4];
  faces.forEach(f=>{
    const ndl=Math.max(0,f.n[0]*L[0]+f.n[1]*L[1]+f.n[2]*L[2]);
    const shade=0.6+ndl*0.4;
    const base=[236,232,226];
    const r=Math.round(base[0]*shade),g=Math.round(base[1]*shade),bl=Math.round(base[2]*shade);
    ctx.beginPath(); ctx.moveTo(f.pts[0].x,f.pts[0].y);
    for(let i=1;i<f.pts.length;i++) ctx.lineTo(f.pts[i].x,f.pts[i].y);
    ctx.closePath();
    ctx.fillStyle=`rgb(${r},${g},${bl})`; ctx.fill();
    ctx.lineJoin='round'; ctx.strokeStyle='rgba(20,18,16,0.9)'; ctx.lineWidth=2; ctx.stroke();
  });
  massing.cx = saveCx; massing.cy = saveCy;
}

