(function () {
  const vMenu = document.getElementById('mass-view-menu'), eMenu = document.getElementById('mass-export-menu');
  const vPop = document.getElementById('mass-view-pop'), ePop = document.getElementById('mass-export-pop');
  function closeMassMenus() { vPop.style.display = 'none'; ePop.style.display = 'none'; vMenu.classList.remove('active'); eMenu.classList.remove('active'); }
  function toggle(pop, menu) { const open = pop.style.display !== 'none'; closeMassMenus(); if (!open) { pop.style.display = 'flex'; menu.classList.add('active'); } }
  vMenu.addEventListener('click', e => { e.stopPropagation(); toggle(vPop, vMenu); });
  eMenu.addEventListener('click', e => { e.stopPropagation(); toggle(ePop, eMenu); });
  ['mass-flatten','mass-elev','mass-view'].forEach(id => document.getElementById(id).addEventListener('click', closeMassMenus));
  document.addEventListener('pointerdown', e => { const t = e.target; if (!(t instanceof Element) || !t.closest('#mass-view-pop,#mass-export-pop,#mass-view-menu,#mass-export-menu')) closeMassMenus(); });
  window._closeMassMenus = closeMassMenus;
})();

// ---- face sketch editor ----
const faceEd = { bi: -1, id: null, tool: 'pen', color: '#1c1a18', size: 4, drawing: false, last: null, ctx: null, regionPts: [], guide: null, grid: false, snap: false, pxm: 100, gridM: 0.25, fw: 1, fh: 1, openW: 1200, openH: 1500, openSill: 900 };
const feCanvas = document.getElementById('fe-canvas');
function openFaceEditor(bi, id) {
  const b = massing.masses[bi]; if (!b) return;
  const fg = faceGeom(b, id); if (!fg) return;
  let pxm = 100, wpx = Math.max(64, Math.round(fg.w * pxm)), hpx = Math.max(64, Math.round(fg.h * pxm));
  const cap = 1400, mx = Math.max(wpx, hpx);
  if (mx > cap) { const s = cap / mx; wpx = Math.round(wpx * s); hpx = Math.round(hpx * s); }
  feCanvas.width = wpx; feCanvas.height = hpx;
  const ctx = feCanvas.getContext('2d'); faceEd.ctx = ctx;
  ctx.clearRect(0, 0, wpx, hpx);                 // transparent — only ink maps back onto the face
  faceEd.guide = fg.guide || null;
  if (b.faceArt && b.faceArt[id]) { const im = new Image(); im.onload = () => ctx.drawImage(im, 0, 0, wpx, hpx); im.src = b.faceArt[id]; }
  faceEd.bi = bi; faceEd.id = id;
  faceEd.regionPts = [];
  faceEd.pxm = fg.w ? (wpx / fg.w) : 100;        // effective px per metre (after the size cap)
  faceEd.fw = fg.w || 1; faceEd.fh = fg.h || 1;
  faceEd.gridM = _niceGridM(fg.w || 1, fg.h || 1);
  const gbtn = document.getElementById('fe-grid'); if (gbtn) gbtn.classList.toggle('active', !!faceEd.grid);
  const sbtn = document.getElementById('fe-snap'); if (sbtn) sbtn.classList.toggle('active', !!faceEd.snap);
  const gmm = document.getElementById('fe-gridmm'); if (gmm) gmm.value = Math.round(faceEd.gridM * 1000);
  if (typeof _feSyncOpenFields === 'function') _feSyncOpenFields();
  const regs0 = b.faceRegions && b.faceRegions[id];
  const fd = document.getElementById('fe-depth'); if (fd) fd.value = (regs0 && regs0.length) ? (regs0[regs0.length - 1].depth || 0) : 0;
  // overlay: boundary guide + any committed face regions + in-progress region
  feRedrawOverlay();
  document.getElementById('fe-label').textContent = faceLabel(id).toUpperCase();
  document.getElementById('face-editor').style.display = 'flex';
}
function feClose() { document.getElementById('face-editor').style.display = 'none'; faceEd.bi = -1; faceEd.id = null; faceEd.drawing = false; faceEd.regionPts = []; }
function fePos(e) { const r = feCanvas.getBoundingClientRect(); return { x: (e.clientX - r.left) * (feCanvas.width / r.width), y: (e.clientY - r.top) * (feCanvas.height / r.height) }; }
feCanvas.addEventListener('pointerdown', e => {
  e.preventDefault();
  if (faceEd.tool === 'window' || faceEd.tool === 'door') {
    const p = _feSnap(fePos(e));
    feCommitOpening(p.x / feCanvas.width);
    return;
  }
  if (faceEd.tool === 'region') {
    const p = _feSnap(fePos(e)), pts = faceEd.regionPts || (faceEd.regionPts = []);
    if (pts.length >= 3 && Math.hypot(p.x - pts[0].x, p.y - pts[0].y) < 14) { feCommitRegion(); return; }
    pts.push(p); feRedrawOverlay(); return;
  }
  feCanvas.setPointerCapture(e.pointerId); faceEd.drawing = true; faceEd.last = fePos(e);
});
feCanvas.addEventListener('pointermove', e => {
  if (faceEd.tool === 'region' || !faceEd.drawing) return;
  const p = fePos(e), ctx = faceEd.ctx;
  ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.lineWidth = faceEd.size;
  if (faceEd.tool === 'erase') { ctx.globalCompositeOperation = 'destination-out'; ctx.strokeStyle = 'rgba(0,0,0,1)'; }
  else { ctx.globalCompositeOperation = 'source-over'; ctx.strokeStyle = faceEd.color; }
  ctx.beginPath(); ctx.moveTo(faceEd.last.x, faceEd.last.y); ctx.lineTo(p.x, p.y); ctx.stroke();
  ctx.globalCompositeOperation = 'source-over';
  faceEd.last = p;
});

// place a parametric door/window as a recessed region (reuses the recess kernel + materials)
function feCommitOpening(uCenter) {
  const b = massing.masses[faceEd.bi]; if (!b) return;
  const kind = faceEd.tool;                                  // 'window' | 'door'
  const W = faceEd.fw || 1, H = faceEd.fh || 1;              // face dims (metres)
  if (W <= 0.05 || H <= 0.05) { if (typeof massHint === 'function') massHint('Face too small for an opening'); return; }
  let w = Math.max(0.1, (faceEd.openW || 1200) / 1000), h = Math.max(0.1, (faceEd.openH || 1500) / 1000);
  let sill = Math.max(0, (faceEd.openSill || 0) / 1000);
  const fitted = (w > W * 0.92) || (h > H * 0.92) || (sill + h > H);   // clamp to the face — never silently reject
  w = Math.min(w, W * 0.92); h = Math.min(h, H * 0.92);
  if (sill + h > H) sill = Math.max(0, H - h);
  let uL = uCenter - (w / 2) / W, uR = uCenter + (w / 2) / W;
  if (uL < 0) { uR -= uL; uL = 0; } if (uR > 1) { uL -= (uR - 1); uR = 1; }   // keep within the face width
  uL = Math.max(0, uL); uR = Math.min(1, uR);
  const vBot = 1 - sill / H, vTop = 1 - (sill + h) / H;       // v=0 top, v=1 bottom
  const uv = [{ u: uL, v: vTop }, { u: uR, v: vTop }, { u: uR, v: vBot }, { u: uL, v: vBot }];
  const mat = kind === 'window'
    ? { kind: 'color', hex: '#7d97a8', id: 'glass', glass: true }   // translucent glazing
    : { kind: 'color', hex: '#3a3330', id: 'door' };                // recessed panel
  massSnapshot();
  b.faceRegions = b.faceRegions || {}; b.faceRegions[faceEd.id] = b.faceRegions[faceEd.id] || [];
  b.faceRegions[faceEd.id].push({ uv, depth: -100, mat, opening: kind });   // ~100mm reveal; tweak via Pull
  feRedrawOverlay(); renderMassing();
  if (typeof massHint === 'function') massHint((kind === 'window' ? 'Window placed' : 'Door placed') + (fitted ? ' \u2014 fitted to face' : ' \u2014 adjust depth with Pull'));
}
function feCommitRegion() {
  const b = massing.masses[faceEd.bi];
  if (!b || !faceEd.regionPts || faceEd.regionPts.length < 3) { faceEd.regionPts = []; feRedrawOverlay(); return; }
  massSnapshot();
  b.faceRegions = b.faceRegions || {};
  b.faceRegions[faceEd.id] = b.faceRegions[faceEd.id] || [];
  b.faceRegions[faceEd.id].push({ uv: faceEd.regionPts.map(p => ({ u: p.x / feCanvas.width, v: p.y / feCanvas.height })) });
  faceEd.regionPts = [];
  feRedrawOverlay(); renderMassing();
  if (typeof massHint === 'function') massHint('Region added \u2014 it now maps onto the face in 3D');
}
function _niceGridM(w, h) {
  const big = Math.max(w, h) || 1, target = big / 12;
  const steps = [0.05, 0.1, 0.2, 0.25, 0.5, 1, 2, 5];
  for (const s of steps) if (s >= target) return s;
  return steps[steps.length - 1];
}
function _feSnap(p) {
  if (!faceEd.snap || !faceEd.pxm || !faceEd.gridM) return p;
  const step = faceEd.gridM * faceEd.pxm;
  return { x: Math.round(p.x / step) * step, y: Math.round(p.y / step) * step };
}
// Existing holes on this face, in UV: recessed regions + door/window openings (which cut side0/side2).
function facePunctures(b, faceId) {
  const out = [];
  const regs = b.faceRegions && b.faceRegions[faceId];
  if (regs) regs.forEach(r => { if ((r.depth || 0) < 0 && r.uv && r.uv.length >= 3) out.push(r.uv.map(p => ({ u: p.u, v: p.v }))); });
  if ((faceId === 'side0' || faceId === 'side2') && b.openings && b.h) {
    const L = faceEd.fw || 1, H = b.h;
    b.openings.forEach(op => {
      const halfU = (op.w / 2) / L;
      let uc = op.u; if (faceId === 'side2') uc = 1 - uc;
      const uL = uc - halfU, uR = uc + halfU;
      const sill = op.kind === 'door' ? 0 : (op.sill || 0);
      const vBot = 1 - sill / H, vTop = 1 - (sill + op.h) / H;
      out.push([{ u: uL, v: vTop }, { u: uR, v: vTop }, { u: uR, v: vBot }, { u: uL, v: vBot }]);
    });
  }
  return out;
}
function feRedrawOverlay() {
  const gv = document.getElementById('fe-guide'); if (!gv) return;
  gv.style.display = 'block'; gv.width = feCanvas.width; gv.height = feCanvas.height;
  const gx = gv.getContext('2d'); gx.clearRect(0, 0, gv.width, gv.height);
  // snap grid (under everything)
  if (faceEd.grid && faceEd.pxm && faceEd.gridM) {
    const step = faceEd.gridM * faceEd.pxm;
    if (step >= 4) {
      gx.strokeStyle = 'rgba(160,40,53,0.13)'; gx.lineWidth = 1; gx.setLineDash([]);
      gx.beginPath();
      for (let x = 0; x <= gv.width + 0.5; x += step) { gx.moveTo(x, 0); gx.lineTo(x, gv.height); }
      for (let y = 0; y <= gv.height + 0.5; y += step) { gx.moveTo(0, y); gx.lineTo(gv.width, y); }
      gx.stroke();
    }
  }
  if (faceEd.guide) {
    gx.strokeStyle = 'rgba(160,40,53,0.5)'; gx.setLineDash([8, 6]); gx.lineWidth = 2;
    gx.beginPath(); faceEd.guide.forEach((p, k) => { const X = p.x * gv.width, Y = p.y * gv.height; k ? gx.lineTo(X, Y) : gx.moveTo(X, Y); }); gx.closePath(); gx.stroke();
  }
  gx.setLineDash([]);
  const b = massing.masses[faceEd.bi];
  // existing punctures (openings / recesses) — drawn as hatched voids so you sketch around them
  if (b) {
    const punc = facePunctures(b, faceEd.id);
    punc.forEach(poly => {
      gx.save();
      gx.beginPath(); poly.forEach((p, k) => { const X = p.u * gv.width, Y = p.v * gv.height; k ? gx.lineTo(X, Y) : gx.moveTo(X, Y); }); gx.closePath();
      gx.fillStyle = 'rgba(28,26,24,0.16)'; gx.fill();
      gx.strokeStyle = 'rgba(28,26,24,0.65)'; gx.setLineDash([5, 4]); gx.lineWidth = 1.5; gx.stroke();
      gx.clip(); gx.setLineDash([]); gx.strokeStyle = 'rgba(28,26,24,0.22)'; gx.lineWidth = 1;
      let mnx = 1e9, mny = 1e9, mxx = -1e9, mxy = -1e9;
      poly.forEach(p => { const X = p.u * gv.width, Y = p.v * gv.height; mnx = Math.min(mnx, X); mny = Math.min(mny, Y); mxx = Math.max(mxx, X); mxy = Math.max(mxy, Y); });
      gx.beginPath();
      for (let d = mny - (mxx - mnx); d <= mxy; d += 9) { gx.moveTo(mnx, d); gx.lineTo(mxx, d + (mxx - mnx)); }   // diagonal hatch
      gx.stroke();
      gx.restore();
    });
  }
  const regs = (b && b.faceRegions && b.faceRegions[faceEd.id]) || [];
  regs.forEach(r => {
    gx.beginPath(); r.uv.forEach((p, k) => { const X = p.u * gv.width, Y = p.v * gv.height; k ? gx.lineTo(X, Y) : gx.moveTo(X, Y); }); gx.closePath();
    gx.fillStyle = 'rgba(58,110,165,0.18)'; gx.fill(); gx.strokeStyle = '#3a6ea5'; gx.lineWidth = 2; gx.stroke();
  });
  const pts = faceEd.regionPts || [];
  if (pts.length) {
    gx.strokeStyle = '#a02835'; gx.lineWidth = 2; gx.beginPath();
    pts.forEach((p, k) => { k ? gx.lineTo(p.x, p.y) : gx.moveTo(p.x, p.y); }); gx.stroke();
    pts.forEach(p => { gx.fillStyle = '#a02835'; gx.beginPath(); gx.arc(p.x, p.y, 4, 0, 6.2832); gx.fill(); });
  }
}
