/* =================================================================
   KEYBOARD: add area tool + Escape to cancel polygon
   ================================================================= */

/* =================== KEYBOARD =================== */
window.addEventListener('keydown', (e) => {
  if (e.target.tagName === 'INPUT' || e.target.isContentEditable) return;
  if (e.key === 'Escape' && typeof hideShapeChip === 'function') hideShapeChip();
  if (e.key === 'Escape' && state.polyActive) {
    state.polyPoints = [];
    state.polyActive = false;
    document.getElementById('poly-hint').style.display = 'none';
    refreshMeasurements();
    return;
  }
  if ((e.metaKey || e.ctrlKey) && e.key === 'z') { e.preventDefault(); e.shiftKey ? redo() : undo(); }
  else if ((e.metaKey || e.ctrlKey) && e.key === 'y') { e.preventDefault(); redo(); }
  else if (e.key === 'p') setTool('pen');
  else if (e.key === 'm') setTool('marker');
  else if (e.key === 'b') setTool('brush');
  else if (e.key === 'w') setTool('watercolour');
  else if (e.key === 'l') setTool('pencil');
  else if (e.key === 'e') setTool('eraser');
  else if (e.key === 'r') setTool('ruler');
  else if (e.key === 'a') setTool('area');
  else if (e.key === 's') setTool('stencil');
  else if (e.key === 'h') setTool('hand');
  else if (e.key === 'i') setTool('brushes');
  else if (e.key === 'k') setTool('wall');
  else if (e.key === 'j') setTool('opening');
  else if (e.key === 'x') setTool('wand');
  else if (e.key === 'o') setTool('lasso');
  else if (e.key === 'f') setTool('fill');
  else if (e.key === 'g') document.getElementById('btn-grid').click();
  else if (e.key === '+' || e.key === '=') handleZoomIn();
  else if (e.key === '-') handleZoomOut();
  else if (e.key === '0') handleZoomFit();
});

/* =================================================================
   BRUSH CURSOR RING — live circle at stylus tip showing brush size
   ================================================================= */
const brushCursor = document.getElementById('brush-cursor');

function updateBrushCursor(e, brush) {
  if (!brushCursor) return;
  // Position in CSS pixels relative to canvas-area
  const areaRect = area.getBoundingClientRect();
  const cx = e.clientX - areaRect.left;
  const cy = e.clientY - areaRect.top;
  brushCursor.style.left = cx + 'px';
  brushCursor.style.top = cy + 'px';

  // Size in screen pixels = brush size in doc px × display scale
  const docToScreen = paper.getBoundingClientRect().width / DOC_W_PX;
  const pr = pressureFor(e);
  const b = brush || activeBrush();
  const effSize = Math.max(1, state.size * (1 - b.pressureSize + b.pressureSize * pr));
  const screenSize = Math.max(4, effSize * docToScreen * 2); // diameter
  brushCursor.style.width = screenSize + 'px';
  brushCursor.style.height = screenSize + 'px';
  brushCursor.style.borderColor = b.kind === 'erase'
    ? 'rgba(160,40,53,0.7)'
    : 'rgba(0,0,0,0.65)';
}

// Update cursor position on all pen moves, even when not drawing
area.addEventListener('pointermove', (e) => {
  if (e.pointerType !== 'pen' && e.pointerType !== 'mouse') return;
  const b = activeBrush();
  if (isDrawTool(state.tool)) {
    brushCursor.style.display = 'block';
    updateBrushCursor(e, b);
  } else {
    brushCursor.style.display = 'none';
  }
}, { passive: true });

area.addEventListener('pointerleave', () => {
  brushCursor.style.display = 'none';
});

/* =================================================================
   CANVAS ROTATION — two-finger twist gesture
   ================================================================= */
state.canvasRotation = 0; // degrees
let _rotateStart = null;

function applyCanvasRotation() {
  const r = state.canvasRotation;
  paper.style.transform = `translate(-50%, -50%) scale(${state.zoom * state.baseZoom}) rotate(${r}deg)`;
  const badge = document.getElementById('rotation-badge');
  if (r === 0) {
    badge.classList.remove('show');
  } else {
    badge.textContent = `${Math.round(r)}°`;
    badge.classList.add('show');
  }
}

// Override applyStageTransform to include rotation
const _origApplyStageTransform = applyStageTransform;
function applyStageTransform() {
  stage.style.transform = `translate(${state.panX}px, ${state.panY}px)`;
  paper.style.transform = `translate(-50%, -50%) scale(${state.zoom * state.baseZoom}) rotate(${state.canvasRotation}deg)`;
  document.getElementById('zoom-level').textContent = Math.round(state.zoom * 100) + '%';
  refreshMeasurements();
}

// Detect rotation gesture: track angle between two touches
area.addEventListener('touchstart', (e) => {
  if (e.touches.length === 2) {
    const t1 = e.touches[0], t2 = e.touches[1];
    const angle = Math.atan2(t2.clientY - t1.clientY, t2.clientX - t1.clientX) * 180 / Math.PI;
    _rotateStart = { angle, rotation: state.canvasRotation };
  }
}, { passive: true });

area.addEventListener('touchmove', (e) => {
  if (e.touches.length === 2 && _rotateStart !== null) {
    const t1 = e.touches[0], t2 = e.touches[1];
    const angle = Math.atan2(t2.clientY - t1.clientY, t2.clientX - t1.clientX) * 180 / Math.PI;
    const delta = angle - _rotateStart.angle;
    state.canvasRotation = _rotateStart.rotation + delta;
    applyCanvasRotation();
  }
}, { passive: true });

area.addEventListener('touchend', () => {
  // Snap to 0° if within 8° — prevents accidental rotation
  if (Math.abs(state.canvasRotation) < 8) {
    state.canvasRotation = 0;
    applyCanvasRotation();
  }
  _rotateStart = null;
});

// Double-tap the rotation badge to reset to 0°
document.getElementById('rotation-badge').addEventListener('click', () => {
  state.canvasRotation = 0;
  applyCanvasRotation();
  showHint('Canvas rotation reset to 0°');
});

/* =================================================================
   DRAGGABLE PUCK
   ================================================================= */
(function initDraggablePuck() {
  const puck = document.getElementById('puck');
  const handle = document.getElementById('puck-drag-handle');
  if (!handle || !puck) return;

  let dragging = false, ox = 0, oy = 0;

  handle.addEventListener('pointerdown', (e) => {
    e.stopPropagation();
    handle.setPointerCapture(e.pointerId);
    dragging = true;
    const pr = puck.getBoundingClientRect();
    const ar = area.getBoundingClientRect();
    ox = e.clientX - pr.left;
    oy = e.clientY - pr.top;
    puck.style.transition = 'none';
    puck.style.bottom = 'unset';
    puck.style.left = (pr.left - ar.left) + 'px';
    puck.style.top  = (pr.top  - ar.top)  + 'px';
    puck.style.transform = 'none';
  });

  handle.addEventListener('pointermove', (e) => {
    if (!dragging) return;
    const ar = area.getBoundingClientRect();
    const newLeft = Math.max(0, Math.min(ar.width  - puck.offsetWidth,  e.clientX - ar.left - ox));
    const newTop  = Math.max(0, Math.min(ar.height - puck.offsetHeight, e.clientY - ar.top  - oy));
    puck.style.left = newLeft + 'px';
    puck.style.top  = newTop  + 'px';
  });

  handle.addEventListener('pointerup', () => { dragging = false; });
})();

