/* =================================================================
   AUTOSAVE — debounced persistence to IndexedDB so a crash, refresh,
   or accidental close never loses work. Stores a composite PNG per
   layer plus document metadata; restores on next launch.
   ================================================================= */
const AUTOSAVE_DB = 'nm-trace', AUTOSAVE_STORE = 'doc';
function autosaveKey() {
  return (typeof window !== 'undefined' && window.__SKETCHTRUDE_PROJECT_ID) || 'current';
}
let _autosaveTimer = null, _autosaveBusy = false, _autosaveSuspended = false, _autosaveSerial = 0;
let _autosaveWaiters = [];
let _idbPromise = null;

function waitForAutosave() {
  return new Promise((resolve) => _autosaveWaiters.push(resolve));
}

function notifyAutosaveWaiters() {
  const waiters = _autosaveWaiters.splice(0);
  waiters.forEach((resolve) => resolve());
}

function idb() {
  if (_idbPromise) return _idbPromise;
  _idbPromise = new Promise((resolve, reject) => {
    const req = indexedDB.open(AUTOSAVE_DB, 1);
    req.onupgradeneeded = () => {
      if (!req.result.objectStoreNames.contains(AUTOSAVE_STORE)) req.result.createObjectStore(AUTOSAVE_STORE);
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  }).catch(() => null);
  return _idbPromise;
}

// Discrete 3D massing edits (push/pull, regions, materials) are not continuous strokes,
// so they get a short debounce — a quick mid-session save, far safer than waiting for the
// 10s sketch debounce or the unreliable pagehide flush on a force-quit.
let _massSaveTimer = null;
function scheduleMassAutosave() {
  if (_autosaveSuspended) return;
  clearTimeout(_massSaveTimer);
  _massSaveTimer = setTimeout(() => { if (!state.drawing) saveDoc(); }, 1500);
}

function scheduleAutosave() {
  if (_autosaveSuspended) return;
  _autosaveSerial++;
  clearTimeout(_autosaveTimer);
  scheduleThumbnail();
  // Long idle debounce: during active sketching (changes every few seconds) this
  // keeps resetting, so autosave never fires in the gaps between strokes. It only
  // runs after a real pause. visibilitychange/pagehide + the periodic timer below
  // cover crash safety during long continuous sessions.
  _autosaveTimer = setTimeout(() => {
    if (state.drawing) { scheduleAutosave(); return; }
    if (window.requestIdleCallback) requestIdleCallback(() => saveDoc(), { timeout: 4000 });
    else saveDoc();
  }, 750);
}

// Periodic safety net for long pause-free sessions — only runs when idle and
// not drawing, so it can't stall a stroke.
setInterval(() => {
  if (_autosaveSuspended || state.drawing) return;
  if (!state.layers.some(l => l._dirty)) return;   // nothing changed since last save
  if (window.requestIdleCallback) requestIdleCallback(() => { if (!state.drawing) saveDoc(); }, { timeout: 4000 });
}, 45000);

// Deep-clone masses for disk persistence, stripping live image/canvas caches (rebuilt on render).
// faceArt dataURLs, faceRegions, depths and materials are plain data and are kept.
function massesForSave() {
  const skip = (k, v) => {
    if (typeof v === 'function') return undefined;
    if (typeof HTMLImageElement !== 'undefined' && v instanceof HTMLImageElement) return undefined;
    if (typeof HTMLCanvasElement !== 'undefined' && v instanceof HTMLCanvasElement) return undefined;
    if (typeof ImageBitmap !== 'undefined' && v instanceof ImageBitmap) return undefined;
    return v;
  };
  try { return JSON.parse(JSON.stringify(massing.masses || [], skip)); } catch (e) { return []; }
}
async function saveDoc() {
  if (_autosaveBusy) return waitForAutosave();
  if (_autosaveSuspended || !state.layers.length) return;
  if (state.drawing) { scheduleAutosave(); return; }   // defer until not drawing
  _autosaveBusy = true;
  const saveSerial = _autosaveSerial;
  try {
    // Only re-encode layers that actually changed since the last save.
    const layerData = [];
    for (const l of state.layers) {
      if (l._dirty || !l._savedBlob) {
        // Skip the temp-composite when the layer has no live (un-baked) image —
        // encode the drawing canvas directly. Most layers take this fast path.
        let sourceCanvas = l.canvas;
        if (l.imageCanvas && !l.imageBaked) {
          const tmp = document.createElement('canvas');
          tmp.width = DOC_W_PX; tmp.height = DOC_H_PX;
          const tc = tmp.getContext('2d');
          tc.drawImage(l.imageCanvas, 0, 0);
          tc.drawImage(l.canvas, 0, 0);
          sourceCanvas = tmp;
        }
        l._savedBlob = await new Promise(res => sourceCanvas.toBlob(res, 'image/png'));
        if (_autosaveSerial === saveSerial) l._dirty = false;
        await Promise.resolve();   // yield between layers
      }
      layerData.push({
        name: l.name, visible: l.visible, opacity: l.opacity,
        trace: l.trace, blendMode: l.blendMode,
        blob: l._savedBlob, raster_path: l._rasterPath || null,
      });
    }
    const payload = {
      version: 1, savedAt: Date.now(),
      doc: { wmm: DOC_W_MM, hmm: DOC_H_MM, dpi: DOC_DPI },
      infiniteCanvas: state.infiniteCanvas,
      autoExpandCanvas: state.autoExpandCanvas,
      paperBg: state.paperBg,
      grid: { show: state.showGrid, type: state.gridType, spacingMM: state.gridSpacingMM },
      activeLayer: state.activeLayer,
      pxPerUnit: state.pxPerUnit, scaleUnit: state.scaleUnit,
      scaleLabel: scaleLabelFromState(),
      measurements: state.measurements,
      walls: state.walls,
      wallsVisible: state.wallsVisible !== false,
      shapes: state.shapes,
      masses: massesForSave(),
      massBaseAnchor: massing.baseAnchor || null,
      layers: layerData,
    };
    const db = await idb();
    if (db) {
      await new Promise((resolve, reject) => {
        const tx = db.transaction(AUTOSAVE_STORE, 'readwrite');
        tx.objectStore(AUTOSAVE_STORE).put(payload, autosaveKey());
        tx.oncomplete = resolve; tx.onerror = () => reject(tx.error);
      });
    }
    _lastDocPayload = payload;
    scheduleCloudSync();
  } catch (e) {
    console.warn('Autosave failed:', e);
  } finally {
    _autosaveBusy = false;
    notifyAutosaveWaiters();
    if (_autosaveSerial !== saveSerial && !state.drawing) scheduleAutosave();
  }
}

let _lastDocPayload = null;
let _cloudSyncTimer = null;
let _cloudSyncInFlight = false;
let _cloudSyncWaiters = [];

function waitForCloudSync() {
  return new Promise((resolve) => _cloudSyncWaiters.push(resolve));
}

function notifyCloudSyncWaiters() {
  const waiters = _cloudSyncWaiters.splice(0);
  waiters.forEach((resolve) => resolve());
}

function scheduleCloudSync() {
  if (!_lastDocPayload) return;
  clearTimeout(_cloudSyncTimer);
  _cloudSyncTimer = setTimeout(() => { flushCloudSync(); }, 2500);
}

async function uploadLayerRaster(pid, index, blob) {
  const fd = new FormData();
  fd.append('layer_index', String(index));
  fd.append('raster', blob, 'layer-' + index + '.png');
  const res = await fetch('/api/projects/' + pid + '/document/layer', {
    method: 'POST',
    body: fd,
    credentials: 'same-origin',
  });
  if (!res.ok) {
    const errText = await res.text().catch(() => '');
    console.warn('Layer upload failed:', index, res.status, errText);
    return null;
  }
  const data = await res.json();
  return data.raster_path || null;
}

async function flushCloudSync() {
  const pid = typeof window !== 'undefined' ? window.__SKETCHTRUDE_PROJECT_ID : null;
  if (_cloudSyncInFlight) {
    await waitForCloudSync();
    return flushCloudSync();
  }
  if (!pid || pid === 'local' || !_lastDocPayload) return;
  _cloudSyncInFlight = true;
  try {
    const payload = _lastDocPayload;
    const layerMeta = [];
    for (let i = 0; i < payload.layers.length; i++) {
      const l = payload.layers[i];
      let raster_path = l.raster_path || null;
      if (l.blob && l.blob.size > 0) {
        const uploaded = await uploadLayerRaster(pid, i, l.blob);
        if (!uploaded) {
          console.warn('Cloud save skipped: missing uploaded raster for layer', i);
          return;
        }
        raster_path = uploaded;
        const live = state.layers[i];
        if (live) live._rasterPath = uploaded;
        l.raster_path = uploaded;
      }
      layerMeta.push({
        name: l.name,
        visible: l.visible,
        opacity: l.opacity,
        trace: l.trace,
        blendMode: l.blendMode,
        raster_path,
      });
    }
    const manifest = {
      version: payload.version,
      savedAt: payload.savedAt,
      doc: payload.doc,
      infiniteCanvas: payload.infiniteCanvas,
      autoExpandCanvas: payload.autoExpandCanvas,
      paperBg: payload.paperBg,
      grid: payload.grid,
      activeLayer: payload.activeLayer,
      pxPerUnit: payload.pxPerUnit,
      scaleUnit: payload.scaleUnit,
      scaleLabel: payload.scaleLabel,
      measurements: payload.measurements,
      walls: payload.walls,
      wallsVisible: payload.wallsVisible,
      shapes: payload.shapes,
      masses: payload.masses,
      massBaseAnchor: payload.massBaseAnchor,
      layers: layerMeta,
      layer_count: layerMeta.length,
    };
    const res = await fetch('/api/projects/' + pid + '/document', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify(manifest),
    });
    if (!res.ok) {
      const errText = await res.text().catch(() => '');
      console.warn('Cloud save failed:', res.status, errText);
    }
  } catch (e) {
    console.warn('Cloud save failed:', e);
  } finally {
    _cloudSyncInFlight = false;
    notifyCloudSyncWaiters();
  }
}

async function loadCloudDocument() {
  const pid = typeof window !== 'undefined' ? window.__SKETCHTRUDE_PROJECT_ID : null;
  if (!pid || pid === 'local') return null;
  try {
    const res = await fetch('/api/projects/' + pid + '/document', { credentials: 'same-origin' });
    if (!res.ok) return null;
    const data = await res.json();
    if (!data || !data.layers || !data.layers.length) return null;
    const layers = [];
    for (const ld of data.layers) {
      const entry = {
        name: ld.name,
        visible: ld.visible,
        opacity: ld.opacity,
        trace: ld.trace,
        blendMode: ld.blendMode,
        blob: null,
      };
      if (ld.raster_url) {
        try {
          const imgRes = await fetch(ld.raster_url);
          if (imgRes.ok) entry.blob = await imgRes.blob();
        } catch (_) { /* skip layer image */ }
      }
      layers.push(entry);
    }
    return Object.assign({}, data, { layers });
  } catch (e) {
    console.warn('Cloud load failed:', e);
    return null;
  }
}

async function loadSavedDoc() {
  const db = await idb();
  if (!db) return null;
  return new Promise((resolve) => {
    const tx = db.transaction(AUTOSAVE_STORE, 'readonly');
    const req = tx.objectStore(AUTOSAVE_STORE).get(autosaveKey());
    req.onsuccess = () => resolve(req.result || null);
    req.onerror = () => resolve(null);
  });
}

function savedDocHasPixels(doc) {
  return !!doc?.layers?.some((layer) => layer?.blob && layer.blob.size > 0);
}

function savedDocHasVectors(doc) {
  return ['measurements', 'walls', 'shapes', 'masses'].some((key) => Array.isArray(doc?.[key]) && doc[key].length > 0);
}

function isRestorableDoc(doc) {
  return !!doc?.layers?.length && (savedDocHasPixels(doc) || savedDocHasVectors(doc));
}

function chooseSavedDoc(localDoc, cloudDoc) {
  const localRestorable = isRestorableDoc(localDoc);
  const cloudRestorable = isRestorableDoc(cloudDoc);
  if (localRestorable && !cloudRestorable) return localDoc;
  if (cloudRestorable && !localRestorable) return cloudDoc;
  if (localRestorable && cloudRestorable) {
    const localSavedAt = Number(localDoc.savedAt) || 0;
    const cloudSavedAt = Number(cloudDoc.savedAt) || 0;
    return cloudSavedAt > localSavedAt ? cloudDoc : localDoc;
  }
  return cloudDoc || localDoc;
}

async function clearSavedDoc() {
  const db = await idb();
  if (!db) return;
  const tx = db.transaction(AUTOSAVE_STORE, 'readwrite');
  tx.objectStore(AUTOSAVE_STORE).delete(autosaveKey());
}

function removeAllLayers() {
  state.layers.forEach(l => {
    if (l.canvas && l.canvas.parentNode) l.canvas.parentNode.removeChild(l.canvas);
    if (l.imageCanvas && l.imageCanvas.parentNode) l.imageCanvas.parentNode.removeChild(l.imageCanvas);
  });
  state.layers = [];
}

// Returns true if a session was restored.
async function restoreSession() {
  let cloudSaved = null, localSaved = null;
  try { localSaved = await loadSavedDoc(); } catch { localSaved = null; }
  try { cloudSaved = await loadCloudDocument(); } catch { cloudSaved = null; }
  const saved = chooseSavedDoc(localSaved, cloudSaved);
  if (!saved || !saved.layers || !saved.layers.length) return false;
  _autosaveSuspended = true;
  try {
    // Apply document dimensions
    DOC_W_MM = saved.doc.wmm; DOC_H_MM = saved.doc.hmm; DOC_DPI = saved.doc.dpi;
    DOC_W_PX = Math.round(DOC_W_MM / 25.4 * DOC_DPI);
    DOC_H_PX = Math.round(DOC_H_MM / 25.4 * DOC_DPI);
    strokeCanvas.width = DOC_W_PX; strokeCanvas.height = DOC_H_PX;
    const gc = document.getElementById('guide-canvas'); gc.width = DOC_W_PX; gc.height = DOC_H_PX;
    gridCanvas.width = DOC_W_PX; gridCanvas.height = DOC_H_PX;

    removeAllLayers();
    for (const ld of saved.layers) {
      const layer = createLayer(ld.name);   // pushes + creates canvases at current DOC size
      layer.visible = ld.visible; layer.opacity = ld.opacity;
      layer.trace = ld.trace || 0; layer.blendMode = ld.blendMode || 'source-over';
      if (ld.blob) {
        try {
          const bmp = await createImageBitmap(ld.blob);
          layer.ctx.drawImage(bmp, 0, 0);
          bmp.close && bmp.close();
        } catch (_) { /* skip a corrupt layer image */ }
      }
      // reset history to this restored state
      layer.history = []; layer.redo = [];
      saveSnapshot(layer);
    }
    state.activeLayer = Math.min(saved.activeLayer ?? state.layers.length - 1, state.layers.length - 1);
    if (saved.pxPerUnit) { state.pxPerUnit = saved.pxPerUnit; state.scaleUnit = saved.scaleUnit || 'cm'; }
    else if (saved.scaleLabel) applyScaleFromLabel(saved.scaleLabel);
    updateScaleDisplay();
    if (saved.infiniteCanvas != null) state.infiniteCanvas = !!saved.infiniteCanvas;
    if (saved.autoExpandCanvas != null) state.autoExpandCanvas = !!saved.autoExpandCanvas;
    if (saved.paperBg) { state.paperBg = saved.paperBg; if (paper) paper.style.background = saved.paperBg; }
    if (saved.grid) {
      state.showGrid = !!saved.grid.show;
      state.gridType = saved.grid.type || state.gridType;
      if (saved.grid.spacingMM) state.gridSpacingMM = saved.grid.spacingMM;
      drawDocGrid();
    }
    if (Array.isArray(saved.measurements)) state.measurements = saved.measurements;
    if (Array.isArray(saved.walls)) state.walls = saved.walls;
    state.wallsVisible = saved.wallsVisible != null ? !!saved.wallsVisible : true;
    if (Array.isArray(saved.shapes)) state.shapes = saved.shapes;
    if (Array.isArray(saved.masses)) { massing.masses = saved.masses; massing.selected = -1; }
    if (saved.massBaseAnchor) massing.baseAnchor = saved.massBaseAnchor;
    if (typeof syncWallsToMasses === 'function') syncWallsToMasses();
    fitToScreen();
    updateLayerOrder(); renderLayers(); updateUI();
    refreshMeasurements(); renderSchedule();
    return true;
  } catch (e) {
    console.warn('Restore failed, starting fresh:', e);
    return false;
  } finally {
    _autosaveSuspended = false;
  }
}

// Save on page hide/close as a final safety net (debounce may not have fired)
window.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'hidden') {
    saveDoc().then(() => flushCloudSync());
    scheduleThumbnail();
  }
});
window.addEventListener('pagehide', () => {
  saveDoc().then(() => flushCloudSync());
  scheduleThumbnail();
});

window.addEventListener('message', async (e) => {
  if (e.data?.type === 'sketchtrude-save') {
    try {
      for (let i = 0; i < 30; i++) {
        await saveDoc();
        if (_lastDocPayload && !_autosaveBusy && !state.layers.some(l => l._dirty)) break;
        await new Promise((r) => setTimeout(r, 100));
      }
      clearTimeout(_cloudSyncTimer);
      await flushCloudSync();
      scheduleThumbnail();
    } catch (_) {}
    if (window.parent !== window) {
      window.parent.postMessage({
        type: 'sketchtrude-save-done',
        projectId: window.__SKETCHTRUDE_PROJECT_ID,
      }, '*');
    }
  }
});

let _scaleSyncTimer = null;
function syncProjectScale(label) {
  const pid = typeof window !== 'undefined' ? window.__SKETCHTRUDE_PROJECT_ID : null;
  if (!pid || pid === 'local' || !label) return;
  const cfg = window.__SKETCHTRUDE_PROJECT_CONFIG;
  if (cfg) cfg.scale_label = label;
  clearTimeout(_scaleSyncTimer);
  _scaleSyncTimer = setTimeout(async () => {
    try {
      await fetch('/api/projects/' + pid, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ scale_label: label }),
        credentials: 'same-origin',
      });
    } catch (_) { /* offline — IDB still has scale */ }
  }, 400);
}

function scaleLabelFromState() {
  if (!state.pxPerUnit || !state.scaleUnit) return null;
  const unitInMm = { mm:1, cm:10, m:1000, in:25.4, ft:304.8 }[state.scaleUnit] || 1;
  const realPerPx_mm = unitInMm / state.pxPerUnit;
  const docPxPerMm = DOC_W_PX / DOC_W_MM;
  const ratio = realPerPx_mm * docPxPerMm;
  if (!ratio || ratio <= 0) return null;
  return `1:${Math.round(ratio)}`;
}

function updateScaleDisplay() {
  const label = scaleLabelFromState();
  const el = document.getElementById('scale-text');
  if (el && label) el.textContent = label.replace(/\s+/g, '');
  return label;
}

function applyScaleFromLabel(label) {
  if (!label || state.pxPerUnit) return;
  const m = String(label).match(/1\s*:\s*(\d+(?:\.\d+)?)/);
  if (!m) return;
  const ratio = parseFloat(m[1]);
  if (!ratio || ratio <= 0) return;
  const docPxPerMm = DOC_W_PX / DOC_W_MM;
  state.pxPerUnit = (10 * docPxPerMm) / ratio;
  state.scaleUnit = 'cm';
  updateScaleDisplay();
}

function applyProjectConfig() {
  const cfg = typeof window !== 'undefined' ? window.__SKETCHTRUDE_PROJECT_CONFIG : null;
  if (!cfg) return;
  const meta = cfg.metadata || {};
  if (cfg.doc_width_mm > 0 && cfg.doc_height_mm > 0) {
    DOC_W_MM = cfg.doc_width_mm;
    DOC_H_MM = cfg.doc_height_mm;
    DOC_DPI = cfg.doc_dpi || DOC_DPI;
    DOC_W_PX = Math.round(DOC_W_MM / 25.4 * DOC_DPI);
    DOC_H_PX = Math.round(DOC_H_MM / 25.4 * DOC_DPI);
    if (paper) {
      paper.style.width = DOC_W_PX + 'px';
      paper.style.height = DOC_H_PX + 'px';
      if (state.paperBg) paper.style.background = state.paperBg;
    }
    if (typeof strokeCanvas !== 'undefined' && strokeCanvas) {
      strokeCanvas.width = DOC_W_PX;
      strokeCanvas.height = DOC_H_PX;
    }
    const gc = document.getElementById('guide-canvas');
    if (gc) { gc.width = DOC_W_PX; gc.height = DOC_H_PX; }
    if (typeof gridCanvas !== 'undefined' && gridCanvas) {
      gridCanvas.width = DOC_W_PX;
      gridCanvas.height = DOC_H_PX;
    }
    updateDocInfo(paperFormatName(DOC_W_MM, DOC_H_MM));
  }
  if (meta.infinite_canvas || cfg.infinite_canvas) state.infiniteCanvas = true;
  state.autoExpandCanvas = !!(
    meta.auto_expand ||
    meta.infinite_canvas ||
    cfg.infinite_canvas
  );
  // Older projects created before auto_expand metadata — expand by default
  if (
    meta.auto_expand === undefined &&
    meta.infinite_canvas === undefined &&
    !cfg.infinite_canvas
  ) {
    state.autoExpandCanvas = true;
  }
  const bg = meta.paper_bg;
  if (bg) {
    state.paperBg = bg;
    if (paper) paper.style.background = bg;
  }
  if (meta.show_grid) {
    state.showGrid = true;
    state.gridType = meta.grid_type || 'square';
    if (meta.grid_spacing_mm) state.gridSpacingMM = meta.grid_spacing_mm;
  }
  if (meta.guide_type) {
    state.guideType = meta.guide_type;
    if (meta.guide_opacity != null) state.guideOpacity = meta.guide_opacity;
  }
}

function toggleSymmetry() {
  const order = [null, 'vertical', 'horizontal'];
  const idx = order.indexOf(state.symmetryAxis);
  state.symmetryAxis = order[(idx + 1) % order.length];
  const labels = { vertical: 'Vertical symmetry', horizontal: 'Horizontal symmetry' };
  showHint(state.symmetryAxis ? labels[state.symmetryAxis] + ' ON' : 'Symmetry off');
  const btn = document.getElementById('ovf-symmetry');
  if (btn) btn.classList.toggle('active', !!state.symmetryAxis);
}

/* =================== BOOT =================== */
applyProjectConfig();
loadStencils();
loadHatches();
loadFillTextures();
loadBrushes();
fitToScreen();
createLayer('Base');
createLayer('Sketch 01');
state.activeLayer = 1;
updateLayerOrder();
renderLayers();
updateUI();
renderSwatches();
setActiveBrush(BUILTIN_BRUSHES[0]);
regroupRail();
updatePreview();
initWheelEvents();
syncWheelFromColor(state.color);
injectHatchTab();
// Init guide canvas to correct doc size
const _gc = document.getElementById('guide-canvas');
if (_gc) { _gc.width = DOC_W_PX; _gc.height = DOC_H_PX; }
// Init grid canvas
gridCanvas.width = DOC_W_PX; gridCanvas.height = DOC_H_PX;
drawDocGrid();
if (state.guideType && state.guideType !== 'none' && typeof drawGuideGrid === 'function') drawGuideGrid();

const ovfSym = document.getElementById('ovf-symmetry');
if (ovfSym) ovfSym.addEventListener('click', () => { toggleSymmetry(); overflowPanel.classList.remove('show'); });

// Attempt to restore the last session (replaces the default layers if found).
restoreSession().then(restored => {
  if (restored) {
    const label = scaleLabelFromState();
    if (label) syncProjectScale(label);
    scheduleThumbnail();
    setTimeout(() => showHint('Restored your last session'), 400);
  } else {
    const cfg = typeof window !== 'undefined' ? window.__SKETCHTRUDE_PROJECT_CONFIG : null;
    if (cfg?.scale_label) applyScaleFromLabel(cfg.scale_label);
  }
});

setTimeout(() => {
  showHint('SketchTrude · 2-finger tap = undo · 3-finger tap = redo · UI hides while drawing');
}, 600);

setTimeout(() => scheduleThumbnail(), 1800);

